INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Фаҳмед, чӣ тавр ҳаҷми ҳосили сабзадорӣ (спинач) дар ҳар ҳектарро бо истифода аз усули нақши Тип зиёд кардан мумкин аст. Ин раҳнамои пурра дастурҳои амалӣ барои зиёд кардани самаранокӣ ва самаранокии кишоварӣ-иқтисодиро пешниҳод мекунад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','Ҳаҷми ҳосили сабзадорӣ дар ҳектар бо нақши Тип: Раҳнамои пурра барои зиёд кардани самаранокӣ' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='tj' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
COMMIT;

START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-002' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-002:ar-IQ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='pest-disease-management-pulse-drip-systems-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'pest-disease-management-pulse-drip-systems-guide','pest-disease-management-pulse-drip-systems-guide-crop-002-iraq');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'pest-disease-management-pulse-drip-systems-guide-crop-002-iraq-1a9d71db');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>عدس من أهم البقوليات في القطاع الزراعي، ورغم مقاومته النسبي للجفاف، فإنه حساس للغاية للرطوبة النسبية العالية على سطح التربة وكذلك داخل الوطاء النباتي (canopy). التحول من الري السطحي التقليدي إلى <strong>الري بالتنقيط</strong> أو <strong>النظام الأنبوبي</strong>، ليس مجرد وسيلة لتقليل استهلاك المياه، بل هو أداة إدارة قوية للتحكم في <strong>آفات ومزارع العدس</strong> يُعد أساسياً. في هذا القسم، نغوص أكثر في كيفية ضبط رطوبة التربة بدقة من أجل السيطرة على انتشار الأمراض. المبادئ الفنية لتثبيت النظام وصيانته هي الأساس الرئيسي لإدارة هذا النظام.</p>\n<h2>تأثير الري بالتنقيط على البيئة المحيطة بنبات العدس</h2>\n<p>نبات العدس حساس جداً للأمراض الفطرية والبكتيرية، خاصة عندما تكون رطوبة سطح التربة مرتفعة لفترات طويلة. في الري بالتنقيط، يُحقن الماء فقط إلى جذور النبات والشرطة الضيقة المحيطة بالغرسات. هذه الطريقة تجعل سطح التربة بين الصفوف يظل جافاً. انخفاض الرطوبة النسبية على سطح التربة يمنع تشكيل الظروف المثالية لنمو تعفنات قاعدة الساق والأمراض الترابية. وبالتالي، <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">التثبيت الصحيح للنظام الأنبوبي</a> يلعب دوراً حيوياً في تحديد المنطقة الرطبة بدقة لمنع تبلل الأوراق أو قواعد السيقان بشكل مفرط. التداخل الصحيح بين النطاق والتوزيع الجذري هو مفتاح النجاح في هذه المرحلة.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-عدس-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های عدس با آبیاری قطره‌ای - تصویر 1"/><figcaption>آفات المحاصيل وأمراض الري بالتنقيط عدس</figcaption></figure>\n<h2>إدارة الأمراض الفطرية عبر التحكم في الرطوبة</h2>\n<p>أمراض مثل الصدأ (Rust) في العدس، رغم أنها تنتقل غالباً عبر الهواء، إلا أن تطورها وشدة ارتبطت بشكل كبير بالرطوبة الموجودة في البيئة الميكروية للنبات. باستخدام نظام التنقيط، تنخفض الرطوبة النسبية المحلية حول قاعدة النبات. هذا الأمر يترافق مباشرة مع انخفاض نشاط الفطريات التي تحتاج إلى وسط رطب لانتشار بذورها. المزارعون يمكنهم من خلال ضبط فترات الري بحيث لا تُغرق التربة بالمياه، منع انتشار الأمراض الترابية مثل الفوساريوم (Fusarium)، وهو عارض مضر لجذور العدس. الإدارة الدقيقة للتغذية تصبح أيضاً ممكنة عبر الري بالتنقيط (Fertigation)، مما يزيد من سلامة النبات ويعزز المقاومة النظامية (ISR) ضد الآفات. لفهم أفضل للربط بين الإدارة الزراعية والإنتاج، دراسة دليل <a href="https://navar-abyari.ir/garlic-yield-per-hectare-factors-increase-36780-2/">زيادة إنتاجية الثوم للهكتار</a> قد تقدم نماذج قابلة للتعميم لبقية البقوليات.</p>\n<h2>دور صحة التربة في تقليل الآفات الجذرية</h2>\n<p>من أبرز التحديات في مزارع العدس وجود آفات جذرية مثل العناكب وديدان التربة. لأن الري بالتنقيط يركز الري في منطقة الجذور، يمكنه منع انتشار بعض الآفات السطحية التي تحتاج إلى بيئة رطبة عامة. أيضاً، استخدام النقاط التنقيطية لحقن المواد المبيدات الحيوية أو البيولوجية إلى الجذور، يمكن أن يساعد بطريق مباشر في مكافحة الآفات الدفينة. إن أردت فهم أفضل لبنية معداتها، فراجع المقالات المتعلقة بـ <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">تثبيت شريط الري</a> استشرى خبيراً حتى تحصل على رؤية شاملة لتأثير الإدارة على المردود. فهم عملية التصاق الشريط بطبقة التربة يضمن توزيعاً متجانساً للماء.</p>\n<h2>آفات حشرية وإدارة تجمعاتها</h2>\n<p>رغم أن الري بالتنقير لا يقضي على الحشرات مباشرة، إلا أن تغيير نمط الري قد يبدل أنماط هجرة بعض الآفات. فبعض الحشرات الممرضة والذبابت البيضاء تميل إلى الاقتراب من المناطق الرطبة في التربة. عن طريق الحفاظ على جفاف نسبي بين الصفوف، ينخفض تركيز هذه الآفات في سطح التربة. فضلاً عن ذلك، يقلل انخفاض الرطوبة المحيطة حول النباتات من تعزيز نشاط الكائنات الطفيلية (Parasitoids) من حيث استقرار موائلها. يجب أن تبدأ الإدارة المتكاملة للآفات (IPM) في أنظمة التنقير برعاية الصحة العامة للمحصول؛ فمحصول لا يتأثر بإجهاد شديد لنقص الماء أو بالغرغرة (Waterlogging) يستجيب بشكل أفضل لمقاوماته الدفاعية. تحديد نوع الآفة بدقة هو الخطوة الأولى لمكافحتها.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-عدس-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های عدس با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation عدس</figcaption></figure>\n<h2>نقاط عملية للمزارع في زراعة العدس</h2>\n<p>للاستفادة من مزايا الري بالتنقير في مواجهة آفات أمراض العدس، من الضروري مراعاة النقاط التالية:</p>\n<ul>\n  <li><strong>اختيار قطر و مسافة الشريط/المقطرة:</strong> يجب أن يتناسب المسافة بين النقاطات مع أبعاد جذور العدس. جذور العدس سطحية، لذا يجب أن يركز النظام الرطوبة في ۲۰ إلى ۳۰ سنتيمتراً الأولى من التربة.</li>\n  <li><strong>استخدام فلاتر دقيقة:</strong> قد تدخل الملوثات الميكروبية في الماء إلى التربة عبر شريط الري. من الضروري استخدام فلاتر دقيقة (Fine Mesh) أو أصفاف لمنع انسداد النقاطات ونقل الأمراض المعتمدة على الماء.</li>\n  <li><strong>تنفيذ التسميد عبر الري (Fertigation):</strong> التغذية عبر التنقير تتيح حقن مبيدات الفطريات التربة أو مبيدات الآفات الجهازية. لمزيد من المعلومات حول المعدات الثانوية، <a href="https://navar-abyari.ir/tips-before-buying-drip-tape-irrigation-iq/">نقاط قبل شراء شريط التنقير</a> راجعها. فحص جودة شريط الري قبل الشراء يمنع إهدار رأس المال.</li>\n  <li><strong>تجنب بقاء أوراق النباتات مبللة:</strong> في حالة استخدام شريط الري، تأكد من أن الشريط مثبت تحت مظلة النبات تماماً حتى لا تنتقل الرطوبة إلى الأوراق التي تكون موطناً للعنيد (Pleurochaetopterus) والفطريات.</li>\n</ul>\n<h3>جدول زمني لفحص الأمراض الشائعة</h3>\n<table>\n  <thead>\n    <tr>\n      <th>مرحلة النمو</th>\n      <th>المرض/الإصابة الهدف</th>\n      <th>أثر الري بالتنقيط</th>\n      <th>ملاحظة في الإدارة</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>البرعم</td>\n      <td>تعفن البذور والشتلات</td>\n      <td>تقليل المخاطر بسبب الجفاف في مسافات بين الصفوف</td>\n      <td>زراعة بذور معقمة، ري خفيف ومستمر</td>\n    </tr>\n    <tr>\n      <td>النمو الخضري</td>\n      <td>عث العنكبوت، تعفن الجذر</td>\n      <td>إدارة الرطوبة المحلية، تقليل انتشار التعفن</td>\n      <td>مراقبة بصرية تحت الأدغال، استخدام مواد حيوية تربة</td>\n    </tr>\n    <tr>\n      <td>إنتاج الحبوب</td>\n      <td>الصُدَأ (Rust)</td>\n      <td>تقليل الرطوبة النسبية المحلية، تقليل شدة إطلاق الأبواغ</td>\n      <td>إيقاف مؤقت للري قبل الحصاد لإسقاط الحبوب، إزالة بقايا النباتات</td>\n    </tr>\n  </tbody>\n</table>\n<p>يجب الانتباه إلى أن نظام الري بالتنقيط ليس علاجًا بحد ذاته، بل هو إجراء وقائي. إزالة بقايا الحمّص من الحقل والصرف المناسب للحقل عاملان رئيسيان يعملان بالتزامن مع الري بالتنقيط لكسر دورة حياة المرض. في المناطق التي تعاني من رطوبة زائدة، يمكن أن يكون للجمع بين الري بالتنقيط وتحسين التربة تأثير علاجي مضاعف. الفهم لمبادئ الري الأخرى للمحاصيل الزراعية، مثل دليل شريط الري للبطيخ، يمكن أن يوفر رؤى قيمة حول التكيف التقني للأنظمة مع احتياجات نباتية مختلفة.</p>\n<h2>أجابات على الأسئلة الشائعة (FAQ)</h2>\n<ol>\n  <li><strong>هل يؤدي الري بالتنقيط إلى زيادة السعر النهائي للمحصول؟</strong><br>لا بالضرورة. على الرغم من أن التكلفة الأولية للمعدات أعلى، إلا أن تكلفة مبيدات الفطريات وفائض الماء وأجور الري تنخفض. كما أن تحسين جودة المحصول الناتج عن تقليل تلوثات التربة يمكن أن يساهم في زيادة جاذبيته للسوق وسعر التجزئة.</li>\n  <li><strong>ما نوع المرشح الموصى به للعدس؟</strong><br>العدس له جذور دقيقة، كما أن الأنبوب الشرياني يحتوي على ثقوب صغيرة. يوصى باستخدام مرشحات قرصية كثافتها 60 إلى 120 أو مرشحات شبكية بفتحات 120 للحظة، لمنع دخول الجزيئات الدقيقة إلى النظام.</li>\n  <li><strong>هل يمكن استخدام مبيد الأعشاب عن طريق التنقيط كإجراء وقائي؟</strong><br>استخدام الإثراء للتحكم في الأعشاب (Herbicide) في نظام التنقيط شديد الخطورة وقد يسبب أضراراً جسيمة للناتج الرئيسي. يجب مكافحة الأعشاب بوسائل ميكانيكية أو برش سطحي موجه، وليس عبر قطرات التنقيط.</li>\n  <li><strong>ما تأثير الري بالتنقيط على التربة والخنافس الأرضية؟</strong><br>الخنافس المفيدة في التربة التي تعتمد على رطوبة التربة قد يكون نشاطها أقل في المناطق الجافة بين نقاط التنقيط. قد يؤدي هذا إلى تغيير التوازن الميكروبي للتربة. يوصى بمراقبة صحية التربة باستمرار لتعويض هذا الأثر. لفهم أفضل لإدارة المزرعة، يمكنك الاستعانة بالدليل <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">تركيب الشريط الشرياني</a> استفاده کنید از بهینه‌سازی شرایط خاک.</li>\n</ol>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-عدس-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های عدس با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation عدس</figcaption></figure>\n<h2>جمع‌بندی و توصیه نهایی</h2>\n<p>انتقال عدس از آبیاری کلاسیک به سیستم‌های قطره‌ای یا نوار تیپ، یکی از هوشمندانه‌ترین تصمیمات برای مدیریت <strong>آفات و بیماری‌های عدس</strong> است. با کاهش رطوبت سطحی، کاهش استرس زیستی گیاه و امکان مدیریت دقیق‌تر تغذیه، کشاورز یک لایه دفاعی پنهان در برابر بیماری‌های خاکی و قارچی ایجاد می‌کند. با این حال، این فناوری باید در کنار دانش زراعی‌های محلی و پایش دقیق توسط کارشناس گیاه‌پزشکی اجرا شود. از آنجایی که کیفیت سیستم آبیاری مستقیماً بر سلامت محصول تأثیر می‌گذارد، حتماً در مراحل نصب، دقت به جزئیات فنی داشته باشید. برای اطلاع از روش‌های نصب اصولی‌تر، مراجعه به مطالب تخصصی مانند <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">نصب نوار تیپ</a> پیشنهاد می‌شود. در نهایت، تکیه بر سیستم‌های هوشمند مانیتورینگ رطوبت خاک می‌تواند بازه‌های آبیاری را بهینه‌تر کند و در بلندمدت، ریسک بیماری‌ها را به حداقل برساند. آشنایی با منابع آب و مدیریت بارش‌ها نیز می‌تواند به درک عمیق‌تر چرخه‌های آب در مزارع منجر شود، همان‌طور که در مقالاتی مانند <a href="https://navar-abyari.ir/gafsii-devori-lentai-obyorii-qatragi/">مقادیر آبیاری نوار تیپ</a> تم عرضه.</p>','إدارة الآفات وأمراض العدس في أنظمة الري بالتنقيط: دليل شامل للمزارعين','يتناول هذا المقال كيف يمكن أن تلعب الري بالتنقيط دورًا حاسمًا في تقليل مخاطر الإصابة بأحماض عدس وأمراض فطرية وبكتيرية. من خلال استكشاف المبادئ التقنية، من اختيار المعدات إلى تخطيط الري، ستتعلم تحسين الإدارة الزراعية للحصول على محصول أصح.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
