SET @resolved_slug=IF(@slug_conflict IS NULL,'idorokunii-zarorovarmo-va-bemorihoi-nuhur-dar-systemahoi-obori-bozgashtnak','idorokunii-zarorovarmo-va-bemorihoi-nuhur-dar-systemahoi-obori-bozgashtnak-crop-002-tj');
