SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='cucumber-seed-rate-per-hectare-sowing-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'cucumber-seed-rate-per-hectare-sowing-irrigation-guide','cucumber-seed-rate-per-hectare-sowing-irrigation-guide-crop-006-en');
