SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='idarokunii-zararroson-o-bemorihoi-beshuk' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'idarokunii-zararroson-o-bemorihoi-beshuk','idarokunii-zararroson-o-bemorihoi-beshuk-crop-008-tj');
