SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='alfalfa-pest-disease-management-precision-irrigation' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'alfalfa-pest-disease-management-precision-irrigation','alfalfa-pest-disease-management-precision-irrigation-crop-010-en');
