SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='melon-yield-per-hectare-drip-irrigation' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'melon-yield-per-hectare-drip-irrigation','melon-yield-per-hectare-drip-irrigation-crop-020-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
