START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-022' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-022:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='idarokunon-bodoi-zararavandho-opimimizatsiya-sistemi-agroznoi' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'idarokunon-bodoi-zararavandho-opimimizatsiya-sistemi-agroznoi','idarokunon-bodoi-zararavandho-opimimizatsiya-sistemi-agroznoi-crop-022-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'idarokunon-bodoi-zararavandho-opimimizatsiya-sistemi-agroznoi-crop-022-tj-94692637');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Вобастагии мустақими намоллои хушок ва саломатии решаҳо дар булбул</h2><p>Баҳорӣ (Ocimum basilicum) ҳамчун яке аз бисёр пардозиидашудагин гиҳаҳои хушбӯ ва тиббӣ дар саноати ғизоӣ барои рушди бевосита ба шароити ҳосилпазирии муҳим ниёз дорад. Ин гиҳаи дилхоҳ, ба нафъи бисёр сабзавотҳои дигар, таҳаммули ҳаракати назарнок ба хушкшавии хок надорад. Решаҳои баҳорӣ сатҳӣ мебошанд ва ба пур шудани ҳаракати давоми оксиген ва намнокии мувозинатӣ вобастаанд. Вақте ки ҳаракати обнокӣ идора карда нашавад, аз оксиген камшавии хок ба вуҷуд меояд ва муҳити муносиб барои наслкунии занбӯронҳое, ба монанди <em>Pythium</em> ва <em>Fusarium</em> майдон фароҳам меояд. Ин занбӯронҳо сабабкунандаи асосии кофтани реша мебошанд, ки метавонанд дар дамои чанд рӯз тамоми баҳоро нобуд созанд. Бинобар ин, ҳалли ҳаракатҳои зомии ҳашорот ва бемориҳои баҳор бе дида ба технологияи обнокӣ нокомил аст. Системаҳои маҳаллӣ, ба монанди чангобнокӣ ва пардаи чандирӣ, бо маркази намнокӣ дар минтақаи реша ва хушк кардани байни резҳо, хатти дифои физикиро дар муқобили ҳаракати патогенҳо эҷод мекунанд.</p><p>Дар идомаи ин дастури ихтисосӣ, ба техникаҳои иҷроӣ амиқтар даромада, муайян мекунем, ки чӣ тавр бо истифода аз стресси обнокӣ барои зиёд кардани муқовимати табиии гиҳа фоида бароранд ва чӣ тавр бо ислоҳи низоми ғизоӣ тавассути каналҳои обнокӣ, тоқҳҳои кимиёвиро барои ҳашорот нобуд кунем. Ин роҳкарди якпорча, ба ҷои такяи маҳдуд ба ҳашороткунии системавӣ, ҳалли бехататар барои кишоварзии муосир аст.</p>\n\n<h2>Таъсири дақиқи системаи чангобнокӣ дар пешгирии кофтани реша</h2><p>Бемории кофтани реша ё «порог» дар баҳор, одатан дар фаслҳои бадобнокӣ ё дар натиҷаи обнокии ҳаҷмии зиёд, маъмул аст. Вақте ки аз ноқилҳои пахтанда ё обнокии сатҳӣ истифода мебаранд, об ба таври якхела дар тамоми ҳаҷми хок паҳн мешавад. Ин падида боиси вуҷуди қабати хок намнок ва вазнин мебошад, ки нопардаи ҳаво ба онҳоро бозмедорад. Дар ин муҳити беҳаво, решаҳои баҳор барои нафас кашидан мушкилӣ доранд ва системаи иммунии гиҳа заиф мешавад. Баъд зараррасонии бемории занбӯронӣ, ки дар хок кампозикӣ мебошанд, фурсатро истифода мебаранд ва аз решаҳои захмкарда мегузаранд. Дар муқобили ин, <strong>обнокии чангӣ</strong> бо истифода аз чангҳо бо оқими паст, намокии маҳдуд, танҳо ба андозаи ниёзи рӯзонаи решаҳоро дар радиуси муайян (одатан 20 то 30 сантиметр) таъмин менамояд. Қисми дигари хок намнок ва бо ҳаводиҳии мувофиқ боқӣ мемонад. Ин чархаки «намнок-хушк» маҳаллӣ суръати рушди решаҳоро зиёд мекунад ва паҳншавии занбӯрӣро пешгирӣ мекунад. Инчунин, назорати дақиқи вақти обнокӣ тавассути таймерҳо, аз шиддати такрорӣ пешгирӣ мекунад, ки муҳимтарин омили паҳншавии бемориҳои решаҳо мебошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ریحان-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های ریحان با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation Рӣҳон</figcaption></figure><h3>Нақши пардаи чандирӣ дар идоракунии намнокӣ байни резҳо</h3><p>Пардаи чандирӣ ҳамчун ивазкунии муосира чангҳои гарон, барои кишт ба баҳор, ки одатан бо фосилаҳои мунтазами резҳо иҷро мешавад, бениҳоят мувофиқ аст. Як ғазаи афшондаи перфортсияшуда дар маркази рез ғазл мешавад ва бо суръати оқими муайян, обро ба таври якхела дар тӯли рез холӣ мекунад. Ин система кафолат мекунад, ки намнокӣ дар тӯли рез якхела бошад ва нуқтаҳои хушки пинҳонӣ дар анҳои ғазаҳои чангӣ вуҷуд надоранд. Барои фаҳмиши беҳтари тафсилоти техникӣ ва усули ҳисобкунии оқим ва фишори муносиб дар пардаҳои чандирӣ, метавонед ба дастури пурраи <a href="https://navar-abyari.ir/%D9%85%D8%B1%D8%A7%D8%AD%D9%84-%D9%86%D8%B5%D8%A8-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/">Марҳилаҳои ғазаи пардаи чандирӣ</a> масил кунед, ки параметрҳои ҳисобнокӣро бо мисолҳои адавӣ шарҳ медиҳад. Инчунин, таҳқиқи алгоритмҳои ғаза дар сабзавоти фрилансер монанди пипер дар мақола <a href="https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D9%BE%D8%A7%D9%BE%D8%B1%DB%8C%DA%A9%D8%A7/">Пардаи чандирии пипер</a> метавонад алгоритми монандро барои танзими фосилаи шакарҳо дар баҳор пешниҳод кунад, зеро ҳарду гиҳа ҳассосияти якхела ба намнокӣ доранд.</p>\n\n<h2>Идоракунии ҳашоротҳои хокзист ва ҳашоротҳо бо истифода аз каналҳои обнокӣ</h2><h3>Назорати шӯрҳо ва кӯрҳои хокзист</h3><p>Акчас аз ҳашароти хокзаи реханон, аз ҷумла хоки хабшонагӣ ва буми решагӣ, барои ҳаракат аз сатҳ то реша ба роҳи тармо ниёз доранд. Риширип бо нигоҳ доштани сатҳи байнсорхи хушк ҳаракати уфуқии ин ҳашаротро маҳдуд менамояд. Гарчанде ки ободории тамдодии дуруст метавонад ҳашаротро пурра нест кунад, вале чикундагӣ-ишро кам менамояд ва зарари мустақим ба решаҳоро паст меоред. Инчунин, истифодаи системаи ободорӣ барои тақсими ҳашароткуни биологӣ, усули пешрафтаи идоракунии таҳаммум аст. Баъзе лавҳаҳои фоиданок ва паразитҳои микориза метавонанд ба сурати моеъ аз риши идагузорӣ карда шаванд. Ин усул дақиқии таъсиротро баланд мебарад ва аз талафоти отрувиҳо дар фазои кушода пешгирӣ мекунад. Барои ҳисобкунии дозу дурусти моддаҳои ғизоӣ ва дорие, ки аз риши ба растани мерасад, мақоларо омӯхт <a href="https://navar-abyari.ir/miqdori-tum-kamolina-dar-yak-gektar/">Анҷомни кӯдулино дар як гектар</a> Метавонад нуқтаҳои калидии марбут ба консентратсияи маҳлулро ба шумо тақдим кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ریحان-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های ریحان با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation реханон</figcaption></figure><h3>Тавсиъаги ғизогузорӣ ва тақвият додани системаи иммунии растани</h3><p>Реханон барои муқоимат бо стресси обӣ ва ҳуҷуми занзуборҳо ба мувозинати дақиқи элементҳои ғизоӣ ниёз дорад. Кусуркунии кальсий боиси хуруши ҳуҷайраҳо ва воридшудани осонии патофенҳо мешавад. Кусуркунии фосфор рушди решаҳоро хуруш мекунад ва растаниро заифтар менамояд. Риширип имконият медиҳад, ки "ғизогузории тамдодии" дақиқ иҷро шавад, ки дар он, моддаҳои ғизоӣ ба таври дақиқ дар минтақаи решаҳои зинда идагузорӣ мешаванд. Ин на танҳо суръати ҷаббиширо баланд мебарад, балки аз ҷамъшавии намак дар сатҳи хок (ки худ сабаби стресс ба растани аст) пешгирӣ мекунад. Барои шиносӣ бо принсипҳои ҷойгиршавӣ ва пудрӣшавии моддаҳои ғизоӣ дар системаи риши, омӯхт <a href="https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%B7%D8%A7%D9%84%D8%A8%DB%8C/">Риширип шаблонӣ</a> Тавсия мешавад, ки усули филтрасия ва пешгирии часпиданро шарҳ медиҳад.</p>\n\n<h2>Ҳалли амалӣ барои деҳқон: протоколҳои мониторинг ва танзимот</h2><p>Барои баланд бардоштани ҳосилисти система дар идоракунии хатарҳо иҷрои протоколҳои зерин зарур аст. Ин рӯйхат ченлики иҷроӣ аст, ки бояд ҳар моҳ тафтиш карда шавад:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ریحان-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های ریحان با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation реханон</figcaption></figure><ul><li><strong>Танзими фосилаи тамдодкунандагон бо чуқурии реша:</strong> Реханон дар моҳҳои аввали рушд решаҳои сатҳӣ дорад. Фосилаи тамдодкунандагон бояд таврӣ танзим шавад, ки намӣ дар чуқурии 5 то 15 сантиметрӣ ҷамъ офтада шавад. Чуқур кардани беш аз чӣ боиси талафоти об ва камтар намӣ дар минтақаи фаъоли реша мегардад.</li><li><strong>Мониторинги намӣ бо сенсорҳои ошноӣ:</strong> Истифодаи потометр ё хумограометр, пазеҳури заҳри бемории аст. Агар намӣ аз 85 фоиди пурра бештар бошад, хатари фусилӣ фаъол аст. Танзими система асос ба маълумоти ин сенсорҳо, на тақвими собит, камои саломатиро таъмин мекунад.</li><li><strong>Алмоиш кариш ва таваб ободории:</strong> Ҳатто бо системаи тамдодии, реханонро набоҳад дар замини бозорӣ, ки соли гузашта растаниҳо аз хонадони наант ва фифл карда шудаанд, ниҳод. Таваб кариш бо дубулҳо ва ғаллаҳо давралуми патофенҳои мушаххашро мешиканад.</li></ul><h2>Хулоса: якҷояи технология ва идоракунии каришазӣ</h2><p>Идораискуни муҳимҳо ва бемориҳои базме (босҳӯр) танҳо имконпазир нест. Ин раванд талаб мекунад, ки дониши растнороёнӣ, гидрологии хок ва техникаҳои озиш (обкорӣ) бо ҳам омезиш дода шаванд. Системаҳои озиши банд (нап) ва қатрагӣ асъори қудратманд барои эҷоди муҳити ноустод барои муҳимҳо мебошанд, аммо танҳо дар сурати даркор насб ва идоракунии онҳо. Кишоварии паёдар он ҷо оғоз меёбад, ки мо ба ҷои идоракуни бӯҳрон, аз истеъмоли об ва энергия барои пешгирии бӯҳрон истифода мебарем. Барои васеъ кардани донишҳои шумо дар самти mahсулоти дигар бо эҳтиёҷоти монанд, таҳқиқоти <a href="https://navar-abyari.ir/beet-seed-amount-per-hectare-guide/">Рӯҳсати миқдори ниҳоди чаноқ (свекла) дар ҳектар</a> ба фаҳмиши беҳтари зичии ниҳодан дар бандҳои қатрагӣ кӯмак мекунад. Инчунин, хондани мақола <a href="https://navar-abyari.ir/miqdori-hosili-yunjadar-gektar-rahnamoi-purra/">Миқдори маҳсулотии гандум дар ҳектар</a> нишон медиҳад, ки чӣ гуна асосҳои обкунии дуруст метавонанд маҳсулотии ниҳоиро дар донишкӯбони калонтар низ боло баранд, зеро асосҳои физиологӣ якхела мебошанд.</p>\n<p><strong>Мақолаҳои алоқаманд:</strong> Миқдори ниҳоди тарбуз (харбоқ) дар ҳектар + Ҷадвали зичии ниҳодан</p>','Комил идоракунии зараранокҳо ва бемориҳо дар бодоӣ бо оптимизатсияи системаи оғознокӣ бо қатра ва нӯри тиб','Риҳан наботест, ки ҳассосияти баланд дорад ба намноки зиёд ва обӣ кардани номувофиқ бевосита боиси паҳншавии қаразҳои патоген мегардад. Дар ин мақола мо принсипҳои техникӣ идоракунии намнокӣ бо системаҳои тасмавии ва қатрагӣ, ҷанбаҳои ғизо ва назоратро баррасӣ мекунем, то маҳсулоти солимтарро бо хароҷоти камтар истеҳсол кунед.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
