SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='muqammal-baaluu-obori-poonyi-t-drip' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'muqammal-baaluu-obori-poonyi-t-drip','muqammal-baaluu-obori-poonyi-t-drip-crop-023-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'muqammal-baaluu-obori-poonyi-t-drip-crop-023-tj-698b6629');
