SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='modiraji-hashorat-o-bemorijon-sabzavot-bo-namoyshdig' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'modiraji-hashorat-o-bemorijon-sabzavot-bo-namoyshdig','modiraji-hashorat-o-bemorijon-sabzavot-bo-namoyshdig-crop-027-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'modiraji-hashorat-o-bemorijon-sabzavot-bo-namoyshdig-crop-027-tj-3bd49700');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Нақши ороёнии қатравӣ дар идоракунии солиматии сабзот</h2>\n<p>Дар камолоти саросарӣ ва озод, идоракунии <strong>ҳашарот ва бемориҳои сабзот бо ороёнии қатравӣ</strong> яке аз унвонҳои асосии солиматии маҳсул аст. Ба фарқ аз ороёнии ғарқобӣ, ки боиси ғановии пурраи хок ва эҷоди муҳити зараррасон барои ҳавои риешҳо мегардад, ороёнии қатравӣ бо кам кардани намнокӣ дар сатҳ ва нигоҳ доштани мувозинати намнокӣ-газиш дар минтақаи риешҳо заминаро барои кам кардани рушди патогенҳои хокӣ фароҳам меорад. Бисёр деҳқонон тафаккур мекунанд, ки ороёнӣ танҳо барои таъмини об аст, аммо ҳақиқат ин аст, ки усули тақсимоти об мустақиман ба пайдоиши бемориҳои қарзҳои ба монанди пипаия ва сиғаи сафед, ва ҳашароти ғайричандонҳо ба монанди мугушкаи хок ва кӯзатоки чӯбишк таъсир мерасонад. Дар ин қисмат мо робитаи мустақими байни усули ороёнӣ ва солиматии ҳаби сабзотро баррасӣ мекунем.</p>\n\n<h2>Механизми пешгирии бемориҳои қарзӣ дар системаи қатравӣ</h2>\n<p>Бемориҳои қарзӣ-и сабзот одатан дар шароити намнокии баланди сатҳӣ ва камшавии дувомхорӣ (аэротсия) дар хок шиддат меёбанд. Системаҳои қатравӣ бо ҷамъ кардани таъмини об дар минтақаи риешҳо, боиси он мегарданд, ки сатҳи баргҳо дар ҳолати хушк нигоҳ дошта шаванд, дар ҳоле ки риешҳо навмекунанд. Ин зиддияти намнокӣ яке аз беҳтарин роҳҳои ғайрихимиявӣ барои идоракунии пӯсишҳои қарзӣ аст. Инчунин, имконияти омехта кардани ороёнӣ бо ғизонокӣ (фишуд) имкон медиҳад, ки дар даври рушд аз моддаҳои зиди беморӣ ва зиди ҳашарот бо дақиқӣ ва мунтазам истифода бурда шавад. Дар ин роҳ, омӯзиши дар бораи миқдори боби бобуна дар гектар метавонад ба шумо кӯмак расонад, ки зичии мувофиқи кӯрпакро бо назардошти системаи ороёнӣ интихоб кунед, зеро зичии баланди кӯрпак бе идоракунии дурусти ороёнӣ, фосилаи рушди қарзҳоро кӯтоҳ мекунад.</p>\n<h3>Таъсири стресси намнокӣ барои муқовимати ҳаб</h3>\n<ul>\n<li><strong>Стресси мулоими ороёнӣ:</strong> Истифодаи усули ороёнии қатравӣ бо кам кардани миқдори намноки риешҳо ба сатҳи 60 то 70 фоиз ҳаҷми моеъ боиси зиёдшавии истеҳсоли кислотаи салисилӣ дар ҳаб мегардад, ки моддае барои қуввати табиӣ дар муқобили патогенҳо аст.</li>\n<li><strong>Кам кардани гузариши об-обҳо:</strong> Дар ороёнии қатравӣ, ба фарқ аз ғарқоб, мавҷҳои об аз риешҳо ба сӯи сатҳи хок ва баргҳои пояти сабзотҳо (ба монанди спинак ва касал) паҳн намешаванд ва бинобар ин бустуни рушди қарзи сиғаи сафед нобуд мегардад.</li>\n</ul>\n<h2>Идоракунии ҳашароти хокӣ бо навори тибӣ ва қатравӣ</h2>\n<p>Ҳашароти хокӣ ба монанди кӯзатоки чӯбишк, кузатҳо ва ларваҳои мугушкаи гӯголи фаринҷӣ ва сабзи чомоҳӣ, мустақиман бо минтақаи риешҳо дар алоқаанд. Системаҳои навори тибӣ ва қатравӣ имконияти истифодаи тӯлҳои кӯрпак ва моддаҳои химиявии хокпаршандаро дар фосилаи қатравоҳҳо фароҳам меоранд. Дар қисматҳои ихтисосӣ тавсия дода мешавад, ки аз туҳҳои зарра барои назорати ҳашароти петиноз ҳамзамон бо даврони ороёнӣ истифода бурда шавад. Агар аз навори тибӣ барои камолоти равоии ба монанди сабзи чомоҳӣ ё кӯле истифода мебаред, таъмин шавед, ки шӯрҳои овардани об дар маҳалли кӯрпак ҷойгир шудаанд, то об ва ободори мустақиман ба риешҳо бирасад. Барои фаҳмиши беҳтари кори техникӣ, омӯзиши хусусиятҳои техникӣ навори тибии ороёнӣ ба шумо кӯмак мерасонад, ки қатравиро асосан ба қари шӯр ва сатҳи самарановбарӣ интихоб кунед, то пешгирӣ кардани паҳншавии зиёди об дар сатҳи хок ва ҷабҷабидани он таварони ҳашароти сатҳӣ шуд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سبزی-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های سبزی با آبیاری قطره‌ای - تصویر 1"/><figcaption>Ҳашарот, бемориҳо, ороёнии қатравӣ сабзот</figcaption></figure>\n\n<h2>Ҳашарот ва бемориҳои оддӣ дар камолоти сабзи чомоҳӣ ва кӯле бо қатравӣ</h2>\n<p>Сабузоти чомоҳӣ ва кӯле сабзотоне мебошанд, ки ба намноки мунтазам ниёз доранд, аммо ба қарзҳои риешзан ҳассосии баланд доранд. Дар камолоти сабзи чомоҳӣ, бемориҳои гиреҳи риешӣ, ки аз ҷониби нематодаҳо ба вуҷуд меоянд, бо ороёнии ғарқобӣ шиддат меёбанд. Бо истифода аз қатравӣ, метавон аз формулҳои зиди беморӣ бо дозҳои паст, аммо миқдори зиёд истифода бурд. Инчунин дар кӯле, рӯяни об аз нушеёбии қатравоҳҳо ба баргҳои поин метавонад боиси пӯсиши сафед гардад. Барои пешгири, ҳатман системаро дар оғози камолот санҷед. Агар камолоти пиёзча дошта бошед, ки яке аз сабзотҳои даъватии баланд аст, идоракунии ҳашароти ширкашон хеле муҳим аст. Омӯзиши дар бораи <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори ҳосилкашории пиёзча дар гектар</a> метавонад ба шумо кӯмак расонад, ки бо дониши қобилияти истеҳсо, идоракунии рағотӣ ва намноки хокро дақиқтар барномарезӣ кунед, зеро намноки зиёд дар хоки пиёзча боиси пӯсиши риеш ва ҷабҷабидани мугушка мегардад.</p>\n<h2>Намудҳои амалӣ барои танзими системаи сачкоҳӣ барои саломатии сабзавот</h2>\n<ol>\n<li><strong>Нзаррасонии сатҳи сачкоҳӣ:</strong> Ҳамеша сатҳи сачкоҳиро бо тақсимкунандаи оби оҳиста (флоуметр) назорат кунед. Сачҳо хурд ё дарозшуда ба ҷамъшавии зарарзанандагон дар нуқтаҳои хушкҳои хок боис мешаванд. Барои интихоби сач мувофиқ, метавонед ба мақолаи «Равия интихоби наварҳои обориҳои оҳиста» таваҷҷуҳ кунед.</li>\n<li><strong>Гудрукдиҳии мақсаднок:</strong> Истифодаи ҳалкунандаҳои муқобил ба ҳашарот, ба монанди фосфати калий, ба ҷойи пашпашкунии умумӣ, тавассути системаи сачкоҳӣ иҷро кунед. Ин усул имкон медиҳад моддаҳои ғизоӣ ба реша барсид, ки ин муқовимати растаниро вобаста ба бемории қарақати реша бартар меорад.</li>\n<li><strong>Идоракунии мадак (мулт) бо обориҳо:</strong> Истифодаи наварҳои обориҳо бо тӯлӣҳо ва мадакҳои сачҳо ҳарорати сатҳи хокро ҳариф нигоҳ медорад ва дар афзоиши тези дӯрӯби ҳашороте, ки ҷойи овуни зарарзанандагон аст, пешгирӣ мекунад.</li>\n</ol>\n<h2>Саволҳои маъмул дар бораи зарарзанандагон ва бемориҳои сабзавот бо обориҳои сачкоҳӣ</h2>\n<p><strong>Оё обориҳои сачкоҳӣ боиси афзоиши зарарзанандагони нисакӣ мегарданд?</strong>\nНе, дар асл обориҳои сачкоҳӣ боиси кам шудани намнокӣ дар сатҳ ва набудани оби паҳнок шудан ба баргҳо мегардад, ки ин эҳтимоли овуни зарарзанандагони нисакӣ ва ҳашороти сафедро кам мекунад. Аммо агар мадак дар атрофи шланг кушода бошад, бояд нигоҳдории зарарзанандагони хокзамандаи дигарро назорат кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سبزی-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های سبزی با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation сабзавот</figcaption></figure>\n<p><strong>Беҳтарин вақти истифодаи ҳалкунандаи муқобил ба ҳашарот тавассути сачкоҳӣ чист?</strong>\nБеҳтарин вақт марҳилаи пеш аз зоҳир шудани нишонаҳо аст (барои пешгирӣ). Одатан дар миёнаи рӯи сабзавот, вақте намнокӣи ҳаво баланд аст, як бор овуни қураҳои фитонавӣ тавассути сачкоҳӣ тавсия дода мешавад.</p>\n<p><strong>Таъсири обориҳои сачкоҳӣ ба дуввонаи чӯбхӯр дар ҳасили сасин ё аспанаҷ чист?</strong>\nДуввонаи чӯбхӯр аз хушк шудани худсозҳои хок зарар мебинад. Бо обориҳои муқарраб ва кӯтоҳ, намнокӣи хок якхел мемонад, ки ин боиси он мегардад, ки дуввонаҳо дар чуқури муайян ҷойгир шаванд ва дар сурати лозимӣ бо ҳалкунандаҳои маҳаллӣ назорат карда шаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سبزی-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های سبزی با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation сабзавот</figcaption></figure>\n\n<h2>Хулоса: Ҷамъомалии обориҳои сачкоҳӣ ва идоракунии зарарзанандагон</h2>\n<p>Идоракунии <strong>Вабо ва бемориҳои сабзиҳо бо обёрӣ по қатрадорӣ</strong> Ин як равиши якҷост, ки ба танзими дақиқи параметрҳои обёрӣ, интихоби шитоби мувофиқ ва истифодаи ҷилои мунзими боқароии хокӣ ниёз дорад. Ба ҷои он ки обёриро танҳо барои намак донед, онро ҳамчун восита барои идоракунии муҳити патогенҳо тавҷӯҳ диҳед. Бо риояи фосилаи мувофиқи қатраҳо, истифодаи мульча ва назорати муқаррарии равиш, метавонед боқароии моддаҳои кимиёвиро ба таври назаррас кам кунед ва молу маҳсули бештарро ба бозор пеш бароред. Диққат ба моҳи чойгунӣ ва сифати расидани об таъсири мустақимро дарз ба саломати решаҳои сабзиҳо дорад.</p>\n<p><strong>Маводи пайваста:</strong> <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A8%D8%A7%D9%85%DB%8C%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 D8A8D8A7D985DB8CD987 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A7%D8%B3%D9%81%D9%86%D8%A7%D8%AC-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 D8A7D8B3D981D986D8A7D8AC D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/drip-tape-melon-irrigation-guide-tajikistan/">drip tape melon irrigation guide tajikistan</a></p>','Мудираҷи ҳашорот ва бемориҳои сабзавот бо намоишдиҳӣ: Родӣёди комил','Оғоз кунӣ ҳатто на танҳо дар таҳиякунии об муассир аст, балки бо эҷоди намии назоратшуда дар решаҳо, нақши калидӣ дар пешгирии бемориҳои занбӯрунакӣ ва зараррасонҳои заминӣ сабзавот дорад. Ин мақола роҳҳои пулсоҳии идоракунии зараррасонҳо бо таваҷҷуҳ ба оғозкунӣро мебаррад.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
