SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='nigahubini-gehur-bo-naqri-tib' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'nigahubini-gehur-bo-naqri-tib','nigahubini-gehur-bo-naqri-tib-crop-031-tj');
