SET @resolved_slug=IF(@slug_conflict IS NULL,'analysis-vegetable-cost-drip-irrigation-farmer-guide','analysis-vegetable-cost-drip-irrigation-farmer-guide-crop-033-iraq');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'analysis-vegetable-cost-drip-irrigation-farmer-guide-crop-033-iraq-18b8787b');
