START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-034' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-034:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='mukomoti-justabosti-korburiyi-baho-bob-obarokuniyi-qatragi' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'mukomoti-justabosti-korburiyi-baho-bob-obarokuniyi-qatragi','mukomoti-justabosti-korburiyi-baho-bob-obarokuniyi-qatragi-crop-034-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'mukomoti-justabosti-korburiyi-baho-bob-obarokuniyi-qatragi-crop-034-tj-ed8863a9');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар муҳимии ороиши қатрагӣ барои парвариши чангӯбӣ</h2><p>Чангӯбӣ яке аз муҳимтарин нақли ҳатми заҳр ва ороӣшуда дар Ирон аст, ки ғайр аз арзиши ғизоии баланд, нақши калидӣ дар беҳбуди ҳосилнокӣи хок ва даври обивии заминҳо мебозад. Ин растани ҳамчун донги гиравӣ, тавассути бозгашти нитрогени хок, ниёз ба азотҳои кимиёвиро кам мекунад ва дар натиҷа аз ҷиҳати иқтисодӣ ва муҳитӣ бартарии зоҳир дорад. Бо дар назар гирифтани маҳдудияти шадиди манбағҳои обӣ дар Ирон ва пешгӯии хушксолӣ дар бисёр минтақаҳо, системаҳои навнишони ороӣишуда, чун <strong>навари тиббӣ</strong> ва қатрагӣ барои парвариши муҳимии чангӯбӣ ба корбори зарурӣ ва бебадил гардидаанд.</p><p>Ороиишудаи қатрагӣ бо таваҷҷуҳи об ба шакли нокии ва такрорӣ беқарар ба минтақаи рӯӣ, на танҳо намдории мувофиқ ва якхеларо нигоҳ дорад, балки аз фускунии сабукҳо ва паҳн шудани бимариҳои қамарӣ, ки дар ороии рӯи хок оддӣ мебошанд, пешгирӣ мекунад. Ҳамчунин, ин усул аз афзоиши гузаштаҳо ҷониби қаторҳо пешгирӣ мекунад, зеро намдории рӯи хок танҳо дар қисми рӯӣ мавҷуд аст. Дар ин дастуроми мукаммал, мо тафсилоти техникӣ барои парвариши чангӯбӣ бо ороиишудаи қатрагиро баррасӣ мекунем, то ки деҳқонон бо огоҳии пурра фоидабарории худро ба ҳадди максимал расонанд.</p><h2>Усулҳои парвариш (Planting Methods) чангӯбӣ дар системаи қатрагӣ</h2><p>Интихоби шакли дурусти парвариш, ним роҳи бартарӣ дар ороиишудаи қатрагӣ чангӯбӣ аст. Шаклҳои парвариш бештар ба асоси масофа байни қаторҳо, намуди зирафӣ ва ҷойгиркунии системаи ороӣ муайян мешаванд. Фаҳми ин робита, калиди беҳтарсозии истифодаи об ва пешгирии фишорҳои рӯӣ аст.</p><h3>Парвариши дувони дар навари тиббӣ</h3><p>Дар ин усул, чангӯбӣ дар ду қатор парвариш мешавад, ки навари тиббӣ далелҳо ҷои байни ин ду қатор аст. Ин усул барои зирафҳоҳои пуршаддат, ки фазои бештарро талаб мекунанд, тавсия дода мешавад. Масофаи парвариш дар наварҳои тиббии яквони оддӣ 45 то 50 сантиметр ва дар наварҳои тиббии дувони 90 то 100 сантиметр аст. Истифода аз наварҳои тиббии яквони сабаб мешавад, ки об бо қувваи муносиботар таваҷҷуҳ дода шавад ва фарогирии минтақаҳои рӯӣ беҳтар бошад. Барои интихоби намуди беҳтарин навар ва фаҳми фарқиятҳои техникӣ онҳо, шумо метавонед матлаби <a href="https://navar-abyari.ir/farq-nawwar-tip-bolal-dowkh-w-plaked/">Фарқияти навари тиббии дувони ва яквони</a> ро бо эҳтиётӣ омӯзед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-لپه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت لپه با آبیاری قطره‌ای - تصویر 1"/><figcaption>plante methods drip crop irrigation schedule чангӯбӣ</figcaption></figure>\n<h3>Парвариши яквони ва ҷойгиркунии хаттӣ</h3><p>Дар ин усул, растаниҳо дар як қатор ҷойгиранд ва навари тиббӣ ҳаммасофа бо онҳо ё каме ҷойивар (Staggered) насб мешавад. Парвариши яквони фазои бештарро барои амалиҳои механикӣ фароҳам меорад ва дар боғҳои чангӯбӣ бо масофаи парвариши 60 сантиметрӣ иҷро мешавад. Ҷойивар кардани қисмҳои парвариш бояд бо даври бозгашти системаи ороӣ ҳамзамон бошад, то аз маҳкамшавии қатраҳо пешгирӣ шавад. Ин усул инчунин ба идоракунии беҳтари нуру ҳаво расидан ёрӣ мекунад.</p>\n<h2>Тақвиями ороӣшуда (Irrigation Schedule) ба асоси марҳилаҳои афзоиш</h2><p>Чангӯбӣ монанди дигар нақли ҳатми заҳр, дар марҳилаҳои гуногуни афзоиш ба хосиятҳои гуногун муҳтоҷ аст. Тақвиями ороиишудаи қатрагӣ чангӯбӣ бояд ба асоси ниёз ба об дар ҳар марҳила танзим шавад. Намоёнии таъсиси ороӣшуда бо марҳилаҳои афзоиш, метавонад боиси парокандагии гул, кам шудани пуршавии дон ё ҳатто қатъи афзоиши растани шавад.</p><ol><li><strong>Марҳилаи нухорӣ (1 то 3 ҳафта):</strong> Дар ин марҳила, решаҳо ҳанӯз заифанд. Ороиишудаи кам вале такрорӣ (ҳар 2 то 3 рӯз) бо суръати паст дар навари тиббӣ тавсия дода мешавад, то ки хок намнок боқӣ монад ва намои пайдоишҳои растаниҳо якхела шавад. Ин давр барои устуворияти растани ҳайат аст.</li><li><strong>Марҳилаи рушди вегетативӣ (4 то 6 ҳафта):</strong> Бо афзоиши тези кодаку баргҳо, талабот ба об зиёд мешавад. Давраи ороғин (ирригация) аз 30 дақиқа то 45 дақиқа дароз мешавад. фосила байни ду ороғин ба 3 то 4 рӯз кам мешавад. Масрафи об дар ин марҳила баланд аст.</li><li><strong>Марҳилаи гулдорӣ ва ҳосилшавии нони гӯшаҳо (7 то 10 ҳафта):</strong> Ин ҳассостарин марҳила аст. Камбуди об дар ин вақт боиси афтидани гулҳо ва камшавии сахт ҳосилнокии мешавад. Ороғини дақиқ ва мунтазам бо лӯлаҳои ороғини тамдидӣ (наварӣ) боиси он мегардад, ки рӯи хок устувор боқӣ монад. Тавсия карда мешавад, ки пас аз ҳар маротиба ороғин, системаи шустушӯро истифода баред, то пайдоиши ресуб (намакҳо) аз тамдидгирҳо (кучкчконҳо) пешгирӣ шавад.</li><li><strong>Марҳилаи пухт (ҳафтаи 11 баъд):</strong> Масрафи об кам мешавад. Ороғинҳо мунтазамтар мешаванд (ҳар 5 то 7 рӯз) ва дар охирин ҳафта комилан қатъ мегарданд, то ғолаҳо хушк шаванд. Ин кор ба ҷамъоварии осон ва камшавии бемориҳои пас аз ҳосилдохтӣ кӯмак мекунад.</li></ol><p>Барои ҳисоб кардани дақиқи дараҷа ва шумораи тамдидгирҳо (кучкчконҳо), шумо метавонед роҳнамои нархи лӯлаҳои ороғини ҳанӯрӣ-поёнро ҳангоми хариди онро ҳамчун қисме аз системаи лӯлакучӣ бознигаред. Инчунин, интихоби ҳанӯрҳои мувофиқ барои идоракунии фишор ва дараҷа нақши муҳимро дар давомнокии система боз мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-لپه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت لپه با آبیاری قطره‌ای - تصویر 2"/><figcaption>planting methods drip crop irrigation schedule лӯбаи сабз</figcaption></figure>\n<h2>Омӯзишҳо ва мавҷудиҳои иловагӣ</h2><p>Барои муваффақият дар ғолдори лӯбаи сабз бо ороғини тамдидӣ (кучкчконӣ), риояи мундариҷаи зерин зарурӣ аст ва ҳар гуна дурӯй аз ин асосҳо метавонад гарон барояд:</p><ul><li><strong>Идоракунии хок:</strong> Хок барои лӯбаи сабз набояд бо об пур шавад. Лӯлаҳои ороғини тамдидӣ бо истифода аз кам об, аз намакҳо ва обфрӯйӣ (ғарқобӣ) пешгирӣ мекунанд. Пеш аз насб кардани система, ҳатман ҳаросони хокисто (наврор) тафтиш кунед. Тавсияи мо баррасии... <a href="https://navar-abyari.ir/%d9%86%da%a9%d8%a7%d8%aa-%d9%82%d8%a8%d9%84-%d8%a7%d8%b2-%d8%ae%d8%b1%db%8c%d8%af-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c/">Муҳимтаринҳо пеш аз харидани лӯлаҳои ороғини тамдидӣ</a> ...барои пешгирии блокшавии оянда ва ҳифзи самаранокии система мебошад.</li><li><strong>Дидан ва ғолдони:</strong> Дараҷаи ғалдонии бораи лӯбаи сабз одатан 5 то 7 сантиметр аст. Бора бояд дар дараҷаи мувофиқ ҷойгир шавад, то аз яҳшавӣ (сармозадан) ва офтобгармӣи зиёд (хушкшавӣ) пешгирӣ карда шавад. Барои донистани миқдори дақиқи бора, шумо метавонед ба миқдори бораи лӯбаи сабз дар як гектар + роҳнамои ғалдонӣ, ки аз ҷиҳати техникии монанди лӯбаи сабз аст, муроҷиат кунед ва дар асоси ҳамон принсипҳо танзимотро барои лӯбаи сабз анҷом диҳед.</li><li><strong>Коргардонии (мониторинги) система:</strong> Ҳар як маротиба ороғин бояд бо назорати нақши коҳиши об ҳамроҳ бошад. Агар баъзе минтақаҳо хушк монда бошанд, дараҷаи тамдидгирҳо (кучкчконҳо)-ро танзим кунед. Инчунин, тафтиши шафофии оби воридшаванда ба система барои пешгирии талашкунӣ зарур аст.</li></ul><h2>Саволҳои маъмул (FAQ)</h2><p><strong>1. Масофаи мувофиқ байни нӯри тиб ва решаҳои нӯр чӣ қадар аст?</strong><br>Тавсия мешавад, ки нӯри тиб дақиқан байни ду ҷаби (дар нӯруи ду ҷаба) ё 15 то 20 сантиметри тарафи реша (дар нӯруи як ҷаба) ҷойгир бошад, то реша бо оби бевосита мулоқот дошта бошад. Ин масофаи стандартии барои беҳтар кардани ҷидоши об ва таъмини оксиген ба реша мебошад.</p><p><strong>2. Оё нӯр ҳассоси оби тибӣ аст?</strong><br>Нӯр нисбат ба обдорӣ ҳассос аст, аммо аз равозӣ барқарор меояд. Тибҳои бо дэби 160 ё 200 литр дар соат барои минтақаҳои гарм ва хушк идеалӣ мебошанд. Дар минтақаҳои хунуктар, дэби поён ва бозор бештар таъсирнок мебошанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-لپه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت لپه با آبیاری قطره‌ای - تصویر 3"/><figcaption>усули нӯру, зоти нӯр, расвали оби тиб нӯр</figcaption></figure><h3>Хулоса</h3><p>Истифодаи оби тиб дар нӯруи нӯр усули арзон ва бусмат аст, ки ба деҳқоноҳона имконият медиҳад, ки бо коҳиши истифодаи об, сифат ва миқдори mahsul-и худро баланд бардоранд. Рӯиобӣ ба расвали оби тиб асоси марҳилаҳои афзоиш ва интихоби услуби мувофиқи нӯру, ду сутуни асосии муваффақият мебошанд. Бо пайравӣ ба ин роҳнамо ва истифодаи муносиб чун тибҳои муқовимат дор, шумо метавонед беҳтарин истифодаи ғунуман нӯри худро бовар кунед. Диққат ба тафсилоти хурди нобуд шудани ва назорати система фарқи байни шикаст ва муваффақият дар фасли хушкӣ аст.</p><p><strong>Мавзӯҳои вобаста:</strong> Фарқи ҷилби оби тиб системаи оби тиб, <a href="https://navar-abyari.ir/miqdori-tuxmi-lobia-chashmbalbala-dar-yak-hektyar/">Миқдори тухми лӯбии чашм балба дар як гектар</a>، <a href="https://navar-abyari.ir/piyozak-tukhm-dar-hektar-chand/">Пизоки тохм дар як гектар чандто</a></p>','Мукамоти ҷамъбасти корбурии баҳо бо обёркунии қатрагӣ: асосҳо, тақвим ва дастурҳои амалӣ','Таҳқиқи қадам ба қадами усули корки чанго (чечевица) дар системҳои навида (нурӣ), муайян кардани ҳарифи обёркунӣ вобаста ба марҳилаҳои афзоиши растани ва ба даст овардани роҳнамои амалӣ барои беҳтар кардани истифодаи об ва зиёд кардани ҳосили чанго.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
