SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='tape-drip-irrigation-maintenance-clover-cultivation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'tape-drip-irrigation-maintenance-clover-cultivation-guide','tape-drip-irrigation-maintenance-clover-cultivation-guide-crop-036-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'tape-drip-irrigation-maintenance-clover-cultivation-guide-crop-036-en-ca6a93c2');
