SET @resolved_slug=IF(@slug_conflict IS NULL,'komsili-zar-i-bobi-kabud-i-drop-i-navi-tip','komsili-zar-i-bobi-kabud-i-drop-i-navi-tip-crop-037-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'komsili-zar-i-bobi-kabud-i-drop-i-navi-tip-crop-037-tj-12b47a8d');
