SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='pepper-drip-tape-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'pepper-drip-tape-irrigation-guide','pepper-drip-tape-irrigation-guide-crop-039-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
