SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fasila-i-qatori-jinsefenkurr-vahorat-orom-me-yorahoy-tovishada-crop-041-tj-bd5fb8ee');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти беҳтар кардани тарҳрезии паҳлӯй (layout) дар парвариши розмарин</h2>\n<p>Розмарин яке аз растаниҳои духтхӯрокхори дорои даромади баланд дар бозорҳои дохилӣ ва хориҷӣ аст, ки сифати ниҳоии он ба чуқурӣ ва паҳноии решагирӣ вобаста аст. Муайян кардани <strong>масофаи лентаро дар парвариши розмарин</strong> аз муҳимтарин масъалаҳои фаннӣ дар идоракунии обёркунии тамчавӣ (drip) мебошад. Интихоби масофаи мувофиқ на танҳо ба беҳтар шудани устувории решаҳо кӯмак мекунад, балки аз вобордани решаҳо дар шароити намноки баланди ҷӯрагӣ низ пешгирӣ менамояд. Дар ин қисм, шиносоӣ бо роҳи интихоби ленти мувофиқи обёркунии тамчавӣ метавонад ба кишовар дар бораи намудҳои лент ва хусусиятҳои фаннии онҳо диди васеътар диҳад.</p>\n\n<h2>Стандарди масофаи қаторҳо ва роҳи ҷойгиркунии лент</h2>\n<p>Барои парвариши розмарин, чидмани қаторӣ одатан масофаи 100 то 120 сантиметрро дорад. Масофаи ленти тамчавӣ аз маркази қатор бояд ба таври чунин бошад, ки ноҳияи намдор (Wetted Zone) пӯшиши пурраи решаҳоро таъмин кунад. Азбаски розмарин ба решаҳои рӯии то нимметр ҳассосият нишон медиҳад, тавсия мешавад, ки масофаи лент аз таҷи (Stem) набояд аз 15 то 20 сантиметр фарқ кунад. Ин масофа аз тобишан ба таври мустақими гави (crown) растани пешгирӣ мекунад ва дар айни замон намнокроки зарурии решаҳоро таъмин мекунад. Дар шароитҳое, ки бошкҳои калонтар истифода мешаванд, ин масофа то 25 сантиметр зиёд шуда метавонад, то ки фишори вайронкунии (compress) барои решаҳои нав пешгири шуданаш баста шуд. Инчунин, ҷойгиркунии ленти тамчавӣ бо назардошти асосҳои роҳи интихоби ленти мувофиқи обёркунии тамчавӣ муҳимияти дугона дорад, зеро намуди лент ба тақсимоти фишор ва ҷараёни об таъсири мустақим мерасонад.</p>\n\n\n\n<h3>Таъсири иқлим ба масофаи ленти тамчавӣ</h3>\n<p>Дар минтаҳаҳои гарм ва хушк, ки бухоршавии баланд доранд, эҳтимолан лозим мешавад, ки лент каме ба растани наздиктар ҷойгир карда шавад, то ноҳияи намдор тезтар ба вуҷуд ояд ва аз хушк шудани решаҳо пешгирӣ шуд. Аз ҷиҳати дигар, дар минтаҳаҳои сард ва намнок, ки хатари бемории зараррасонаҳои куфӣ ба решаҳо вуҷуд дорад, масофаи 20 то 25 сантиметр кӯмак мекунад, то ки аз маҳсулоти об тоҷушӣ аз лент ва тобиши дурӯзаи решаҳо пешгирӣ шуд. Шиносоӣ бо асосҳои <a href="https://navar-abyari.ir/%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%DA%AF%D8%B1%D9%87%D8%A7%DB%8C-%DB%8C%D8%A7-%D8%AE%D9%86%D8%AF%D9%82/" target="_blank">обёркунии каналӣ ё кӯла (flood/ridge)</a> Инчунин дар шароитҳои хусусии хокӣ метавонад фоидаовар бошад, аммо барои розмарин, системаи ленти тамчавӣ бо сабаби идоракунии баланд, гӯзори асосӣ мебошад. Истифодаи дониши классикии обёркунии каналӣ бо системаҳои замонавии ленти тамчавӣ метавонад кӯмак кунад, то ки кишовар бо рафторани хок ва гировуҳои ҳидроликии ҷӯрагии худ беҳтар шинос шавад ва қарорҳои беҳтар барои танзими фишор ва дэб (дебит) система гирад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-رزماری-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت رزماری: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop розмарин</figcaption></figure>\n\n<h2>Интихоби намуди ленти тамчавӣ аз рӯи чуқурии решаи розмарин</h2>\n<p>Барои розмарин, аз лентҳои тамчавӣ бо суръати баромади тамча (Emitter Discharge) пасттар (масалан, 1 ё 1.5 литр дар соат) истифода мешавад. Ин боиси менамояд, ки намнокӣ ба таври ором дар чуқурии мувофиқ паҳн шавад ва сатҳи хок дар атрофи растани аз хушк мондан наҷот ёбад. Интихоби дурусти лент бо шиносоии <a href="https://navar-abyari.ir/drip-irrigation-tape-system-components/" target="_blank">ҷузъҳои системаи обёркунии тамчавӣ</a> оғоз мешавад. Аз лентҳои тамчавӣ бо андозаи хурдтар (масалан, 1/6 дюйм) истифода мебаред, пас тақсимоти масофаҳо бояд дақиқтар бошад, то ки парокандагии фишор дар дарозии шланг боиси нобаробарии ноҳияи намдор нагардад. Тавсия мешавад, ки пеш аз амалиёти кӯтиш (кишт), тестфишор ва ҷараёнро дар як қатор намунавӣ иҷро кунед, то ки бо пайвастагии ноҳияи намдор боварӣ ҳосил шавед. Фаҳмиши сохтори ҷузъҳои система, аз помпа то палтрак (filter) ва тамчаҳои баромад, калиди асосии тарҳрезии як шабакаи обёркунии самаранок ва доимӣ мебошад.</p>\n\n\n\n<h3>Нуқтаҳои асосӣ дар чидмани қаторӣ (Row Layout)</h3>\n<ul>\n<li>Масофа байни қаторҳо: 100 то 120 сантиметр.</li>\n<li>Масофаи лент аз таҷи растани: 15 то 20 сантиметр дар шароити оддӣ.</li>\n<li>Дар нигоҳдории дусоҳибарӣ: масофаи 25 сантиметр дар ҳар тарафи тоҷ.</li>\n<li>Эзоҳ: Дар боғу бинҳо бо шамолотии баланд, трубаи асосӣ (Mainline)-ро дар тарафи поёни шамолотӣ ҷойгир кунед, то фишори ҳидроликӣ камтар бошад.</li>\n</ul>\n\n<p>Илова бар ин, тафтиш <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%84%d9%be%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/" target="_blank">Миқдори ҳосили лӯпӣ дар гектар + омилҳои таъсиргузор ва усулҳои зиёд кардан</a> медионад нусхаи аҳамияти идоракунии дақиқи решаҳо дар ояву чиноҳои доруворӣ ва нӯрҳои наҷотро тақдим кунад. Гарчанде роҷерс маҳсулоти гуногун аз лӯпӣ аст, вале принсипҳои идоракунӣ чун шинохтание заифи решаҳо ва оптимизатсияи манбаъҳо дар ҳарду ҳолат истифодаи монанд доранд. Ин усулҳои таҳлилӣ ба деҳқон кӯмак мерасонад, то хатарҳои истеҳсолиро кам кунад ва самаранокии боғро зиёд созад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-رزماری-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت رزماری: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>масофаи траки ғизоии сутунки нигоҳдории ҳосили роҷерс</figcaption></figure>\n\n<h2>Нуктаҳои амалӣ ва идоракунии ҳудуди намнокӣ</h2>\n<p>Муҳимтарин омил дар муваффақияти нигоҳдории роҷерс, якдилӣ будани ҳудуди намнокӣ аст. Агар масофаи траки ғизоӣ номувофиқ бошад, мо ду мушкилоти асосиро мебинем: хушкшавии решаҳо дар наздикии тоҷ ё боборшавии решаҳо. Барои назорати ин ҳолат, шумо метавонед аз усулҳои зарбадорӣ ё ултарсавудӣ истифода баред. Илова бар ин, шинохтани нозимҳои решабандии ояву чиноҳои дорувори дигар, аз ҷумла таҳқиқоти чун зиёд шудани ҳосили пиёз дар гектар, метавонад дарки амиқтари ҳассосияти маҳсулот ба обёрро эҷод кунад. Барои роҷерс тавсия дода мешавад, ки нигоҳдариро дар самти шарқӣ-ғарбӣ иҷро кунед, то офтоб аз ҳудуди намнокӣ гузарад ва буғи моеъи якнамошавӣ тарқ шавад. Ин ҷобаҷогузорӣ боиси кам шудани фишори обӣ дар соатҳои гарм мегардад.</p>\n\n<h3>Оптимизатсияи истифодаи об ва хароҷот</h3>\n<p>Истифодаи масофаҳои дуруст бевосита ба кам шудани хароҷоти об ва энергияи помпаҳо мусоидат мекунад. Муқоиса бо дигар маҳсулот нишон медиҳад, ки идоракунии ҳудуди намнокӣ дар маҳсулоти ҳассос ба об фарқи назаррасро дар натиҷаи ниҳоӣ меорад. Роҷерс нисбат ба маҳсулоти бачагинӣ ба оби камтар ниёз дорад, вале ба назорати дақиқ зиёд ниёз дорад. Бо назардошти баланд шудани нархи ашёи хом, боғҳо метавонанд бо истифода аз манбаъҳои <a href="https://navar-abyari.ir/miqdori-tuhmi-qahvagi-dar-yak-gektar/" target="_blank">Ҳисоб кардани истифодаи об дар як гектар</a> барои ояву чиноҳои монанд, арзёби дақиқтареро дошта бошанд. Илова бар ин, донистани он ки <a href="https://navar-abyari.ir/navor-i-tip-baroi-yek-gektar-chi-qadar/" target="_blank">миқдори траки ғизоии лозима барои як гектар чанд аст</a> ба нақшакунии буҷет ва хариди таҷҳизот кӯмаки зиёд мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-رزماری-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت رزماری: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>масофаи траки ғизоии сутунки нигоҳдории ҳосили роҷерс</figcaption></figure>\n\n\n\n<h2>Саволҳои оддӣ (FAQ)</h2>\n<ol>\n<li><strong>Оё метавон аз ду траки ғизоӣ дар як сутуни роҷерс истифода бард?</strong><br>Бале, агар наҳокиҳо қавӣ ва калон бошанд, истифодаи ду траки ғизоӣ бо масофаи 25 сантиметр аз тоҷ метавонад рушдро зиёд кунад. Ин усул дар минтақаҳо бо норасоии обҳои шадид тавсия дода мешавад.</li>\n<li><strong>Бестарин вақт барои ҷойгир кардани шити рӯбиз дар кӯриштарӣ (катиш)и рӯзмарри чист?</strong><br>Бестарин вақт, пеш аз амали бодор ё нӯрхандон аст. Агар рӯзмарри бо роҳи нӯр кунӣ шавад, шитро дар масофаи 15-20 сантиметр аз ҷои ҷойгиршавии нӯр дар канда ҷойгир кунед.</li>\n<li><strong>Масофаи шити рӯбиз дар рӯзмарри ба омор (бедор) вобаста аст?</strong><br>Дар сурати истифодаи оморҳои васеъ (масалан, 80 сантиметр), масофаи шит бояд ба маркази омор наздик бошад, то намдор дар тамоми андозаи беда тақсим шавад.</li>\n<li><strong>Оё масофаи шити рӯбиз дар рӯзмарри бо кӯриштарии корфс фарқ дорад?</strong><br>Бале, корфс ба рӯбҳои чуқуртар ва намдории бештар ниёз дорад. Таҳқиқоти шити рӯбиз барои корфс нишон медиҳад, ки дар он масофаҳо ва оқимҳои гуногун истифода мешаванд. Бинобар ин, ҳар як маҳсул намунаи хоси худро дорад.</li>\n</ol>\n\n<h2>Хулоса</h2>\n<p>Ёфт <strong>Масофаи шити рӯбиз дар кӯриштарии рӯзмарри</strong> Мувофиқ, омезиши шинохти чуқурии рӯб, намуди хок ва шароити иқлимӣ аст. Стандарти тиллоӣ, масофаи 15 то 20 сантиметр аз таҷи растани дар сафҳои 100 то 120 сантиметрӣ аст. Риояи ин масофаҳо, ғайр аз беҳтар кардани сифати растани, аз хароҷоти лозимии об ва энергия пешгирӣ мекунад. Бо назардошти афзудани нархҳои моддаҳои асосӣ, корхонаҳо метавонанд бо истифода аз захиравҳои ҳисобкунии сарфи об дар як гектар, тахмини дақиқтари ниёзҳои корхонаи худ дошта бошанд. Дар охир, назорати мунтазам ва танзими системҳои филтратсия ва помпаҳо кафолати идомаи амали шити рӯбиз ва нигоҳдории рӯбҳои солимани рӯзмарри аст. Риояи ин принсипҳо, сармоягузории бевосита дар самаранокии иқтисодӣ ва сифати маҳсулоти ниҳоӣ аст.</p>','Фосилаи қатори ҷинсфенкурр в заҳрати оромӣ: Меъёрҳои тавсияшуда ва принсипҳои амалиягӣ','Дар ин мақола мо фосилаи аниқи сатҳи лавҳаро дар кишт кардани розмарин, стандарти ҷойгиркунии қаторӣ, интихоби намуди лавҳа бар асоси шароити иқлим ва маслиҳатҳои амалӣ барои баланд бардоштани самаранокии обро баррасӣ мекунем.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
