SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='spinach-planting-guide-drip-band-irrigation' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'spinach-planting-guide-drip-band-irrigation','spinach-planting-guide-drip-band-irrigation-crop-042-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
