SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='cost-cereal-rye-cultivation-drip-tapes-hectare' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'cost-cereal-rye-cultivation-drip-tapes-hectare','cost-cereal-rye-cultivation-drip-tapes-hectare-crop-043-en');
