SET @resolved_slug=IF(@slug_conflict IS NULL,'qiimati-parvishikori-chonak-bo-navare-tiff-tahlili-mufassali-ikiqodi-tehniki','qiimati-parvishikori-chonak-bo-navare-tiff-tahlili-mufassali-ikiqodi-tehniki-crop-043-tj');
