SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-048' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-048:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='fasila-qatori-khumus-kharozi-khumus' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'fasila-qatori-khumus-kharozi-khumus','fasila-qatori-khumus-kharozi-khumus-crop-048-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fasila-qatori-khumus-kharozi-khumus-crop-048-tj-cde7dcba');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p><strong>Муқаддима: Аҳамияти геометрияи оҳимӣ дар парвариши чаводар</strong></p><p>Чаводар (Secale cereale) ҳамчун яке аз донҳои бӯда, на танҳо тобоварии баланди ба сармо дорад, балки нисбат ба зердавидани об низ ҳассосиятҳои мушаххас дорад. Дар системаҳои оҳимии муосир, интихоби дурусти чидиши сатҳӣ (Row Layout) ва муайян кардани дақиқи <strong>фосилаи шитори оҳимӣ</strong> метавонад муайянкуни охирини дараҷаи ҳосилнокӣ ва ҳадди беморшавии реша бошад. Бисёре аз кишоварон ҳангоми насби шитори оҳимӣ танҳо ба кодбандии булурҳои обдиҳанда диққат медиҳанд, аммо тағйирёбандаи фосила байни шиторҳо ва сатҳҳои ҳиссаи ғалъа одатан дар назар гирифта намешавад. Ин фосила бояд ҳампаҳлӯгии минтақаҳои тар бо реша (Wetted Bulb)-ро ба таври чунин ба аморар орад, ки ҳамаи решаҳо барои раста дар дастрасӣ бошанд, бе он ки боиси аз даст додани захираҳои об ё пайдоиши бемориҳои қарозеъ тавассути ғарраи зиёд гардад.</p><h2>Омилҳои асосӣ дар муайян кардани фосилаи шитори оҳимӣ</h2><p>Ғайри вуҷуди рақами собит барои ҳамаи дучархоҳои чаводар, ниёз ба таҳлили тағйирёбандаҳои маҳаллӣ ду баробар меафзояд. Омили зерин нақши асосӣро дар тарроҳии геометрияи оҳимӣ бозиш меомӯзанд:</p><ul><li><strong>Навъ ва андозаи хок:</strong> Дар хокҳои шубии бо муҳобатии баланд, фосилаи шиторҳо метавонад камтар бошад, зеро кӯлакҳои тар бо суръати зиёд паҳн мешаванд. Дар ҳамоҳанг, дар хокҳои чӯгин, фосилаҳои зиёдтар лозим аст, то аз немоиши таҳқиқшавии табақаи берунӣ аз ҳориентсияҳои решагӣ пешгирӣ карда шавад.</li><li><strong>Зичии натиш (Planting Density):</strong> Чаводар одатан дар зичии мушаххас натиш мекунад. Агар зичии натиш дар сатҳҳои асосӣ аз 45 то 60 сантиметр бошад, фосилаи шитори оҳимӣ аз маркази сатҳ бояд бо дақиқат баррасӣ шавад, то рақобат байни решаҳо ва системаи оҳимӣ мувозинат боҳад.</li><li><strong>Навъи шитори оҳимӣ:</strong> Шиторҳое, ки деворҳо бо ғафсии муносиб доранд, монанд ба <a href="https://navar-abyari.ir/ideal-wall-thickness-drip-tape-irrigation/">ғафсии идеалии шитори оҳимӣ</a> бар зидди фишори система, тақсимоти баробартар доранд ва дар тарроҳии фосилакунии имконияти истифодаи булурҳои обдиҳанда бо омади камтарро фароҳам меоранд.</li></ul><p><strong>Алоқаи фосилаи шитор ва самаранокии иқтисодиёти кӯшиш</strong></p><p>Як хатои маъмул, наздик кардани зиёда аз ҳад шиторҳо ба поёнҳои сатҳҳо аст. Дар чаводар, решаҳо дар соли аввали растанӣ бо суръати хеле баланд дар амиқӣ дохил мешаванд. Истифодаи <a href="https://navar-abyari.ir/foidai-norabiyari-tip/">шитори оҳимӣ</a> бо фосилаи стандартӣ ва омади муносиб, боиси мешавад, ки решаҳо ба сурат ба захираҳои озуавӣ ҷазб шаванд. Таҳқиқот нишон медиҳанд, ки беҳтар кардани фосилаи шитор, метавонад таъсирҳои муҳоҷирати зиёд кардани зичии ғалъа дар кӯшишҳои мушаххас, монанди <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b3%db%8c%d8%b1-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми бӯри сармоя</a> дар системаҳои гуногун бошад; яъне бо зиёд шудани зичии самаранок ва идоракунии дуруст, самаранокии умумии баландтар даст оварда мешавад.</p><p></p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-چاودار-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت چاودار: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>масофаи ҷойгиршавии ҷуръа ва ҷулои зироат ҷулҷӯлашӯб</figcaption></figure><h2>Стандартҳои тавсияшуда барои масофагирии навбаи drip tape</h2><p>Аз рӯи таҷрибаҳои майдонӣ дар минтақаҳои хуравони гуногун, ҷадвали зерин чорчакуи асосӣро барои муайян кардани масофаи навбаи drip tape аз ҷуръаҳои ҷулҷӯлашӯб пешниҳод мекунад. Ин рақамҳо бар асоси дэбитҳои оддӣ (1/5 то 2/5 литр дар як соат) танзим шудаанд.</p><table><thead><tr><th>Даромади хок</th><th>Масофаи пешниҳодии навба аз қабатҳои поёнии ҷуръа (сантиметр)</th><th>Шарҳи техникии</th></tr></thead><tbody><tr><td>Резӣ/Қумӣ</td><td>10 - 15</td><td>Парокуншавии зуддони тарракӣ, ниёз ба наздиктар будан барои пешгирии хушкшавии қабатҳои паҳлӯӣ.</td></tr><tr><td>Шинори</td><td>15 - 25</td><td>Мувозинат байни гузаштагӣ ва нигоҳдории тарракӣ; беҳтарин вариант барои аксари минтақаҳо.</td></tr><tr><td>Резӣ/Оғоз</td><td>30 - 40</td><td>Ҷорӣ баровардани ниҳолӣ бо доезаҳои камтар, масофаи зиёдатар барои пешгирии пуршавии қабати рӯяндарӣ.</td></tr></tbody></table><p><strong>Нуқтаҳои иловагӣ дар ҷойгиркунии ҷуръаҳо</strong></p><p>Ҳангоми даромадани ба ифтори <strong>Фосилаи нақшҳои лентаро барои ош (чавдар)</strong>, тарҳи қаторҳои ҷанубӣ-шимолиро низ ба назар гиред. Агар деҳот бо усули ширкушӣ (фуроркунӣ) шиношуда шаванд, лентаро бояд дақиқ дар ширҳо ҷойгир кард. Дар шароитҳое, ки истифодаи обёри чистӣ (чоробӣ) ё усулҳои монанди онро барои заминҳои поёнӣ (пайоб) дар назар доранд, мутобиқат кардани фосилаи қаторҳо бо системаи сармои (дарқатра) аҳамияти дукарата меёбад. Номутобиқати геометрияи ширҳо бо лентаҳо ба аз даст рафтани об ва коҳиши ҳосил меомад. Инчунин, монанди аҳамияти муайян кардани <a href="https://navar-abyari.ir/rozmary-hosildori-dar-yak-gektar/">ҳосилнокии рамари дар як гектар</a> бар асоси зичӣ, ҳосилнокии чавдар низ қавӣ ба зичии муъассири ва пӯшиши (пошиши) лентаҳо вобаста аст.</p><p></p><h2>Нуқтаҳои амалӣ барои иҷро ва насб кардани лентаро</h2><ol><li><strong>Санҷиши пеш аз насб:</strong> Ҳамеша пеш аз кашидани лентаро, сатҳи заминро тавонун (мувозинат) кунед. Барои огоҳ шудан аз сабабҳои зарурати ин амал, мақолаеро дар бораи аҳамияти санҷиши замин барои лентаро ва лӯлаҳои полиетиленӣ хонед. Шубораҳои (шуҳб) нагаҳонӣ боиси ҷамъшавии об дар як тарафи лентаво ва хушк шудани тарафи дигар мегарданд.</li><li><strong>Насб дар чуқурӣ:</strong> Дар ҳолати имконпазир, лентаҳоро дар зери сатҳи замин (10 то 15 см) ҷойгир кунед. Ин кор дар асоси (бо роиш) ба тагун (тагуни) об ӯҳдагардӣ карда, фосилаи муъассири лентаро аз реша мекушояд.</li><li><strong>Истифодаи филтри мувофиқ:</strong> Чавдар ба гирифтор шудани реша ҳассос аст. Истифодаи филтрҳои кӣстагӣ (кисти) бо зарраҳои (дана) мувофиқ кафолат медиҳад, ки <a href="https://navar-abyari.ir/foidai-norabiyari-tip/">лентаро</a> дар тамоми умри фано (умри корӣ) оқими (дебит) устуворро нигоҳ дорад.</li></ol><h2>Саволҳои оддӣ (FAQ)</h2><p><strong>1. Оё фосилаи лентаро дар чавдар бо гандум фарқ дорад?</strong></p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-چاودار-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت چاودار: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop чавдар</figcaption></figure><p>Бале. Чавдар решаҳои чуқуртар ва мукотуб (ҳаётан) ба сармо дорад. Гарчанде ки масофаи ғавор (кунҷ) дар ҳосилмонӣ монанд аст, вале чавдар одатан дар шароити хушктар шиношуда мешавад ва бинобар ин ба ҳосилнокии чуқуркунии решаҳои поёнӣ ниёз дорад. Фосилаҳои тавсияшуда барои чавдар баъзан каме камтар аз гандум аст, то ки пӯшиши (пошиши) об дохилҳо ба андозаҳои миёна расад.</p><p><strong>2. Ҳангоме ки аз ду нақб нинг дар як сатҳ истифода барем?</strong></p><p>Агар фурсати сатҳҳои ҷавдол зиёда аз 50 сантиметр бошад ё хок чангу вазнин бошад, истифодаи ду нақб бо сарфиши камтар ба ҷойи як нақб бо сарфиши баланд тавсия дода мешавад. Ин тартиб тақсимоти баробартари намнокӣ-ро ба вуҷуд меорад ва ба тартибҳои беҳтаршуда барои зиёд кардани самаранокии растаниҳо бо решаи ҳассос монан аст. Албатта, ин усул хароҷоти насбкунӣ-ро ду баробар мекунад ва боздошти иқтисодии он бояд арзёбӣ шавад.</p><p><strong>3. Оё масофаи нақб нинг ба фурсати ғаллоти ҷавдол дар минтақаҳои гуногун, ба монанди Узбекистон, таъсирасоӣ дорад?</strong></p><p>Стандартҳо бар асоси иқлиму намуди хоки маҳаллӣ мебошанд. Дар минтақаҳое, ки шартҳои сахттар доранд, ба монанди намунаҳои иқлимӣ, ки бо <a href="https://navar-abyari.ir/sorgum-yield-per-hectare-tajikistan/">самаранокии саргон дар Тоҷикистон</a> ё минтақаҳои дигари хушк алоқаманд аст, масофаи нақбҳо бояд бо эҳтиёткориҳои зиёдатар нисбат ба хушкшудани зудии сатҳ танзим карда шаванд. Паҳлӯпаҳлӯ шудани решаҳои ҷавдол дар ин шартҳо ҳақиқати баландтарро талаб мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-چاودار-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت چاودار: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>масофаи нақб нинг тартиби сатҳ ҳосил ҷавдол</figcaption></figure><p><strong>4. Чӣ тавр аз дучуфт шудани нақб дар давоми рушди ҷавдол пешгирӣ кунем?</strong></p><p>Истифодаи нақбҳое, ки ба корди ӣшъои UV ва фуз резистантанд, бо илова кардани насбкунии ибтидоии дуруст тавассути сипин ё сим, калиди устуворӣ аст. Инчунин, аз рафти мошинҳои вазнин болои нақбҳо дар марҳилаҳои ибтидоии ғаллот парhez кунед. Ин қоидаҳо бо принсипҳои умумӣ дар <a href="https://navar-abyari.ir/kudwa-natiq-iq-production-per-hectare-drip-tape/">зиёд кардани самаранокии дар системаи нақб нинг</a> мувофиқат доранд.</p><p></p><h2>Хулоса: роҳи беҳтаркунии ғаллоти ҷавдол бо нақб нинг</h2><p>муайян кардани <strong>масофаи нақб нинг дар ғаллоти ҷавдол</strong> як формулаи сода нест, балки натиҷаи омехтаи дониш аз сохтори хок, фурсати ғаллот ва сарфиши қатраҳост. Мақсади ниҳоӣ, эҷоди ноҳияи намноки беҳтаршудаест, ки решаҳои ҷавдолро дар тамоми марҳилаҳои рушд (аз тарма то пур шудани дони) дар пошт моқунад. Тавсияи ниҳоии мо ин аст, ки пеш аз иҷрои тамоми масоҳат, дар як қисми хурди деҳот ду масофаи гуногунро (масалан, 15 ва 25 сантиметр) санҷед ва фаъолиятро дар охири мавсим муқоиса кунед. Бо риёяти принсипҳои танзимкунишуда, истифодаи қатраҳое, ки ғафсшавии деворашон мувофиқ аст ва ба назар гирифтани тартиби сатҳӣ, шумо метавонед самаранокии обро дар деҳотҳои ҷавдолро ба сатҳи ҳақиқӣ расонед. Диққат ба нохӯлиҳои техникии нақб нинг, на танҳо хароҷоти амалиётӣ-ро кам мекунад, балки бо зиёд шудани сифати дони, арзиши тиҷоратии ҳосилро низ баланд мебардорад. Дар ниҳоят, машварат бо мутахассисони маҳаллии обориш бо қатраҳо барои мутобиқ сохтани ин роҳнамо бо шартҳои дақиқи деҳоти шумо, қадамро зарурӣ барои даст овардани боварӣ аст.</p>','Фосилаи қатори хумус дар парҳези хумус: Тағйиротҳои тавсияшуда','Муайяни дақиқи масоҳати риштаҳои нӯрӣ дар кӯштани чӯдодар тақозоии фаҳмиши амиқ аз фарҳасти кишоварӣ, намуди системаи обёрӣ ва шароити иқлимро дорад. Дар ин роҳнамои ҷамъбасти мувофиқи масоҳати риштаҳо барои кам кардани стресси обӣ ва зиёд кардани фаъолияти наҷиб баррасӣ мешавад.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
