SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='miqdori-tohi-rasmari-dar-hektar-rohnamo' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'miqdori-tohi-rasmari-dar-hektar-rohnamo','miqdori-tohi-rasmari-dar-hektar-rohnamo-crop-049-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
