SET @resolved_slug=IF(@slug_conflict IS NULL,'harchai-kurkhuri-khur-riba-dar-yek-gektar-rahnami-iqtsodi-tekniki','harchai-kurkhuri-khur-riba-dar-yek-gektar-rahnami-iqtsodi-tekniki-crop-050-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'harchai-kurkhuri-khur-riba-dar-yek-gektar-rahnami-iqtsodi-tekniki-crop-050-tj-098a8c2c');
