SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='drip-tape-spacing-for-melon-cultivation-recommended-standards' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'drip-tape-spacing-for-melon-cultivation-recommended-standards','drip-tape-spacing-for-melon-cultivation-recommended-standards-crop-060-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
