SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-060' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-060:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='fosila-ripi-koshi-khurbi' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'fosila-ripi-koshi-khurbi','fosila-ripi-koshi-khurbi-crop-060-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fosila-ripi-koshi-khurbi-crop-060-tj-d76619c9');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи аҳамияти ҷойгиршавии дурусти лавҳаҳои нафаси ҳассобӣ дар кбудани тарбуз</h2><p>Кбудани тарбуз бо сабаби вазъияти махсуси решаҳо ва ҳассосияти баланди ин растани ба зероии об яке аз истифодаҳои муассир системаҳои нафаси ҳассобӣ мебошад. Интихоби фосилаи мувофиқ байни сафҳо ва ҷойгиршавии дурусти лавҳа таъсири мустақим ба амиқшавии намӣ, инкишофи решаҳо ва дар натиҷа вазн ва сифати мева дорад. Дар кбудҳои муосир, ҳадафи асосӣ кам кардани ҳаҷми обии истифодашуда тавассути ороишгузории маҳаллӣ аст; аммо агар фосилаи сафҳо бо намуди лӯлаҳои нафаси ҳассобӣ мувофиқ набошад, на танҳо аз ин бенафъӣ истифода намекунем, балки ба хушкшавии nisbӣ дар қабатҳои амиқи хок дучор мешавем.</p><p>Боз ҳам таъкид мекунем, ки «фосилаи лавҳаи нафаси ҳассобӣ» на танҳо ба андозаи физикии лӯла ишора мекунад, балки як силсилаи тағйирёбандаҳоро дар бар мегирад, ки дар онҳо фосилаи сафҳои кбуд, фосилаи нафасҳо дар лӯла, намуди хок ва шиддати офтобӣ илова шудаанд. Тағйирёбандаҳои зерин дар муайян кардани фосилаи ниҳоӣ нақш доранд:</p><ul><li>Намуди хок (ришти, лъомӣ, силтӣ)</li><li>Намунаи тарбуз ва марҳалаи рушд</li><li>Усули кишвар (як саф, ду саф, чӯҳкории)</li></ul><h2>Стандартҳои техникии муайян кардани фосилаи сафҳо ва лавҳа</h2><h3>Таъсири амиқии решаҳои тарбуз ба самаранокии об</h3><p>Системаи решаҳои тарбуз то андозае сатҳӣ аст, аммо дар марҳилаҳои аввалини рушд, дахоли амиқи решаҳо барои устувии растани зиндабуд аст. Бинобар ин, фосилаи лавҳаи нафаси ҳассобӣ набояд он қадар зиёд бошад, ки минтақаи хушк байни ду лавҳа васеъ шавад ва набояд он қадар кам бошад, ки намии иловагӣ боиси фасилшавии решаҳо ва бемориҳои қаламчагӣ гардад. Асоси <a href="https://navar-abyari.ir/%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%DA%A9%D8%B4%D8%A7%D9%88%D8%B1%D8%B2%DB%8C/">Пайвасткуниҳоии лавҳаҳои нафаси ҳассобии кишоварзӣ</a> ва принсипҳои ҳидроликӣ, як формулаи таҷрибавӣ барои ҳисоб кардани фосилаи максималии лавҳа дар асоси радиуси дахоли нафасҳо вуҷуд дорад. Дар шароити муқаррарӣ, фосилаи нафасҳо дар лавҳа ба андозаи 20 то 30 сантиметр танзим карда мешавад. Агар фосилаи нафасҳо 20 сантиметр бошад, фосилаи ду сафи лавҳа, ки дар ҳар сафи кбуд ҷойгир шудааст, одатан бояд дар фосилаи 80 то 100 сантиметр бошад, то минтақаи намдор зери решаи асосии растани пӯшида шавад.</p><h3>Ҷадвали роҳнамоии фосилаи лавҳаи нафаси ҳассобӣ дар кбудани тарбуз дар асоси намуди хок</h3><table><thead><tr><th>Намуди хок</th><th>Фосилаи пешниҳодии нафас (сантиметр)</th><th>Фосилаи сафҳо (сантиметр)</th><th>Шарҳҳо</th></tr></thead><tbody><tr><td>Ришти ва сабук</td><td>20</td><td>80 то 90</td><td>Гузиши бадкунӣ тез, ниёз ба тамаркузи пудкунии даҳонӣ</td></tr><tr><td>Луми миёна</td><td>25</td><td>90 то 105</td><td>Бартарин самаранокии иқтисодӣ, мувознати хуб</td></tr><tr><td>Силогӣ ва вазнин</td><td>30</td><td>110 то 120</td><td>Гузиши бадкунӣ аҳолӣ, имконияти кам кардани шумораи пудкунҳо</td></tr></tbody></table><p>Мушоҳида мешавад, ки дар хокҳои силогӣ, масофаи пудкунҳо метавонад зиёдтар бошад, зеро об ба шиддати камтар ба хок мерезад ва рағобат дар қабатҳои болоӣ дарозмуддаттар мемонад. Илова бар ин барои <a href="https://navar-abyari.ir/agricultural-drip-tape-connectors/">Пайвастагии пудкунҳои тиби кишоварӣ</a> Бояд диққат дод, ки ҳеҷ гуна сарфи абое вуҷуд надорад, зеро дар сохторҳои вазнин, сарфи абое ҳатто бо миқдори кам метавонад боиси селбӯрӣи нисбии ҷои пайвасткунӣ ва вазъ ба решаҳо гардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-خربزه-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت خربزه: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>масофаи пудкун тартиб додани хат ғалоба хурмуқ</figcaption></figure><p></p><h2>Нуқтаҳои амали барои баҳурзакунӣ ҷойгиркунии пудкун ва ҳар</h2><h3>Таъсири тартиб додани ҳар ба интихоби масофаи пудкун</h3><p>Дар ҳари хурмуқ, ду усули маъмули кишт вуҷуд дорад: кишт дар як хат бо масофаҳои тӯлонитр ва кишт дар ду хат (тукар). Дар усули дуюм, ки оддитар аст, масофаи байни ду хати асосӣ оддатан 120 то 150 сантиметр мебошад. Дар ин ҳолат, пудкунӣ тиби дақиқан дар маркази ҳар хати ҳар ҷойгир мешавад. Ба ин тавр, масофаи афкунӣ аз пудкун то маркази хати овардабардор нисфи масофаи хатҳо аст. Пас агар масофаи ду хати ҳар 140 сантиметр бошад, радиуси паҳш кардани рағобат ҳатман бояд ақалл 70 то 75 сантиметрро фаро гирад, то ки решаҳои канории растанҳои ҳамхат ба об кофӣ дастрасӣ дошта бошанд. Ин ҳисобкунӣ дақиқтар аз ишораи масофаи мувофиқ бо кӯмаки андозаҳо барои пудкун дар гектар ва стандарҳои маҳаллӣ муайян карда мешавад.</p><h3>Нуқтаҳои амали насб ва нигоҳдорӣ</h3><ol><li><strong>Коркиш ва ҳамзамонишуда лента:</strong> Лентаро чунин бинед, ки нуқтаи пайвастшавии лӯлаҳо дақиқан зери байни ду боб (бӯи) ҷойгир бошад, то решаҳо метавонанд аз нуқтаҳои қавитар намдӣ истифода баранд.</li><li><strong>Пӯшиши пластикӣ:</strong> Истифодаи пӯшиши пластикии сафед ё нуқфарранг байни лентаи коҳишбахорро барои коҳиши бугори сатҳӣ ба таври қавӣ зиёд мекунад ва ҳарорати хокиро барои рушди тарбуз идъоал нигоҳ медорад.</li><li><strong>Назорати фишор:</strong> Бо зиёд шудани шидати замин, фишор дар поёнҳои лента зиёд мешавад. Барои танзими масофаи қатраҳои таъсиркунанда, аз лентаҳои бо тарҳбандии муқобилитанзими ва пайвасткуниҳои пайвандашуда истифода баред.</li><li><strong>Барқарорсозии лента:</strong> Пас аз парвариши тарбуз, бояд лента барои фасли оянда ба ҳадди кофӣ нисбат дода шавад; <a href="https://navar-abyari.ir/afzaliyathoi-lentai-qatragi/">Зиёд кардани умри лентаи қатрагӣ</a> Бо ҷамъ кардани дуруст он имконпазир мегардад.</li></ol><p></p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-خربزه-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت خربزه: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop тарбуз</figcaption></figure><h3>Таъсири рӯшноӣ ва ҳарорат ба самаранокии лента</h3><p>Метритҳои интихоби масофа бояд чунин бошанд, ки дар нимшаб ва ҳангоми хунукӣ, намдҳои иловагӣ дар хок ҷамъ нашавад ва дар заҳари боб, хушкӣи қабати хок қобили қабул бошад. Тарбуз дар моҳҳои гарми боб ба обёрии доимӣ, аммо кӯтоҳмуддат ниёз дорад, то решаҳо чашн нахӯранд. Ҷойгиркунии лентаи қатра ба тавре танзим шавад, ки барориши намнокии ҳудудӣ тақрибан ду сеум то се чорями масофаи байни сатҳҳои коркӣ паҳн шавад; ин ҳолат идъоал барои идоракунии рушди ҷудогона, идоракунии об ва пешгирии бемориҳои реша аст.</p><h2>Ҷавоб ба саволҳои оммавӣ (FAQ)</h2><h3>Оё масофаи қатраҳо метавонад дар тӯли фасл тағйир ёбад?</h3><p>Не, масофаи қатраҳо сохторӣ дар лента аст ва тағйироти физикӣ доданаш имконнокист. Аммо метавон аз лентаҳои гуногун бо масофаи 20, 25 ё 30 сантиметр барои қисмҳои гуногуни замин (бояни шидат ва сифати хок) истифода бурд. Тағйирот бояд аз оғози фасл, ҳангоми коркиш, муайян шавад.</p><h3>Дар ҳолате, ки хоки замин якхела нест, чӣ тавр масофаро интихоб мекунем?</h3><p>Дар ин шартҳо, тақсим кардани замин ба зонаҳои обёрӣ тавсия дода мешавад. Барои зонаҳои хоки сабук, масофаи қатраҳои 20-сантиметрӣ ва барои зонаҳои хоки вазнин, масофаи 30-сантиметрӣ мувофиқтар аст. Инчунин метавон аз <a href="https://navar-abyari.ir/musir-hosilagiri-dar-hektyar/">Роҳҳои баланд бардоштани ҳосил бар ҳектар</a> Бо истифода аз сенсорҳои намии хок дар нуқтаҳои гуногун барои идоракунии дақиқтар. Истифода кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-خربزه-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت خربزه: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>фавоси лентҳои дарини, тарҳи сафҳо, парвариши хурма</figcaption></figure><h3>Агар намӣ байни ду лента дар тӯли фасли хушк боқӣ монад, чӣ бояд кард?</h3><p>Дар ин ҳолат, ин нишонаи он аст, ки фосилаи лента нисбат ба чуқурии решаи растаниҳо дар минтаха хеле зиёд аст. Дар фасли оянда, бояд фосилаи дариниҳоро камтар дар назар гирифт (масалан, тағйир аз 30 ба 25 сентиметр) ё фосилаи байни сафҳоро каме кам кард, то пӯшиши намӣ пурра шавад.</p><p></p><h2>Хулоса ва маслиҳатҳои ниҳоӣ</h2><p>Интихоби фосилаи лентаи даринӣ ҳангоми парвариши хурма як қарори чандуметағирдор мебошад, ки омезиши сифати хок, навъи системаи дарини ва шароити иқлимии минтаҳаро дар назар мегирад. Ба таври кӯтоҳ, барои аксари деҳқониҳо бо хоки лумӣ ва парвариш дар ду саф, фосилаи дариниҳои 25 сентиметрӣ дар фосилаи 90 то 105 сентиметрӣ аз маркази парвариш мувозинати мувофиқ байни истеъмоли об, рушди расадӣ ва сифати маҳсулро фароҳам меорад. Рӯиҳарамии принсипҳои насб, пайвасткунии дуруст ва назорати фишор калиди муваффақият дар истифодаи бартарии лентаи даринӣ мебошад. Бо дидагирӣ ба ин принсипҳо ва меъёрҳои зикргардида, шумо метавонед бо ваъди беҳтарӣ ба зиёд шудан самаранокӣ ва кам шудани хароҷоти манбаъҳои об кӯмак расонед.</p>','Фосилаи нӯрип дар кӯши хурби: Мавзуҳои тавсияшуда','Шиносои беҳтарин масоҳати нӯри тип дар ҳашари хушмев барои зиёд кардани самаранокӣ ва кам кардани истеъмоли об. Раҳнамои пурра бо нуқтаҳои амалӣ, меъёрҳои фаннӣ ва ҷавоб ба саволҳои маъмула.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
