START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-062' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-062:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='miqdori-bexi-kominali-har-hektar' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'miqdori-bexi-kominali-har-hektar','miqdori-bexi-kominali-har-hektar-crop-062-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'miqdori-bexi-kominali-har-hektar-crop-062-tj-76e8b924');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи аҳамияти дақиқӣ дар ҳисобкунии миқдори томони камеллиа</h2><p>Рушди иқтисодии Эрон дар қисми боғдории саноатӣ, ба таври мустақим ба интихоби дурусти намуд, сорт ва <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%DA%AF%D9%88%D8%AC%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">миқдори томон</a> барои воҳиди сатҳ вобаста аст. Камеллиа, ҳамчун набототи камеллиаи тиҷоратӣ, ки ба ҳаросӣ нисбат ба ҷинс ва омили иҳотӣ ҳассос аст, ба барномаи дақиқ ниёз дорад. Баҳсӣ аз кишлонон танҳо ба маблағгарии томон иштиҳом кунанд, аммо хато дар ҳисобкунии зичии пайдоиш (Population Density) метавонад ба камшавии баланд ва ҳосилнокӣ дар охир дар давраи истеҳсол кор шавад. Дар ин дастуворӣ, бо таваҷҷух ба принсипҳои физиологияи набототӣ ва муҳандисии обиробӣ, формулаҳои таҳияшуда барои ҳисобкунии дақиқи томонро пешниҳод мекунем, то сарфазам аз манбаҳои об ва хок ба ҳадди ақал расад.</p><h2>Омилҳои таъсиркунанда ба муайян кардани шумораи томон дар гектар</h2><p>Баръакси набототи ҷинсӣ, ки хусусиятҳои ҷинсий 1:1 доранд, камеллиаҳои тиҷоратӣ зери таъсири стрессҳои муҳитӣ қарор доранд. Ин стрессҳо метавонанд мувозинати ҷинсиро ба ҷони гони модарӣ вайрон каранд. Бинобар ин, ҳисобкунии миқдори томон танҳо 20000 дараҷа гармӣ нест, балки функсияи солим будани асоси томон ва иқлими ҳосилот аст.</p><ul><li><strong>Иқлими гарм ва хушк:</strong> Дар минтақаҳои ҷанубӣ, истифодаи томон бо сифати баландтар (стандарти 98%) ва зичии баландтар лозим аст, то аз камшавии коэффисиенти нобузарӣ пешгирӣ шавад.</li><li><strong>Иқлими моътанон:</strong> Дар минтақаҳои шимолии қаториш ва марказӣ, бо риоя кардани масофаҳои стандартӣ, зичии камтар метавонад сабабгари рушди беҳтари савгош шавад.</li><li><strong>Ҷинси наботот:</strong> Бо назардошти он, ки гони камеллиаҳо яккомплесн мебошанд, фоизи гони саломат бояд дар ҳисобкунии ниҳоӣ истифода шавад, то аз камшавии гулгунобарӣ пешгирӣ карда шавад.</li></ul><h3>Формулаи ҳисобкунии зичии пайдоиш (аз рӯи ҷинс)</h3><p>Барои расидан ба сатҳи баланди иқтисодӣ, бояд аз формулаи зер барои ҳисобкунии <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%a8%d8%a7%d8%af%d8%a7%d9%85-%d8%b2%d9%85%db%8c%d9%86%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори томон</a> дар гектар истифода баред:</p><p><strong>Миқдори томон (килограмм дар гектар) = (шумораи пичлаки даромадат × коэффисиенти ислоҳи ҷинсӣ) / фоизи пурстасӣ</strong></p><p>Дар шароити идеалӣ, коэффисиенти ислоҳи ҷинсӣ 1.0 фарз мекунад, аммо дар минтақаҳои куҳӣ тавсия мешавад, ки ин коэффисиент ба 1.2 зиёд карда шавад, то носозиҳо аз гулгунобарии нокофӣ ҷуброн шавад. Ин ҳисобкунии мисоли равобҳои истифодашуда дар ҳисобкунии <a href="https://navar-abyari.ir/dry-fava-bean-yield-per-hectare-guide/">Истишоъи баклаван</a> ва дигар наботи гулдорӣ, ки ҳассосияти баланд ба зичӣ доранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کاملینا-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر کاملینا در هکتار: راهنمای جامع - تصویر 1"/><figcaption>seed rate per hectare crop камелина</figcaption></figure><><h2>Истилои кунҷӣ ва идоракунии масофаҳо</h2><p>Камелина наботе аст, ки ба ҳавои хуб ниёз дорад. Корбандии зич аз пӯшишони баргҳо пешгирӣ мекунад, аммо зичии зиёд боиси зиёд шудани бемориҳои қарчобӣ ва камии нур дар сатҳи хок мешавад. Беҳтарин усули кунҷӣ, кунҷӣ дар риштаҳои тарк бо масофаи мувофиқи «раннер» аст.</p><ol><li><strong>Масофа байни риштаҳо:</strong> Аз 70 то 100 сантиметр, вобаста ба системаи обёрӣ ва иқлим.</li><li><strong>Масофа дар дохили ришта (ташаккул):</strong> Аз 10 то 15 сантиметр барои иқлимҳои гарм.</li><li><strong>Дирақи кунҷӣ:</strong> Аз 2 то 3 сантиметр; кунҷии чуқур боиси паҳлӯи гулҳо мешавад ва боиси ғайриимконии бардошт мегардад.</li></ol><p>Бо танзими дурусти масофаҳо, шумо амалан дораи ниҳоии бӯриро дар сатҳи ораҳамгаронӣ муайян мекунед. Агар аз бӯри сифатнок истифода баред, шумо метавонед масофаи байни риштаҳоро кам намуда, аз зичии зиёдтар барои пӯшиши тезтари хок истифода баред. Ин масъала дар минтақаҳое, ки равшӣ қавӣ мебошад, ҳаётии аст, зеро наботи қавиртар муқовимати беҳтарро нисбат ба эррозия (печӯм) доранд.</p><<h2>Нақши ҳаётии системаи обёрӣ буқадобӣ ва риштаи тири</h2><p>Яке аз бузургтарин душвории кунҷии камелина, ҳассосияти реша ба хфакӣ аст. Решаи камелина бояд ҳамеша ҳавогирии мувофиқ дошта бошад. Дар ин роҳ, истифода аз риштаҳои тири обёрӣ бо ғади мувофиқ, калиди муваффақ аст. Риштаи тири бояд анико зери таҷи решагӣ ҷойгир шавад, то об мустақиман ба минтақаи решагӣ расад ва на ба савазӯ, ки боиси пӯри мегардад.</p><p>Барои интихоби системаи мувофиқ, ба тавсифоти фаннии риштаи тири обёрӣ диққат диҳед. Як системаи стандартии бояд аз ланги тири бо ғати 16 ё 20 миллиметр, суръати омадани дарачакаҳо 2 литр дар як соат, ва масофаи дарачакаҳо (Emitter Spacing) 20 сантиметро дар бар гирад. Ин танзимот таъмин мекунад, ки намии хок ба таври якхела дар решагони зиёди камелина паҳн шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کاملینا-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر کاملینا در هکتار: راهنمای جامع - تصویر 2"/><figcaption>seed rate per hectare crop камелина</figcaption></figure><h3>Барномаи обёрӣ, ки ба асоси маълумоти обу ҳавоӣ асос мегирад</h3><p>Обёрии камелина набояд аз пешина реҷагузорӣ шавад, балки бояд бар асоси нишондиҳандаи фишори хфакӣ (Water Deficit) танзим гардад. Агар аз системаҳои ҳосилнок истифода баред, сенсорҳои намии хок (Moisture Sensors) бояд дар чураи 15 сантиметрӣ насб карда шаванд. Кам шудани намӣ аз 60% қобилияти шинонавӣ, нисхонаи аввалини стресс ва падидани гул аст. Дар ин ҳолат, ҳаҷми обёрӣ бояд зиёд шавад, аммо давомнокии обёрӣ бояд кӯтоҳ бошад, то аз шинонавии пурраи хок пешгирӣ карда шавад. Ин равиш монанди принсипҳост, ки дар идоракунии миқдори об дар боғҳои саноатии дигар, ки таъкидро ба нигоҳдории мувозинати об-оксиген мегузоранд, ба кор меравад.</p><<h2>Такрикоҳои амалӣ барои зиёд карди ҳосил ва кам карди таҳом</h2><p>Аксари кишоварон пас аз кабудӣ нигарони сифати гул доранд. Барои ҳалли ин масъала, чанд нуқтаи муҳимро риоя кунед:</p><ul><li><strong>Гуминги боб (Seed Priming):</strong> Пеш аз кабудӣ, бобро 30 дақиқа дар оби дистиллӣ ҷой диҳед, то сатҳи прейстасия зиёд шавад. Ин кор махсусан дар охири тирамоҳ ва аввали зимистон, вақте ки ҳарорат паст аст, бисёр самаранок аст.</li><li><strong>Гизокунии решаҳо:</strong> Истифодаи маҳсулоти кӯдашҳои калий ва фосфат бо роҳи обкунии қатрагӣ (Fertigation) дар марҳилаи ниҳолӣ, боиси мустаҳкам шудани гликумҳои низои ҷинсӣ мегардад ва пареши гулро кам мекунад.</li><li><strong>Идоракунии ҳашараҳо:</strong> Ларваҳои хокзистаи Гриптл (Grub) душмани рақами як решаи кампанла мебошанд. Пеш аз кабудӣ, ҳатман аз маҳсулоти хокбозии мувофиқ истифода баред. Решаи осебдида ба зудӣ нест мешавад ва боби сафишгарданда бе ҳосил аст.</li></ul><p>Ҳамчунин, диққат диҳед ба <a href="https://navar-abyari.ir/vegelatable-harvest-yield-per-hectare-guide/">бардоштани сабзавот</a> ва ҳамои мувофиқи бардошт, метавонад умри гулро зиёд кунад. Кампанла намуде ҷунбиш дар кӯҳкунии гулҳои хоб аст; бинобар ин, бардошт бояд ҳамзамон бо қуллаи гулбарорӣ амалӣ шавад, то сифати дана (Grain Size) таъмин гардад.</p><h2>Саволҳои зуд-зуд такроршаванда (FAQ)</h2><h3>1. Оё имкони кам кардани истеъмоли боб бо истифода аз муҳассанҳои убуш мавҷуд аст?</h3><p>Не, муҳассанҳо ба афзоиши ҷунбиш таъсир мерасонанд, аммо ба ҷинс ва шумораи данаҳо таъсири бевосита надоранд. Танҳо роҳи кам кардани истеъмоли боб, истифода аз боби сифатнок (High Purity) аст, ки сатҳи наҷот (Salvage Rate) ба баландтар бошад. Кам кардани боб бе зиёд кардани сифат, боиси хатарбаландии гулҳои муждуку ғарқ мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کاملینا-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر کاملینا در هکتار: راهنمای جامع - تصویر 3"/><figcaption>миқдори боб дар як гектар барои кампанла</figcaption></figure><h3>2. Беҳтарин вақти кабудии кампанла дар минтақаҳои ҷанубӣ куҷо аст?</h3><p>Барои минтақаҳое, ки тобистони гарм доранд (нимегармсафа), кабудии мутобиқ аз охири моҳи октябр то аввали моҳи декабр аст. Ин давра боиси он мегардад, ки гулбарорӣ дар фаслҳои хунуктар сурат гирад, ки стресси гармӣ (Heat Stress) бар гулбарориро кам мекунад ва ниёз ба дани боб дар як гектарро аз ҷиҳати сифат стандарттар мегардонад.</p><h3>3. Оё системаи обкунии боронакӣ барои кампанла мувофиқ аст?</h3><p>Тавсия намешавад. Қамплина (Complina) гулдории ҳоссила ба хуфъи реша ҳаст. Обёрӣ бо ҳароӣ ба вуҷуди аръоз ва обёрӣ нобаробар мерасад. Системаи қатрагӣ ва бандари (навар) контроли беҳтарро нисбати мувозинати об-оксигени реша таъмин мекунад ва ба нархи нисбатан баландтар мерасад.</p><h2>Хулоса: калиди муваффақият дар идоракунии бода ва об</h2><p>Ҳисоби дақиқи миқдори бодаи қамплина дар як гектар раванди якмаротиба нест, балки омезиши интихоби бодаи сифатнок, риояи масофаҳои иқлимӣ ва идоракунии дақиқи обёрии қатрагӣ мебошад. Бо истифода аз муқарраротҳои ислоҳи ҷинсӣ ва системаҳои навраси бандарӣ (навар) шумо метавонед хатари камбуди гулро ба ҳадди ақалл расонида ва даромади иқтисодии худро зиёд кунед. Моҳибар (қисмт) муваффақ он касест, ки ба ҷои андеша ва гумон, асос ба додаҳои илмӣ ва шартҳои муҳитии минтақаи худ ташкил мекунад. Риояи принсипҳои дар ин мақола овардашуда қадами мустаҳкам дар роҳи ҷинсбардори баробар ва давомноки қамплина дар Эрон мебошад.</p>','Миқдори бехи коминалӣ ба ҳектар: Раҳнамои ҷамъбасти кӣшт ва обёрӣ','Таҳлили илмии миқдори беҳтарини бодирҷонҳо дар ҳектар вобаста ба муҳити обӣ-ҳавоӣ ва ҷинси ҷунбиди килан. Равуҳи амалӣ барои кӯрконӣ, интихоби системаи озуварии қатрагӣ ва маслиҳотҳои баландбарории ҳосил барои деҳқонони ихтисосӣ.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
