SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='teff-drip-irrigation-cost-per-hectare-economic-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'teff-drip-irrigation-cost-per-hectare-economic-guide','teff-drip-irrigation-cost-per-hectare-economic-guide-crop-064-en');
