SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-064' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-064:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='tozimegi-yi-pishandaz-va-zirovat-i-mash-ba-yor-yi-zirkari-yi-rahnamai-komplet-va-tahsiloti' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
