SET @resolved_slug=IF(@slug_conflict IS NULL,'harajat-kush-tohi-dushanbe-ghoshni-no-re-type','harajat-kush-tohi-dushanbe-ghoshni-no-re-type-crop-070-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'harajat-kush-tohi-dushanbe-ghoshni-no-re-type-crop-070-tj-80c6bb7b');
