SET @resolved_slug=IF(@slug_conflict IS NULL,'nakh-i-parvarishi-i-pilu-ripi-rasmi-tajiki','nakh-i-parvarishi-i-pilu-ripi-rasmi-tajiki-crop-080-tj');
