INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола стандартҳои тавсияшуда барои фаосилаи қатори типӣ ҳангоми нақили кӯко муҳокам мешаванд. Барои фермерони тоҷик маълумотҳои техникии зарурӣ пешниҳод карда мешавад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
