SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='moloti-buni-mohi-dar-gektar-dasturi-purrar-baro-i-dehqononi-muasir' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'moloti-buni-mohi-dar-gektar-dasturi-purrar-baro-i-dehqononi-muasir','moloti-buni-mohi-dar-gektar-dasturi-purrar-baro-i-dehqononi-muasir-crop-083-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'moloti-buni-mohi-dar-gektar-dasturi-purrar-baro-i-dehqononi-muasir-crop-083-tj-b38257f3');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Кор农ёнии имрӯза бо мушкилоти зиёде рӯбарӯанд, ки яке аз муҳимтарин онҳо идоракунии дурусти манбаъҳо аз ҷумла об ва бодир аст. Шаҳри (Alhagi) набатиест, ки на танҳо ҳамчун олоф барои чорводорӣ, балки ҳамчун набат барои беҳтар кардани хок ва устувор кардани нитроген низ шинохта шудааст. Барои коркиши бозёрии ин набат, донистани <strong>миқдори бодири Шаҳри дар ҳектар</strong> аҳамияти ҳаётӣ дорад. Истифодаи нодурусти бодир метавонад ба зичии беш аз ҳад ва рақобат барои манбаъҳо, ё паҳншудани рӯшногӣ ва кам шудани ҳосил овард. Дар ин дастурамали умумӣ, ғайр аз баррасии техникаҳои коркӣ, бахусус дар ҷуфти ҷисмҳои оборӣ бо системаҳои обории қатронак ва нариб (норӣ), нуқтаҳои асосиро барои шумо шарҳ медиҳем.</p>\n<h2>аҳамияти муайян кардани дақиқи зичии бодири Шаҳри</h2>\n<p>Муайян кардани миқдори бодири Шаҳри дар ҳектар танҳо як рақами собит нест, балки равияест, ки ба тағирёбандаҳои зиёде вобаста аст. Шаҳри набати рунгдӯст ва гاه-ба-гаҳ дерравшана аст, бинобар ин зичии корк бояд тавре бошад, ки на танҳо пӯшиши наботии муносиб фармоиш диҳад, балки фазои кофӣ барои афзоиши решаҳо ҳам бокунанд. Агар зичӣ баланд бошад, набатҳои ҷавон рӯшноии кофиро гирифта наметавонанд ва дар натиҷа сояндор мешаванд, ки сифати олофро паст меорад. Аксин, коркиши паҳншуда боиси мешавад, ки набатҳо бо набототи киштӣ рақобат кунанд ва самаранокии ниҳоӣ кам шавад. Бинобар ин, мувозинат байни фосилаи коркӣ ва ҳаҷми бодир бояд ороста шавад.</p>\n<p>Яке аз омилҳои асосӣ, ки кор农ёнии одатан онро диққат намедиҳанд, саломатӣ ва қобилияти шӯрх (Sprouting) бодири аст. Бодири тоза бо сифати олӣ дарсади шӯрхии баландтар доранд, бинобар ин дар ҳар ҳектар ба миқдори камтар ниёз доранд. Ҳар гуна кам шудани сифати бодир бояд бо зиёд кардани миқдор ҷуброн шавад, аммо ин зиёдшавӣ набояд аз қобилияти муҳитии маҳалли корӣ фазлтар бошад. Барои муқоиса бо дигар наботот, шумо метавонед ба <a href="https://navar-abyari.ir/carrot-seed-quantity-per-hectare-guide/">дастурамали миқдори бодири анор дар ҳектар</a> Барои фаҳмо будан фарқиятҳои байни ин ду намуди наботат, ба манбаъ оид муроҷиат кунед.</p>\n\n<h2>Таъсири системаҳои обпошӣ ба миқдори ниҳоди шаҳӣ дар ҳектар</h2>\n<h3>Нақши обпоиши қатрагӣ</h3>\n<p>Системаҳои обпоиши қатрагӣ бо расонидани об мустақиман ба ҳудуди решаҳо, стресси аз камобиро ба минимум меоранд. Дар кишти шаҳӣ бо обпоиши қатрагӣ, метавон аз зичии каме баландтар истифода бурд, зеро тақсимоти баробари намӣ эҳтимоли шукуфтанҳои муваффақтари ниҳодро зиёд мекунад. Дар ин ҳолат, ниҳод бояд дар масофаи муайян аз бисори қатрагӣ ҷойгир шавад, то на танҳо аз таъсири мустақими об пешгирӣ шавад, балки аз вайроншавии натиҷаи таркиии давомӣ ҳифз гардад. Масофаи 10 то 15 сантиметр одатан оптималӣ аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-شاهی-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر شاهی در هکتار: راهنمای جامع - تصویر 1"/><figcaption>ниҳоди дар ҳектари кишоварзӣ шаҳӣ</figcaption></figure>\n<h3>Обпоиши бисори лентӣ ва идоракунии хароҷот</h3>\n<p>Бисори лентӣ барои кишоварзиҳо бо фосилаи нисбатан мунтазами кӯшодан, варианти иқтисодӣтар аст. Аммо бисори лентӣ ҳассосияти баланд ба хушкӣ ва муайян кардани фишор дорад. Пеш аз ҷойгиркунии бисори лентӣ, риояи принсипҳои техникӣ иброми муҳимияти хеле баланд дорад, то аз харобии сармоҳҷо пешгирӣ шавад. Шумо метавонед бо омӯзиш <a href="https://navar-abyari.ir/important-tips-before-installing-drip-tape-in-farm-iq/">Нуқтаҳои муҳим пеш аз насби бисори лентӣ дар кишоварзиҳо</a>Таъмин кунед, ки обравии шумон барои парвариши ҷалбӣ мувофиқ аст. Инчунин, санҷиш <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%DA%A9%D8%AF%D9%88-%D8%A2%D8%AC%DB%8C%D9%84%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">ҳаҷми ҳосили ҷалбӣ дар як гектар</a> метавонад таҳсилоти васеътарро дар бораи идоракунии давраи парваришҳо ба шумо бидҳад, зеро ҷалбӣ баъзан дар навбати парвариш бо дигар парваришҳо якбора парвариш карда мешавад.</p>\n\n<h2>Роҳнамои амалӣ барои ҳисоб кардани миқдори бӯи ҷалбӣ дар гектар</h2>\n<p>Барои ҳисоби дақиқ, бояд аз формулаи зерин истифода баред:</p>\n<ol>\n<li><strong>Муайян кардани фосилаи парвариш:</strong> Одатан барои ҷалбӣ, фосилаи сафарбарӣ 30 то 50 сантиметр ва фосилаи дарахтӣ 10 то 15 сантиметр тавсия дода мешавад.</li>\n<li><strong>Ҳисоб кардани шумораи дарахтон дар гектар:</strong> Асосбардаи масофаҳои муайяншуда, шумораи рӯяноҳоро дар як гектар ҳисоб кунед.</li>\n<li><strong>Диққат ба сурати нишон:</strong> Агар сурати нишони тоҷи шумо 80% бошад, бояд барои ҳар як рӯйи боқимонда, 1/25 тоҷ корд шавед. Пас, шумораи умумии тоҷро зиёд кунед.</li>\n</ol>\n<p>Тақрибан, барои заираи оддӣ, <strong>Миқдори тоҷи заира дар як гектар</strong> метавонад аз 15 то 25 килограмм фарқ кунад. Ин рақамҳо ба навъи рӯй, ғафсии тоҷ ва шартҳои маҳаллӣ вобастаанд. Агар аз тоҷҳои тайёршуда истифода баред, шояд ин миқдор камтар бошад. Диққат диҳед, ки паҳн намудани баробари тоҷ калиди асосии муваффақият аст. Истифодаи паҳнкунандаҳои муасири замонавӣ ё усулҳои дастӣ бо дақиқии баланд, ҷамъшавии тоҷро дар як нуқта пешгирӣ мекунад.</p>\n<p>Агар дар хоҷагиҳои худ корҳои омехта анҷом диҳед, бояд ба мувозинати тоҷи рӯяи ҳамроҳ низ диққат диҳед. Масалан, дар <a href="https://navar-abyari.ir/green-cumin-seed-amount-per-hectare-planting-care/">Миқдори тоҷи заираи сабз дар як гектар</a> Ва парҳизпардории партобонии он, мувозинати обӣ ва рӯшноӣ бо шаҳӣ метавонад ба вуҷуд ояд ва бинобар ин миқдори тоҷи шаҳӣ бояд дубора баррасӣ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-شاهی-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر شاهی در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Norm of sowing seeds per hectare of crop шаҳӣ</figcaption></figure>\n\n<h2>Омилҳои таъсиррасон ба зиёдшавии сатҳи равшанӣ ва бартарӣ</h2>\n<h3>Омодагии хок ва шароити муҳит</h3>\n<p>Шаҳӣ наботате ҳоғиза ба ҳаёт аст, аммо барои равшанӣ ибтидоӣ ба намуди мувофиқ ниёз дорад. Омодагии хокҳои амиқ ва коркарди мувофиқи хок, барои пайвастшавии решаҳо заминаи хуби меъёр мебахшад. Намакии хок низ метавонад ба миқдори тоҷи шаҳӣ дар гектар таъсири манфӣ расонад; зеро дар хокҳои намакин сатҳи равшанӣ пасттар аст ва бинобар ин бояд андозаи тоҷро каме зиёд кард, то ки пошурияти наботатии мувофиқ ба даст оварда шавад.</p>\n<h3>Рӯбарӯӣ бо зараррасонҳо ва бемориҳо</h3>\n<p>Бо зичии баланди тоҷ, муҳит барои пардазидани бемориҳои қофзӣ ва таҳаммули ҳашарот мувофиқтар мегардад. Парҳизпардории солимӣи деҳкони ва истифодаи самоварандаи муносиб дар вақти муайян, баъзан муҳимтар аз зиёд кардани миқдори тоҷ аст. Як наботати боқимонандаи солим, беҳтар аз даҳ наботати заиф ва бемор аст. Барои фаҳмиши беҳтар аз идоракунии бемориҳо дар партобонҳои монанд, метавонед мақолаи мёзисити хурме дар гектарро омӯзед, ки ба таҳлили зараррасонҳо дар фазои деҳкони мерасад. Инчунин, камҳои кабба дар гектар қисми дигари мушкилоти деҳкониро фаро мегирад, ки метавонад намунае барои идоракунии шаҳӣ бошад.</p>\n<h2>Ҷавоб ба саволҳои оммавӣ (FAQ)</h2>\n<p><strong>Саволи 1: Оё миқдори бӯди шаҳӣ ба ҳар гектар собит аст?</strong><br>Не, ин миқдор ба нависҳо, ҳолати бӯд (нав ё кӯҳна), шароити хок ва намуди системаи обёрӣ вобаста аст. Ҳамеша аз датаҳои маҳаллӣ истифода баред.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-شاهی-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر شاهی در هکتار: راهنمای جامع - تصویر 3"/><figcaption>миқдори бӯд ба гектар барои ҳосили шаҳӣ</figcaption></figure>\n<p><strong>Саволи 2: Оё шаҳӣ барои обёрии риштаи (дрилэт) мувофиқ аст?</strong><br>Ҳаъ, шаҳӣ аз системаҳои фишори паст монанди риштаи (дрилэт) истифода мекунад, аммо бояд дар бораи кофӣ будани фишори об ва партоби ҳар ришта боварӣ ҳосил кунед, то намнокӣ якхела бошад.</p>\n<p><strong>Саволи 3: Агар бӯд кам бошад, чӣ кор кардан мумкин аст?</strong><br>Шумо метавонед бӯдро бо бӯди дигар гиёҳон монанди ҷӯшмӣ омехта кунед, аммо бояд нисбатҳоро ҳисоб кунед. Ё метавонед аз котикҳо (афзоиши гиёҳ аз соқм) истифода баред, ки ҳосилнокии баланд дорад.</p>\n<h2>Хулоса ва тавсияҳои ниҳоӣ</h2>\n<p>Муайян кардан <strong>Миқдори тоҳи сабзияи кӯб (бучи) дар ҳектар</strong> Ин раванди динamik аст, ки ба назорат ва танзими доимӣ ниёз дорад. Калиди муваффақият дар парвариши кӯб, на танҳо интихоби миқдори тоҳи, балки мутобиқат доштани он бо системаи обёркуниҳо ва идоракунии замин мебошад. Истифодаи обёркунии қатрагӣ ё тасуфӣ хараҷҳоро кам мекунад ва самараро зиёд мекунад. Мо пеш аз харидани тоҳӣ, муроҷиат ба қишқори бузургро ва гузарондани таҳқиқоти лабгардонӣ дар лабораторияро тавсия медиҳем. Ин қадами хурд метавонад фарқияти муҳимро ба ҳосили ниҳоии кӯшиатон дароварда, онро тағйир диҳад. Инчунин, баррасии мавзӯи вобаста чунин <a href="https://navar-abyari.ir/spinach-yield-per-hectare-factors-increase/">омили афзайиши ҳосили шолӣ дар ҳектар</a> метавонад диди шуморо дар бораи идоракунии таракӣ ва ғизои наботони паррандоз (ки дар ҷанбаи монанди кӯб ҷойгир мешаванд) васеъ кунад.</p>','Мӯҳлоти бӯни моҳи дар гектар: дастури пурра барои деҳқонони муосир','Хусусиятҳои технӣи подшоҳӣ ва усули муайян кардани зичии беҳтарини ҷуноби бардошт дар боғзорҳо бо системаҳои навордирии муосир. Ин мақола тавассути таҳқиқ омилҳои иқлимӣ ва намуди хок ба шумо кӯмак мекунад, ки миқдори дақиқи ҷунби заруриро ҳисоб кунед ва аз талафоти молиягӣ пешгирӣ намоед.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
