SET @resolved_slug=IF(@slug_conflict IS NULL,'miqdomi-budi-qino-dar-hektar-rohnamoyi-mukammal','miqdomi-budi-qino-dar-hektar-rohnamoyi-mukammal-crop-090-tj');
