SET @resolved_slug=IF(@slug_conflict IS NULL,'taqaleef-zeraa-al-turik-kali-battanqit-al-fadaan-tahlil-iqtisadi-wa-fanni','taqaleef-zeraa-al-turik-kali-battanqit-al-fadaan-tahlil-iqtisadi-wa-fanni-crop-091-iraq');
