START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-096' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-096:en-US' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='sprinkler-maintenance-drip-tape-key-points' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'sprinkler-maintenance-drip-tape-key-points','sprinkler-maintenance-drip-tape-key-points-crop-096-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'sprinkler-maintenance-drip-tape-key-points-crop-096-en-5e3220f0');
