SET @resolved_slug=IF(@slug_conflict IS NULL,'nigohubiniyi-ekspres-sipoti-tip-nuktotai-klidi','nigohubiniyi-ekspres-sipoti-tip-nuktotai-klidi-crop-096-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'nigohubiniyi-ekspres-sipoti-tip-nuktotai-klidi-crop-096-tj-a109378b');
