SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='rye-pest-disease-management-drip-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'rye-pest-disease-management-drip-irrigation-guide','rye-pest-disease-management-drip-irrigation-guide-crop-101-en');
