INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','Ҳаҷми беди нӯк дар һектар: дастур барои афзун кардани ҳосил ва таҳриф баобӣ' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин дастуроме шарҳ дода мешавад, ки чӣ тавр ҳаҷми беди нӯкро дар һектар муайян кардан мумкин аст, то ҳосили беҳтар ва истифодаи бовобатари об бошад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
