SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='maintenance-border-irrigation-tape-method-key-points' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'maintenance-border-irrigation-tape-method-key-points','maintenance-border-irrigation-tape-method-key-points-crop-107-en');
