SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='farmonoi-kotish-soroh-sadoidi-tovse-shuda' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'farmonoi-kotish-soroh-sadoidi-tovse-shuda','farmonoi-kotish-soroh-sadoidi-tovse-shuda-crop-108-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
