INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','كيف ترفع إنتاجية الحبة الواحدة لكل هكتار في العراق عبر نظام الري بالتنقيط؟' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تفاصيل شاملة حول تقنيات نظام الري بالتنقيط لرفع إنتاجية الحبة الواحدة لكل هكتار بشكل كبير. احصل على دليل عملي ومباشر موجه لمزارعي الحبة الواحدة في العراق لتقليل تكاليف الإنتاج وزيادة العوائد.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','إنتاجية الحبة الواحدة لكل هكتار باستخدام نظام الري بالتنقيط: دليل عملي ومتقدم' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
