SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='majdudii-chakani-bar-asosi-gokhtar' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'majdudii-chakani-bar-asosi-gokhtar','majdudii-chakani-bar-asosi-gokhtar-crop-110-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'majdudii-chakani-bar-asosi-gokhtar-crop-110-tj-1e04f582');
