SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='tillage-strip-spacing-oats-afp-recommendations' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'tillage-strip-spacing-oats-afp-recommendations','tillage-strip-spacing-oats-afp-recommendations-crop-111-iraq');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'tillage-strip-spacing-oats-afp-recommendations-crop-111-iraq-ad104fad');
