START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-111' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-111:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='farohishi-sathi-gunchakashakan-dar-kisht-shitob' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'farohishi-sathi-gunchakashakan-dar-kisht-shitob','farohishi-sathi-gunchakashakan-dar-kisht-shitob-crop-111-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'farohishi-sathi-gunchakashakan-dar-kisht-shitob-crop-111-tj-a8aa1e38');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Меҳр баъзе муҳимтарин напокҳои покандӣ ва ғизои чорвод мебошад, ки бо сабаби талаботи махсус ба тасмим баҳорӣ ва ғизои баробар, ба системаи обёрӣ дар таври наққорагузории дақиқ ниёз дорад. Дар бисёр мӯрриъҳо, дар бораи фармондиҳӣ <strong>Фасоли наққорагузорӣ дар куннии меҳр</strong> Бе дониши кофӣ дар бораи физикаи хок, иқлим ва геноטיפи напок ба воруид мекунад, ки метавонад ба истифодаи нокомплетӣ ва коҳиши ҳосил оварда расонад. Мақсади ин матлубро, пешниҳоди стандартҳои техникӣ ва оперативӣ барои муайян кардани беҳтарин фасои байни хатҳо наққорагузорӣ мебошад, то ки киҳоварон бо истифодаи маълумотҳои илмӣ, тарҳи системаи обёрӣ худро беҳтар созанд.</p><h2>Моҷиҳои техникӣ барои обёрӣ дар таври наққорагузорӣ дар системаҳои наққорагузорӣ</h2><p>Наққорагузорӣ (Drip Tape) яке аз системаҳои маъмултарини нақлу ғизо дорад. Дар ин система, оҳан ғизо аз нуқтаҳои наққорагузорӣ ба тартиб дар тӯли наққорагузорӣ паршинад. Омили ки дар муайян кардани фасо байни наққорагузорӣ дар байни хатҳои меҳр нақши марказиро мебозад, мадҳояти ҳосил аз хок ва радиуси хирокшавӣ аст. Агар фасо бай наққорагузориҳо аз радиуси таъсирбар мебудад, майҳои хушк дар хок ҳосил мешаванд ва агар аз ҳадафи муносиб камтар мебудад, хашхашавии хирокшавӣ вухӯдад ва вақти хушкшавӣ тӯлонӣ мевурад, ки метавонад ба заҳролӣи реша боиси шавад.</p><h3>Дид ва фасои наққорагузорӣ бо зичии решаи меҳр</h3><p>Системаи решаи меҳр (махсусан намудҳои <em>Trifolium repens</em> ва <em>Trifolium pratense</em>асосан сатҳӣ ва торик аст. Рӯидаҳои асосӣ дарҳораи маҳдуд доранд ва рӯидаҳои иловагӣ паҳншавии андозаашро мегиранд. Бинобар ин, дар масофаҳои хеле дур миёни навбатҳо, қисмҳои амудии хок бе рӯида, хушк мемонанд. Баръакс, дар масофаҳои наздик, хараҷи насб ва таъмир зиёд мешавад. Таҳқиқоти майдонӣ нишон медиҳанд, ки беҳтарин мувозинат ҳангоми он рух медиҳад, ки радиуси намнокории ҳар навбат тақрибан 75 то 100%-ро дар масофаи умумӣ то навбати ҳамсоя фаро мегирад.</p><p></p><h2>Стандартҳои тавсияшуда аз рӯи намуди хок</h2><p>Масофаи бехатарии навбати рипири ба намоиши шафд дар хӯрокворӣ бевосита ба сохтори хок вобаста аст. Дар хокҳои рӯранг, суръати ҷарроҳии об зиёдтар ва радиуси намнокорӣ кӯтоҳтар аст; бинобар ин масофаҳои камтар тавсия мешаванд. Баръакс, дар хокҳои лагунӣ, ҳаракати об шикофтакӣ аст ва паҳншавии амудӣ ва уфуқӣ вақтофарӣ аст, ки имкон медиҳад масофаҳои зиёдтар бо эҳтиётро дар назар гиранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-شبدر-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت شبدر: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop шафд</figcaption></figure><table><tr><th>Намуди хок</th><th>Масофаи тавсияшуда миёни навбатҳо</th><th>Масофа то навбати оянда дар радаҳои пайдарпай</th><th>Шарҳҳо</th></tr><tr><td>Резавӣ / сабук</td><td>45 то 55 сантиметр</td><td>60 то 75 сантиметр</td><td>Устувории гармидиҳӣ пасттар, ниёз ба партоб камтар</td></tr><tr><td>Лом / миёна</td><td>55 то 65 сантиметр</td><td>75 то 90 сантиметр</td><td>Беҳтарин мувозинат барои аксар минтақаҳо</td></tr><tr><td>Рӯдхона / вазнин</td><td>65 то 75 сантиметр</td><td>90 то 105 сантиметр</td><td>Аҳтироҳ аз қабри муштараки реша ва камбудии оксиген</td></tr></table><p>Ин рақамҳо ҳамчун хати ибтидо пешниҳод мешаванд ва бояд бо шароити маҳаллӣ ва санҷишҳои аввалия дар ҷангалҳа мутобиқ карда шаванд. Барои маълумоти беш дар бораи таъсири зичии партофтани пупрак ба системаи оборӣ, шумо метавонед ба дастуруламҳаи шартҳои зарурӣ аз рӯи тартиби корбозӣ муроҷиат кунед, ки принсипҳои монанд дар бораи тақсимоти захираҳоро ба назар мегирад.</p><h2>Таъсири масофаи сӯрохии ғадакӣ ба ҳосилнокӣ ва сифати кӯбук</h2><h3>Дар алоқа бо истеҳсоти хӯроки ҳайвонот</h3><p>Кӯбук тавассути таъмини тавозуни намӣ дар минтақаи решаҳо сатҳи хлорофилл ва тақсимоти баргҳоро нигоҳ медорад. Вақте ки масофаи сӯрохии ғадакӣ дар партофтани кӯбук стандартӣ набошад, гиёҳҳои қаторҳои дугона ба ихтилоли намӣ гирифтор мешаванд. Ихтилолҳои хурд, гарчанде ки бо вуҷуди онҳо фавтоти ва заҳроланиро кам мекунанд, аммо суръати рушдро суст карда, миқдори моддаҳои хушши истеҳсолшударо паст меоранд. Дар ҷангалҳои ломи риояи масофаи 55 то 65 сантиметрӣ боиси кам шудани шори хок ва инчунин ба решаҳои амиқтар имкон медиҳад, ки дақиқ ба моддаҳои ғизоӣ дастрасӣ пайдо кунанд.</p><p>Барои муқоисаи равиши функсионалӣ дар дигар гиёҳҳои офтобагӣ ва мулоимкунанда, таҳқиқот <a href="https://navar-abyari.ir/musir-hosilagiri-dar-hektyar/">Масоҳати чорчӯбавули ҳектар</a> метавонад дарки беҳтареро аз идоракунии аҳолӣ ва обёрӣ дар воҳидҳои мулоимкунанда инъикос намояд.</p><h3>Идоракунии намакӣ ва бемориҳои решагӣ</h3><p>Дар системаҳои наварии дрип, консентратсияи моддаҳои ҳалшуда дар минтақаи тар шуда зиёд мегардад. Масофаи нодуруст байни наварҳо ин паҳноиро шадид мекунад. Чинҷоб барои намак ҳассос аст; бинобар ин, риояи меъёрҳои масофагузорӣ, ғайр аз теъдуд кардани об, ба кам шудани эҳтимоли зарари намакӣ дар нуқтаҳои ҳассоси реша мусоидат мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-شبدر-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت شبدر: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>massofa-driptape-sabtda-rich-kharor-chinchob</figcaption></figure><p></p><h2>Нишонҳои амалӣ барои иҷрои дуруст дар девона</h2><ol><li><strong>Санҷиши сохтори хоки маҳаллӣ:</strong> Пеш аз харидани лентаи тип, намунабардории замин ва санҷиши дарай (Infiltration Test)-ро иҷро кунед. Заминҳои регмӣ вобастагӣ ба фосилаи хурдтар (45-55 сентиметр) доранд ва заминҳои коҳгилӣ вобастагӣ ба фосилаи калонтар (65-75 сентиметр).</li><li><strong>Ҳамсозангии қаторҳо:</strong> Назук одатан бо шакли қаторҳои дутоя ва чандқаторӣ ҷӯшонида мешавад. Лентаҳои тип бояд дақиқан дар маркази гурӯҳи қаторҳо ё дар фосилае ҷойгир карда шаванд, ки ба канорҳои миёнақаторӣ мувофиқат мекунад, то партоби об ба таври симметрӣ сурат гирад.</li><li><strong>Интихоби диаметри канори қатраӣ:</strong> Агар фосилаи лентаҳо зиёд бошад, аз канорҳои қатраӣ бо суръати дебит баландтар (масалан, 2/5 ё 3 литр дар соат) истифода баред, то радиуси намнокӣ афзоиш ёбад. Баръакс, дар фосилаҳои хурд, канорҳое бо дебит пасттар (1/6 то 2 литр) мувофиқтар мебошанд.</li><li><strong>Насб ва ивази ҷорӣ:</strong> Лентаҳои тип истеъмолшаванда мебошанд. Дар шароити назук, ки намнокӣ баланд аст, хатари даромадан (ғарқ шудан)-и канорҳо зиёд аст. Фосилаи хурдтар байни лентаҳо маънои онро дорад, ки шумораи бештари лентаҳо дар гектар ва хароҷоти баланди иваз. Бинобар ин, мувозинати байни фосила ва умри истифодашавии система бояд ба наз гирифта шавад.</li></ol><p>Чун як манбаи иловагӣ барои оптимизатсияи хароҷотҳо дар растаниҳои дигари дренашуда, роҳнамои <a href="https://navar-abyari.ir/okra-yield-per-hectare-guide-tajik-farmers/">Ҷараёни окса дар ҳар гектар барои деҳқонони тоҷик</a> Мумкин аст намунаи хуби идоракунии иқтисодии системаи регҳои чанг (strip) бошад.</p><h2>Саволҳои мавриди баҳс буданда (FAQ)</h2><h3>Фазои махсуси регҳо барои ҳама навъҳои чанг якхела аст?</h3><p>Не. Навъҳои гуногуни чанг дар амиқии реша ва зарурати намӣ фарқиятҳо доранд. Чанги бунафш (<em>red clover</em>) решаҳои амиқтар дорад ва метавонад фазои бештарро саҳибонад, дар ҳоле ки чанги сафед (<em>white clover</em>) бо решаҳои сатҳӣ, ба фазои наздиктар (тақрибан 45 то 55 см) бештар ниёз дорад, то роҳи намнокшавӣ кофӣ дастрас бошад.</p><h3>Оё имкони ҳаракати регҳо пас аз коррон мавҷуд аст?</h3><p>Коҳ кардани шинакаи каппулӣ баъд аз нухудани намон амалан ғайриимкон аст, зеро решаҳои растани ва хок атрофи он бо дақиқат танзим карда шудаанд. Агар лозим бошад, ки масофаро тағйир диҳед, бояд системаро аз вақти омода кардани муҳит ва пеш аз нухудан дубора насб кунед. Инчунин, барои растаниҳое, ки системаи ободори монанд доранд, метавонед аз дастураи <a href="https://navar-abyari.ir/2inch-cotton-irrigation-tube-guide/">обдоии пахта бо пайп 2 дюйм</a> ҳамдаҳӣ кунед, ки асосҳои умумии насб кардани пайпҳоро шарҳ медиҳад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-شبدر-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت شبدر: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>масафаи шинакаи каппулӣ тарҳи сафҳо парвариши намон</figcaption></figure><h3>Самъи масофаи шинака ба хароҷоти об то чӣ андоза мерасад?</h3><p>Масофаи бештар, шумораи камтари шинакаҳо ва дар натиҷа кам шудани хароҷоти аввалагии насбқунӣро дар бар мегирад, амар агар масофа аз радиуси корӣ дур шуда барояд, растани овардани дилазобӣ мекашад ва метавонад ниёз ба ободории иловагии паҳлофӣ дошта бошад, ки хароҷоти он ихтиёрӣ аст. Дар ҳолати идеалӣ, риояи меъёрҳо ба кам шудани истиифодаи умумии об то 15-20 фоиз нисбат ба системаҳои паҳлофӣ оварда мерасонад. Дар заминаи бехатар кардани истифодаи манбаъҳо дар парвариши ҳушорӯягон, таҳқиқоти <a href="https://navar-abyari.ir/migdori-tumi-gandomi-chorsu/">шумораи нухудани гулбудур дар ҳар гектар</a> наظари дорад оид ба роҳҳои идоракунии зичии нухуд ва манбаи ободорӣ дар парваришҳои монанд.</p><p></p><h2>Хулоса ва тавсияҳои охирин</h2><p>Муайян кардан <strong>Фосилаи банди тип дар кишт кардани риккӣ</strong> Яке адади содда нест; балки як мусоиди омили сохтори хок, намуди генотип, суръати ҳаҷми чашмасоҳҳо ва шароити иқлимӣ мебошад. Ба таври умумӣ, барои аксари хокҳои шабистии Афғонистон, фосилаи 55 то 65 сантиметрӣ бо канорҳои 2 литр дар сония, нуқтаи мувозинати беҳтаринро пешниҳод мекунад. Кинорони бояд пеш аз иҷро, озмуни гузаронии обро гузаронида ва фосилаҳоро ба таври танзим намоянд, то ки канорҳои ба об тоза мешаванд бо ҳамдигар пайваст шаванд. риоя кардани ин асосҳо на танҳо аз чормағзакор ва бемориҳои реша парҳез мекунад, балки барои чарои риккӣ ва оббарораки шубид, ҳосили устуwartар ва барориштарро ба вуҷуд меорад. Омода шудааст, ки дар ин дастур ягон нархгузорӣ ё намояндагӣ пешниҳод нашудааст ва ҳамаи рақамҳо бар асоси асосҳои муҳандисии оббодӣ ва тадқиқоти фаннии умумӣ мебошад.</p>','Фароиши сатҳи ғунчакшакан дар кишт шитоб: стандартҳои тавсияшуда','Стандартҳои фосилаи сафи Тиб дар кунуни шодур нақши асосиро дар идоракунии намнокӣ ва тақсимоти баробари моддаҳои ғизоӣ мебозад. Ин мақола принсипҳои техникӣ ва амалиро барои интихоби фосилаи дурустро мефаҳмонад.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
