SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='cantaloupe-drip-tape-maintenance-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'cantaloupe-drip-tape-maintenance-guide','cantaloupe-drip-tape-maintenance-guide-crop-113-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
