SET @resolved_slug=IF(@slug_conflict IS NULL,'darmandorii-xurbo-novar-t-tip-nukta-baroi-dehqono','darmandorii-xurbo-novar-t-tip-nukta-baroi-dehqono-crop-113-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'darmandorii-xurbo-novar-t-tip-nukta-baroi-dehqono-crop-113-tj-3084b284');
