SET @resolved_slug=IF(@slug_conflict IS NULL,'modiratii-zararavaronu-bemorihai-sorgo-dar-systemai-oboriyii-qttarga','modiratii-zararavaronu-bemorihai-sorgo-dar-systemai-oboriyii-qttarga-crop-114-tj');
