SET @resolved_slug=IF(@slug_conflict IS NULL,'taqeer-ghssm-qndm-ba-nawar-typ-fi-hektar-rahnama-ham-bahiya-iqtasadi','taqeer-ghssm-qndm-ba-nawar-typ-fi-hektar-rahnama-ham-bahiya-iqtasadi-crop-115-iraq');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
