SET @resolved_slug=IF(@slug_conflict IS NULL,'arzoyagii-parrovkoni-gandum-systema-type','arzoyagii-parrovkoni-gandum-systema-type-crop-115-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'arzoyagii-parrovkoni-gandum-systema-type-crop-115-tj-a2c2a3a7');
