SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='drip-tape-corn-cultivation-cost-per-hectare' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'drip-tape-corn-cultivation-cost-per-hectare','drip-tape-corn-cultivation-cost-per-hectare-crop-117-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
