SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='barley-pests-diseases-drip-irrigation-management-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'barley-pests-diseases-drip-irrigation-management-guide','barley-pests-diseases-drip-irrigation-management-guide-crop-119-en');
