START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-120' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-120:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='omoyan-baroi-parvarishi-paxta-bo-sugorii-qatqa-vaina-vonr-i-teyp' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'omoyan-baroi-parvarishi-paxta-bo-sugorii-qatqa-vaina-vonr-i-teyp','omoyan-baroi-parvarishi-paxta-bo-sugorii-qatqa-vaina-vonr-i-teyp-crop-120-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'omoyan-baroi-parvarishi-paxta-bo-sugorii-qatqa-vaina-vonr-i-teyp-crop-120-tj-85fbfece');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Чаро пашт ба ободобӣ бо қатракоҳӣ эҳтиёҷ дорад?</h2>\n<p>Кунуни пашт, махсусан дар минтақаҳои хушк ва нимхушк, бо масъалаҳои амиқи идоракунии захираҳои об рӯбарӯст. Усулҳои анъанавии ободобии сатҳии монанди партобӣ ҳамеша бо мушкилоти монанди буҳори баланд, афзоиши аб-ваҳашҳо ва бимориҳои қарамоиш аз сабаби дунбуррории баргҳо ҳамроҳ будааст. Системаи ободобии қатракоҳӣ ва ба хусус истифодаи тасмаи қатра (Drip Tape) вазъи инқилобиро дар кунуни пашт ба вуҷуд овардааст. Ин система бо расондани об ба таври мустақим ба минтақаи реша (Root Zone) наморои мувофиқро нигоҳ медорад ва дарминҳои оби ғилокро ба ҳадди ақалл мерасонад. Илова бар таҳсилот барои об, ин усул ба дастрасони мустақими ғизои ғилок тавассути пашпуши дар шабакаи ободобӣ (Fertigation) имконият мебахшад, ки боиси рушди мунтазамтар ва камшавии пардохти меваҳои номеро мегардад. Барои оғози беҳтар, шиносӣ бо ҳадди меҳрдиҳандагии ғилокони ширқоғӣ ва гурук ва муқоисаи онҳо метавонад дар донистани беҳтари қобилияти самаранокии система дар шартҳои монандро кӯмак расонад, гарчанде ки пашт ҳассосиятҳои мушаххаси худро дорад. Шумо бо таҳсилот пайдо кардан мекунед <a href="https://navar-abyari.ir/mohdath-intaj-thur-maksikhi-li-l-hektar-daleel-shamil-lil-muzariin/">Ҳаҷми истихроҷи даромади максимумӣ дар гектар</a> Ба истиқболи даромади маҳсулоти монанд назар доред.</p>\n\n\n\n<h2>Шартҳои пешаз овардани тасмаи қатра барои кунуни пашт</h2>\n<p>Пеш аз ниҳоли дони пашпа, омодагӣи дурусти системаи оварӣ хеле муҳим аст. Нави каппи чакмак корбори дуруст нест, зеро нахустин нурон барои он камтар аз чакмакҳои собит аст ва қобилияти истифодаи ягонаро (одатан 1 то 3 сол) дорад. Яке аз муҳимтарин нуқтаҳо ин интихоби фосилаи мувофиқи чакмакҳо аст. Барои пашпа, фосилаи 30 то 50 сантиметр дар чакмак одатан комил аст, зеро тақсимоти баробари обро атрофи оҳангарона таъмин мекунад. Инчунин, бояд боварӣ ба оморатҳои пеш аз харидани нави каппи оварӣ диҳед, то аз бастагии сӯрохҳо ва фишори мувофиқ пешгирӣ кунед. Навори дурусти чакмакҳо бояд бо ниҳоли дони ҳом буд, то решаҳо аз аввали раванд бо занонаву дунбони намнок бо дарояндагӣ бошанд. Инчунин, лӯлакҳои асосӣ ва иловагӣ бояд чунин бошанд, ки фишори якхеларо дар тамоми дарозии нави ҳомиран созанд. Барои фаҳмиши беҳтари сохтори техникӣ, муроҷиат ба пайвастҳои нави каппи кишоварзӣ метавонад дар пайвастшавии дурусти фитингҳо ва пешгирии офтоби ноаён муҳим бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-پنبه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت پنبه با آبیاری قطره‌ای - تصویر 1"/><figcaption>усули ниҳоли дони, оварии каппи чакмакӣ, нақшаи оварии пашпа, пашпа</figcaption></figure>\n\n<h2>Ҷадвали вақти оварӣ ва паррандани пашпа</h2>\n<p>Идоракунии оварии пашпа бояд дар асоси марҳилаҳои афзоиши оҳангарона танзим шавад. Пашпа ба оварии мунтазам ва мулоим ниёз дорад ва хушкшавии одадӣ боиси фароҳомии гул ва дона мешавад. Дар марҳилаи аввали афзоиши вазъӣ, оварии муваққатӣ ва такроршуда фоидабахштар аст. Вақте ки ба марҳилаи гулгирӣ ва шаклгирӣи меваҳои ноҳомвор мерасад, ниёз ба об аъоҳот мешавад. Тавассути оварӣ бо паррандан (Фертиватсия) дар нави каппи чакмакӣ, воситаи қавватӣ аст. Шумо метавонед аз ҳалкунандаҳои ғизоӣ, ки нитроген, фосфор ва потасийро дарбар мегиранд, истифода баред. Барои ҳисоби дақиқтарини ниёзҳои паррандан, дониши <a href="https://navar-abyari.ir/mikorit-khomi-yufa-hamadoni-dar-hektar/">Микроэлементи хомеҳӣ дар 1 гектар</a> ёки маркомашкуи монанди метавонад ба танзими бории дақиқ кӯмак расонад, гарчанде ки ин маълумот бештар ба молҳои чорводӣ дахл дорад, аммо принсипҳои умумии ғизои растаниҳо ишора кардан мумкин аст. Ҷадвали зерин роҳнамои умумӣ дар бораи миқдори пешниҳодшудаи об дар гектар бар асоси марҳалаҳои рушд аст:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-پنبه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت پنبه با آبیاری قطره‌ای - تصویر 2"/><figcaption>усули шинокори, равияи обёрӣ, нақшаи обёрӣ, пашт</figcaption></figure>\n\n<table>\n<thead>\n<tr>\n<th>Марҳалаи рушд</th>\n<th>Шиддати обёрӣ (сантиметр/ҳафта)</th>\n<th>Шумораи маротибаҳои обёрӣ</th>\n<th>Нуқтаҳои калидии ғизогузорӣ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Аспорӣ (рӯзи 1 то 21)</td>\n<td>5-8</td>\n<td>2</td>\n<td>Кам шудани нитроген, таваҷҷуҳ ба фосфор барои решагӣ</td>\n</tr>\n<tr>\n<td>Рӯшдӣи тез (рӯзҳои 21 то 50)</td>\n<td>10-15</td>\n<td>2-3</td>\n<td>Зиёд шудани тадриҷии нитроген</td>\n</tr>\n<tr>\n<td>Гулгашт ва ташаккули гул (рӯзҳои 50 то 70)</td>\n<td>12-18</td>\n<td>2</td>\n<td>Вороби калий ва кальсий, танзими дақиқи борий</td>\n</tr>\n<tr>\n<td>Афзоиши мевот (рӯзҳои 70 то 95)</td>\n<td>15-20</td>\n<td>2</td>\n<td>Калии баланд барои зиёд кардани вазни пӯст</td>\n</tr>\n<tr>\n<td>Пеш аз бардоштан (рӯзи 95 ва баъд)</td>\n<td>0-5 (кам кардани тадриҷӣ)</td>\n<td>1</td>\n<td>Нобудкунии оборӣ ва ғизонокунӣ барои ба вуҷуд овардани фишори нопоки</td>\n</tr>\n</tbody>\n</table>\n\n\n\n<h2>Нуктаҳои амалӣ дар бораи кӯбот ва идоракунии алафузӯ</h2>\n<p>Кӯботи пахта бо усули шӯравии тампӣ имконияти хубро барои назорати алафузӯ фароҳам меорад, зеро сояшавӣи шӯравҳо ба хок вазъи рушди алафҳоро маҳдуд мекунад. Бо вуҷуди ин, идоракунии онҳо ҳамчунин зарур аст. Яке аз усулҳои самаранок истифодаи кӯрдаҳи пластикӣ ё пӯшакҳои биодеградатсионӣ аст, аммо хароҷоти бештар дорад. Дар сурати истифода на кардани кӯрдаҳ, алафузӯҳои сирпӯш бояд пеш аз пӯшидани хатҳои кӯбот ва пӯшиши комиллӣ хок бо баргҳои пахта назорат карда шаванд. Усулҳои механикӣ, ба монанди нур кардани хок бо абзорҳои мувофиқ ё истифодаи ҳашарокӯбҳои пешакӣ бо дақиқати баланд тавсия дода мешаванд. Дадорош кунед, ки ҳар қадаре фавосилии қаторҳои кӯботи пахта бештар бошад, майдони бештар барои рушди алафҳо ба вуҷуд меояд; бинобар ин, қаторҳои зич бо пӯшики дутоифаи шӯравии тампӣ ҳолати беҳтарин барои назорати алафузӯ аст. Инчунин, <a href="https://navar-abyari.ir/tarzi-nasbi-lulayi-ob-yori-tip/">Тартиби шӯравҳои обёрории тампӣ</a> Boyd тавре бошад, ки ҳампушии шӯравҳо дар хатҳои амудӣ ва хатҳои ҷонибӣ камтар бошад, то дастрасии механикӣ нигоҳ дошта шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-پنبه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت پنبه با آبیاری قطره‌ای - تصویر 3"/><figcaption>planting methods drip crop irrigation schedule пибта</figcaption></figure>\n\n<h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2>\n<ul>\n<li><strong>Оё бастаи нӯриро дар наутси бӯрзӣ беҳтар аз чанки чанкӯни шӯюшаванда аст?</strong><br>Барои наутси бӯрзӣ, ки одатан яксола парворда мешавад, бастаи нӯриро аз ҷиҳати хараҷҳо арзонтар аст. Чанкӯни чанкӯни шӯюшаванда (одатан бо андозаи 16 милметр) барои парваришҳои бисёрсолагӣ, монанди дархтонҳои мевадор интихоб карда мешаванд. Наутси бӯрзӣ ниёз ба хараҷи ибтидоии пасттар дорад ва бастаи нӯриро ин ниёзро қонеъ мекунад. Инчунин, чанкӯни чанкӯни шӯюшаванда баъзан сӯрохиҳои хурдтар доранд, ки дар сурати вуҷуди рароси баланд дар об, эҳтимоли гирифтан доранд, дар ҳоле ки бастаҳои нӯриёи муосир филтри дохилии мавҷудият доранд.</li>\n<li><strong>Чӣ миқдори об метавонад дар ҳар чанкӯни чанкӯни ба наутси бӯрзӣ расад?</strong><br>Убури об дар ҳар чанкӯни чанкӯни асосан масофа байни чанкӯни чанкӯни танзим мешавад. Одатан масофаи 40 сантимилметрӣ дар бастаҳои 16 милметрӣ, ба ҳар чанкӯни чанкӯни тақрибан 2 то 3 миллитр дар соат мерасад. Барои расидан ба амикияти мувофиқ барои решаҳо, бояд вақти оборишро чунин танзим кунед, ки амикияти таршавӣ тақрибан 30 то 40 сантимилметр бошад.</li>\n<li><strong>Оё метавон аз бастаи нӯриро дар наутси бӯрзӣ бо парваришҳои пайдарпай истифода бард?</strong><br>Бале, аммо одатан ҳар 1 то 2 фавсон иваз кардан тавсия дода мешавад. Наутси бӯрзӣ решаҳои худро мустақиман дар роҳи бастаи нӯриро ҷойгир мекунад ва пас аз хариди мазрук, баста дар замин монда мешавад ё ҷамъ карда мешавад. Давомнокии бастаи нӯриёи стандартӣ дар хокҳои дорои намакнокӣ ва рароси баланд, камтар аз як фавсон аст.</li>\n</ul>\n\n<h2>Хулоса ва роҳҳои сохтани маъмулӣ</h2>\n<p>Истифодаи обориши чанкӯни чанкӯни ва бастаи нӯриро дар парвариши наутси бӯрзӣ, як ҳалли устувор ва самаранок аст. Бо риояи принсипҳои ғарм кардани дақиқ, расми обориши тайидоҳарӣ ва идоракунии оқилонаи ғизо, умедвор шудан мумкин аст, ки сифати пашми наутси бӯрзӣ зиёд мешавад ва зиёнҳо аз боси обӣ ба сифр мерасад. Барои кишлокистон, ки дар ҳолати парвариши дигар рӯшногиҳо доранд, фаҳмиши принсипҳои асосӣ чун <a href="https://navar-abyari.ir/barley-yield-per-hectare-factors-increase/">Омилҳои зиёдшавии ҳосилнокии барҷӯр дар ҳектар</a> инчунин ба фаҳмиши барҷӯйтар аз идоракунии обёркунии маҳсулоти дигар кӯмак мекунад. Ҳар чӣ системаи обёркунӣ дақиқтар бошад, имконияти чашнокшавӣ дар шароити тағйирёбандаи иқлимӣ зиёдтар мешавад. Шумӯр <a href="https://navar-abyari.ir/%D9%81%D8%A7%D8%B5%D9%84%D9%87-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%AF%D8%B1-%D9%84%D9%88%D8%A8%DB%8C%D8%A7/">фасеҳи нӯри типи дар нонӣ</a> ки бо пӯскат аз рӯи сохтори реша ва лозимиятҳои об ба мувофиқат доранд, метавонад фаҳмиши беҳтареро аз принсипҳои физиологӣи рӯяҳон ҳассос ба стресс эҷод кунад. Дар охир, назорати мунтазами таркиши хок бо пробҳои дастӣ ё сенсорҳои худкор, калиди муваффақият дар истифодабарии ин технология аст.</p>\n\n','Омоян барои парвариши пахта бо суғории қатқа ва техникаи навори Тейп','Поя яке аз муҳимтарин маҳсулоти кишоварӣ аст, ки ба идоракунии дақиқи об ва ғизоиан нияз дорад. Дар ин дастури ҷамъбаст, бо принсипҳои кӯрпаеши поя бо оғозкунии обдиҳии қатрагӣ ва навъи пинҳонӣ шинос мешавед. Аз сохтани шабака то тақвоми вақти обдиҳӣ ва ғизоиан, тамоми ҷанбаҳои амалиро баррасӣ мекунем, то шумо метавонед маҳсулоти сифатнок ва самараноки баланд ба даст оред. Истифодаи навъи пинҳонӣ на танҳо маблағгузории обро кам мекунад, балки решаи хубтар ва камшавии алафҳои бекорро низ дар бар мегирад.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
