SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='comprehensive-cucumber-drip-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'comprehensive-cucumber-drip-irrigation-guide','comprehensive-cucumber-drip-irrigation-guide-crop-121-en');
