SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='khamillagi-shurbo-obori-kuyatragi' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'khamillagi-shurbo-obori-kuyatragi','khamillagi-shurbo-obori-kuyatragi-crop-121-tj');
