START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-123' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-123:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='mishdori-bodish-shabdari-dar-gaktar' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'mishdori-bodish-shabdari-dar-gaktar','mishdori-bodish-shabdari-dar-gaktar-crop-123-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'mishdori-bodish-shabdari-dar-gaktar-crop-123-tj-24e4a676');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима ба аҳамияти дақиқ дар кишт кардани люцерн</h2><p>Люцерн яке аз муҳимтарин ҳеширҳои хӯроки чорвод ва пӯшишбахшест, ки дар кишоварзии муосир ҷойгоҳи махсус дорад. Муайян <strong>миқдори тоҳукҳои люцерн дар ҳектар</strong> як муодилаи ғайриоддие аст, ки дар он метгузариҳои иқлим, намуди хок, усули кишт ва системаи обварӣ бояд ба назар гирифта шаванд. Бисёр деҳқонҳо аз сабаби таҳсилоти кам дар ин мавзӯъ, бо партобидани тоҳук зиёдатӣ ё камтар ҳарфазл ҳастанд, ки боиси рақобати шадиди ҳеширҳо бо ҳам ё гирдогир будани шохаҳо мегардад. Дар ин мақола, мо таҳқиқи дақиқи ин омилиро дида мебарем ва тавсияҳои амалӣ барои беҳтар кардани раванди кишт ва нигоҳубин пешниҳод мекунем.</p><p></p><h2>Омилҳои таъсиррасон ба муайян кардани суръати тоҳукҳои люцерн</h2><p>Барои ҳисоб кардани дурусти миқдори тоҳуки зарурӣ, наметавон танҳо ба як рақами собит таваҷҷӯҳ кард. Омилҳои зиёде вуҷуд доранд, ки бояд ҳамзамон ба назар гирифта шаванд. Дар поён оҳиста-оҳиста ба муҳимтарини ин омилҳо мепардозем:</p><ul><li><strong>Намуди наслҳои люцерн:</strong> Наслҳои гуногун (масалан, сурх, сафед ё кабуд) қобилиятҳои гуногуни рушдро доранд. Баъзе наслҳо рушди тезтаре доранд ва метавонанд ба зичии тоҳук камтар ниёз дошта бошанд.</li><li><strong>Система кунӣ:</strong> Кунӣ бо хок, наздик ба сатҳ ё омехта ҳар кадом тағотҳои мушаххасро дар истифодаи тоҳол доранд. Дар кунӣ бо хок одатан барои пӯшонидани муносиби сабзиҳо тоҳоли бештар истифода мешавад.</li><li><strong>Рӯҳонии хок ва системаи обёрӣ:</strong> Бариҳе рӯҳонӣ нақши муҳимро дар ҷомеъ мебошад. Системаҳои обёрӣ бо қулфҳои тамғаҳо ва наҳасти тақлид имкони идоракунии дақиқтари рӯҳонии гилҳаро фароҳам меоранд, ки метавонад ба камшудани стресси об ва беҳтар кардани истифодаи тоҳол оварда расонад. Барои шиносӣ бо фарқияти намуди мухталиф шлангҳои обёрӣ ва истифодаи онҳо дар шароити гуногун, метавонед ба <a href="https://navar-abyari.ir/raining-pipes-types-and-uses/">намуди мухталифи шлангҳои обёрии қулфҳо ва наҳасти тақлид</a> омезед.</li><li><strong>Ҳолати тоҳолӣ:</strong> Дараҷаи шубҳаи тоҳол (витияти) дар ҳисобкунии охирин хеле муҳим аст. Агар фоизи шубҳа паст шуда бошад, бояд фоизи бештари тоҳол кунда шавад, то зичии ниҳоии иловаҳо ба даст орасад.</li></ul><h2>Миқдорҳои тавсияшудаи бӯرӣ вобаста ба шартҳои корт</h2><p>Дар умум, меъёрҳои байналмилалӣ ва таҷрибаҳои маҳаллӣ нишон медиҳанд, ки диапазони тавсияшудаи корти наҷоф муғайяр аст. Барои роҳнамоии беҳтар, ҷадвали зерин маҷмӯаи миқдорҳои оддиро нишон медиҳад:</p><table border="1"><tbody><tr><th align="center">Шартҳои корт</th><th align="center">Миқдори бӯрӣ (килограмм дар гектар)</th><th align="center">Шарҳҳо</th></tr><tr><td>Корти хокӣ (донаҳои калон)</td><td>15 то 20</td><td>Мусоид барои хокҳои бо зехкории хуб ва камбудии вазъии об</td></tr><tr><td>Кашт сатҳӣ (духӯб ҷисмонӣ)</td><td>8 то 12</td><td>Беҳтарин усул барои нигоҳ доштани тарӣ ва тез шудани намоиш</td></tr><tr><td>Кашт омехта бо дон</td><td>3 то 5</td><td>Камтар ҷисмонӣ истифода мешавад, то рақобат бо донро кам кунад</td></tr><tr><td>Ҷисмонҳои паст тарӣ (< 80%)</td><td>Афзоиш 20-30% нисбат ба миқдори асосӣ</td><td>Барои ҷуброни тармокии паст</td></tr></tbody></table><p>Диққат ба интихоби миқдори бӯдҳои бехи (seed rate) мустақиман ба сифати пӯшиши гиёҳӣ дар фаслҳои оянда таъсир мерасонад. Агар кӯлоҳ зиёд бошад, гиёҳҳо дар марҳалаи буттагӣ (bush stage) рақобати шадид барои роҳнамоӣ ва моддаҳои ғизоӣ пайдо мекунанд ва афзоиши амудии онҳо маъюб мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-شبدر-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر شبدر در هکتار: راهنمای جامع - تصویر 1"/><figcaption>miqdori buda per hectare crop shabdar</figcaption></figure><h2>Нақши системаи обёрии бӯрагӣ ва навар-тип дар идоракунии кишт</h2><p>Яке аз унсурҳои асосии кисти дақиқ идоракунии об аст. Шабдар гиёҳест, ки ба тармокии миёна ниёз дорад, вале аз омаишӣ ва тармокии зиёдатеро дар атрофи бӯдҳои бехи (seed rate) инкор мекунад; зеро ба фасодшавии қарахтӣ (қарч) оварда мерасонад. Системаҳои обёрии бӯрагӣ ва навар-тип имконияти эҷоди муҳити тармокии мувозинатнокро фароҳам меорад.</p><p>Истифодаи навар-тип барои кишти шабдар арзишҳои махсус дорад. Шлангҳои навар-тип дар фосилаҳои муайян дар замин ҷойгиранд ва обро мустақиман ба навари решаҳо мерасонанд. Ин чунин боиси мешавад, ки тармокӣ дар қисме, ки гиёҳ ба он ниёз дорад, нигоҳ дошта шавад ва қисмҳои дигари хок барои бухоршавии табиӣ дастрас бошанд. Барои онҳое, ки дар марҳалаи ҳисобкунии иқтисодӣ мебошанд, назорати хараҷи навар-тип барои як гектар метавонад дар қабули қарор дар бораи сармоягузории аввалин таъсири дорад.</p><p></p><h2>Нуқтаҳои амалӣ барои кист ва назорат пас аз нақш</h2><p>Пас аз кишт кардани шабдар, идоракунии тармокӣ ва роҳнамоӣ аҳамияти дучандо пайдо мекунад. Нуқтаҳои зерин ба шумо кӯмак мекунанд, ки аз имкониятҳои баландтарини бӯдҳои нақшшуда истифода баред:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-شبدر-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر شبدر در هکتار: راهنمای جامع - تصویر 2"/><figcaption>norm of seeding per hectare of alfalfa crop</figcaption></figure><ol><li><strong>Sowing at the optimal time:</strong> Alfalfa has the best sowing time in late summer and early autumn. Soil temperature should be suitable for it to ensure rapid germination.</li><li><strong>Sowing at appropriate depth:</strong> Alfalfa seeds are small and should not be sown deeply. A depth of 1 to 1.5 centimeters is ideal. Too much depth will cause the seeds to remain in the soil without germinating.</li><li><strong>Supplementary irrigations:</strong> In case of insufficient rainfall, light and frequent irrigation is essential to create stable conditions for germination. Using the advantages of drip irrigation alongside the furrow at this stage can help in the uniform distribution of moisture in the sowing rows.</li><li><strong>Weed management:<!--ć--> Азбобки бардоди сабиз хеле тез аст, он боисҳои хашхӯро табиӣ зағир карда метавонад. Аммо агар зичии бугурмонан кам бошад, хашхӯҳо фурсат пайдо мекунанд, ки афтод, ва бояд бо маводи дузуронида мувофиқ инъикор кард.</li></ol><h2>Таъсири абобари ба ҳосилоти умумии маҳсулот</h2><p>Коробҳои дақиқ бугурмонан на танҳо ним ҳал мебошад; нимаш дигар идоракунии маҳсулоти баъд аз короб аст. Сабиз, агар бо системаҳои абобарии пайвандон мувофиқ карда шавад, метавонад ҳосилоти устувортар ва боварииро дошта бошад. Ин системаҳо аз тавнонии об манъ мекунанд ва имконият медиҳанд, ки риштакҳо дар шароити муфосирот қарор гиранд.</p><p></p><p>Илова ба сабиз, бисёр маҳсулот, ба монанди пиёз, бо истифода аз усулҳои абобарии пайвандон ҳосилоти баландтар доранд. Барои беҳтар дарк кардани асосҳои умумии абобарии пайвандон дар короби гуногун намудҳои маҳсулот, шумо метавонед мақолае ҳақи одаданд <a href="https://navar-abyari.ir/drip-irrigation-onion-planting-iraq/">Аبوبарии пайвандон дар короби пиёз</a> ро омӯзед, зеро бисёре аз принсипҳои техникии он барои сабиз низ гуногуншуда мешавад.</p><h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2><h3>Муайян аст, ки чанд кг бугурмони сабиз дар ҳар гектар короб мешавад?</h3><p>Ҷавоб ба намуди фармаиш вобаста аст. Барои фармаиши стандартии заминӣ одатан аз 15 то 20 килограмм ва барои фармаиши сатҳӣ аз 8 то 12 килограмм барҳисоб мегиридад. Инчунин агар шарикии тоҳук камтар аз 90 фоиз бошад, бояд миқдори зиёди тоҳук илова кард.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-شبدر-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر شبدر در هکتار: راهنمای جامع - تصویر 3"/><figcaption>norm of seeds per hectare for crop clover</figcaption></figure><h3>Оё чӯрпанош (шибдар)-ро бо системаи обёркунӣ барои наварҳои ларвӣ (drip tape) бошунавонидан мумкин аст?</h3><p>Бале, чӯрпанош (шибдар) яке аз ниҳодҳост, ки бо наварҳои ларвӣ (drip tape) мувофиқати хеле баланд дорад. Ҷойгир кардани шлангҳо дар наварҳои дохти ба он овардани он ки намӣ бевосита ба минтақаи решаҳо мерасад ва аз бемориҳое, ки аз об иловаӣ дар тоҳук ба вуҷуд меоянд, пешгирӣ мекунад.</p><h3>Харобаи чӯрпанош (шибдар) бо дигар дунҳо чӣ гуна ба истеъмоли тоҳук таъсир мерасонад?</h3><p>Дар фармаиши омехта, ба сабаби рақобат, истеъмоли тоҳуки чӯрпанош (шибдар) кам мешавад. Масалан, дар фармаиши омехта бо кукуруза, миқдори тоҳуки чӯрпанош (шибдар) метавонад то 3 то 5 килограмм дар гектар расад. Нуқтаи муҳим дар ин баҳс интихоби навидҳои мувофиқ ва идоракунии обёркунии мувозинатнок аст, ки метавонад тавассути омӯзиш <a href="https://navar-abyari.ir/tarzi-intihobi-tasmai-obyari-nuqtagiri-muvofiq/">Роҳҳои интихоби системаи мусоиди обёркунии қатрӣ</a> оптимизатсия шавад.</p><h2>Хулоса</h2><p>Интихоб ва муайян кардан <strong>Милли бои сина (овся) дар як гектар</strong> Ин як ҳалли техникӣ ва иқтисодӣ аст, ки ба муваффақияти тамоми мавсими коркашӣ таъсир мерасонад. Риояи принсипҳои коркарди дақиқ, истифодаи бойи ободони баланд ва беҳтарсозии системаи оби чуқур ё навиштии пайваста метавонад ба кам шудани хароҷот ва баланд шудани сифати пӯшиши гиёҳӣ оварда расонад. Мошавон карда мешавад, ки пеш аз харидани бой ва оғоз намудани коркашӣ, шароити иқлимии боғро баррасӣ кунед ва бо як масlahаткунандаи минтақавӣ мувофиқат кунок, то то рақамҳо ва системҳои оби мувофиқро барои эҳтиёҷоти боғ интихоб кунед. Бо риоя ин рӯёна, шумо метавонед аз имкониятҳои пурраи сина (овся) дар боғи худ фоида бардоред.</p>\n<p><strong>Мавзӯи алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%87%d8%b2%db%8c%d9%86%d9%87-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a8%d8%b1%d8%a7%db%8c-%db%8c%da%a9-%d9%87%da%a9%d8%aa%d8%a7%d8%b1-%da%86%d9%82%d8%af%d8%b1-%d8%a7%d8%b3%d8%aa%d8%9f/">Сарфнамои навиштии пайваста барои як гектар чӣ қадар аст?</a></p>','Миқдори бодиш-шабдери дар гектар: Раҳнамои мукаммал барои беҳтар кардани партоб ва обёрӣ','Муайяни дақиқи миқдори бодаи риҷис дар ҳектар на танҳо барои ҳамои ниҳоии кишоварзӣ, балки барои сифати растаниҳо ва устувории ҳосил таъсир мерасонад. Дар ин дастур тафсилоти техникӣ ва маслиҳатҳои амалӣ барои кишоварзоне, ки ҷустуҷӯи самаранокии баландтаринро доранд, шарҳ дода шудааст.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
