START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-124' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-124:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='optimizatsiya-yi-miqdori-hosili-pioz-dar-hektar-bo-systemai-shtrihi-tip' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'optimizatsiya-yi-miqdori-hosili-pioz-dar-hektar-bo-systemai-shtrihi-tip','optimizatsiya-yi-miqdori-hosili-pioz-dar-hektar-bo-systemai-shtrihi-tip-crop-124-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'optimizatsiya-yi-miqdori-hosili-pioz-dar-hektar-bo-systemai-shtrihi-tip-crop-124-tj-dcf780b8');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарот: Аҳамияти оморавии дақиқ дар парҳези пиёз</h2>\n<p>Пиёз яке аз сабзаҳои асосӣ ва пурхост дар бозорҳои кишоварӣ аст, ки ҳассосияти баланди шароити обӣ ва хок дорад. Барои расидан ба <strong>ҳазми миқдори ҳосили пиёз дар гектар бо наварии типӣ</strong> баландтар, идоракунии дақиқи захираҳо ва тағоззои обӣ ва моддаҳои ғизоӣ нақши муайянкунандаро боз мекунад. Системаҳои оморавии анъанавӣ, ба монанди обдорӣ (топол), аксар вақт боиси талафоти об ва пӯсидашудагии буттагии пиёз мегарданд. Дар муқобил, наварии типӣ бо ҷамъ кардани об ва моддаҳои ғизоӣ дар ҳудуди реша, на танҳо сарфрасиди обро кам мекунад, балки бо зиёд шудани ҷабби решагӣ, боиси калон шудани сари пиёз ва зиёд шудани вазни ҳар дона мегардад.</p>\n<p>Истифодаи ин технология дар иқлимҳои хушк ва нимхушки Ӯрон, роҳи аслӣ барои устувор кардани самаранокӣ мебошад. Дар идома, тамоми ҷанбаҳои техникӣ ва амалӣ ин мавзуро баррасӣ мекунем.</p>\n\n\n\n<h2>Тасироти системаи наварии типӣ ба физиологияи пиёз</h2>\n<h3>Идоракунии намнокӣ дар минтақаи решагӣ</h3>\n<p>Пиёз як растаки решаҳои сатҳӣ ва боноқ аст, ки ба намнокии мувофиқи хок ниёз дорад, бе он ки решаҳо дар муқобили тарқеи пурраи об қарор гиранд. Наварии типӣ бо эҷод кардани наварии обнок дар тарафи сатҳи кишт, заминаи идеалӣ барои рушди решаҳоро фароҳам меорад. Ин усул ба ин боис мешавад, ки решаҳо дар тӯли дарозтарин вақт бо захираҳои ғизоӣ ва обӣ шинос шаванд.</p>\n<p>Таҷриба нишон дод, ки деҳқонон ҳангоми интихоби система бояд ба шарти риба-такти-креат низ диққат диҳанд, зеро мураккабиҳои хок ва намуди таркиши об ба якхела будани тақсимоти об дар тӯли сафъи пиёз таъсири мустақим доранд.</p>\n\n<h3>Баланд бардоштани ҷабзиши моддаҳои ғизоӣ ва кам кардани бемориҳо</h3>\n<p>Яке аз сабабҳои асосии кам шудани ҳосилдории пиёз, вайрон шудани реша ва пояст, ки аксар вақт бо обёркунии зиёд ҳамроҳ аст. Навъи ҷилбобкунии решаӣ имконпазир аст. Бо парҳези решаӣ ҷабзиши калсий, селен ва олеуминҳои майкроғизоӣ беҳтар мешавад. Инчунин, кам шуданинамуди дар байни рафҳо фаъолияти занбӯруҳҳои хокӣро маҳдуд мекунад. Ин раванд монанди принсипҳое аст, ки дар танфили формил-дар-ҳектар низ барои оптимизатсияи афзоиши дигар кӯлакҳо зикр шудааст, ҷое ки мувозинат байни афзоиши андоза ва танфас ба сифати маҳсулоти ниҳоӣ таъсири мефишорад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-پیاز-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت پیاز در هکتار با نوار تیپ - تصویر 1"/><figcaption>crop yield per hectare drip irrigation пёз</figcaption></figure>\n\n\n\n<h2>Омилҳои асосии таъсиркунанда ба ҳаҷми ҷамъоварии пиёз</h2>\n<h3>Фосилаи партофтан ва навъи ҷилбобкунии об</h3>\n<p>Фосилаи партофтан дар пиёз бевосита бо имконияти ҷойгиркунии системаи навъи ҷилбобкунии об вобаста аст. Сафҳои чандон ба ҳам метавонанд ба такрори навҳои обёркунӣ ва вайрон шудани нуқтаҳои хушк ё намдор оварда расонанд.</p>\n<ul>\n<li><strong>Фосилаи сафҳо:</strong> Одатан барои пиёз 40 то 50 сантиметр мувофиқ аст, ки бо ғадаи нӯрипӯшип хамкорӣ кунад.</li>\n<li><strong>Кунҷи шидати нӯрипӯшип:</strong> Кунҷи баромадани об аз нӯрипӯшип бояд бо суръати даромадани об ба хок мувофиқат кунад, то об ба чуқурии решаҳо расад.</li>\n</ul>\n<p>Дар ин самт, таҳқиқот <a href="https://navar-abyari.ir/sugar-beet-row-spacing-standards/">Стандартҳои масофаи сатҳҳои чӯқанд</a> Илова бар ин, метавонад намунае аз принсипҳои монанд дар парвариши решаҳои решагин бошад, ки дар он танзими дақиқи масофаи сатҳҳо барои ягонагии системаи обёрӣ муҳим аст. Пиёз ҳам чун чӯқанд ба якнафисии пӯшиши обёрӣ зарур дорад.</p>\n\n<h3>Давомнокии обёрӣ ва такрор</h3>\n<p>Мудирати вақти обёрӣ бо нӯрипӯшип бояд асоси минтақакунии буткаи пиёз анҷом шавад. Дар марҳилаҳои аввалии афзоиш, эҳтиёҷ ба об камтар аст, аммо дар вақти пуршудани пиёз (40 то 60 рӯз пеш аз ҷамъоварӣ), эҳтиёҷ ба об ба қулла мерасад. Кӯтоҳ кардани обёрӣ дар марҳилаҳои ниҳоӣ ба ҷамъомадани пиёз кӯмак мекунад.</p>\n<p>Барои беҳтар фаҳмидани муқоисаи самаранокии кор дар системҳои гуногун, ба матни миқдори барори сиҳиқ ба ҳар гектар рӯй оред, ки чӣ гуна таъсири ороиш бо намунаҳои пайпаси бар майдони бодехорҳо ба монанди онро ифода мекунад. Қоидаҳои физики ороиш бо намунаҳои пайпас барои ҳарду меҳвора яксон аст, вале содди иқтисодии пийоз бо сабаби арзиши зиёдкарда барои маводи омода гардидан, ҷозибаи зиёдтар дорад.</p>\n\n\n\n<h2>Масъалаҳои амалӣ барои боғҳои пийоз</h2>\n<h3>Интихоби навъи намунаи пайпас</h3>\n<p>Дун навъи асосии намунаи пайпас вуҷуд дорад: намунаи пайпас бо моҳиҳои гуногун (1/6 то 1/4 дюйм) ва намунаи пайпас бо моҳи бештар пурзӯр. Пийоз ба намунаҳои хурд ва якхела ниёз дорад, то ки об ба сифати ғизоҳо дар зами замин паҳн шавад. Истиноди намунаҳои қалонтар метавонад ба шакли гиёҳҳои амиқ ва хушк шудани решаҳои болоӣ оварда расонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-پیاز-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت پیاز در هکتار با نوار تیپ - تصویر 2"/><figcaption>crop yield per hectare drip irrigation пийоз</figcaption></figure>\n<p>Дар интихоби лавозимот, маслиҳат бо раҳокунии чӣ гуна иваз ва самаранокии намунаи пайпас тавсия дода мешавад, то ки бебаҳои фаъолияти дарозмуддати система амини шуда шавад.</p>\n\n<h3>Мураттат бо нақби барандон ва системаҳои иловагӣ</h3>\n<p>Дар баъзе ҳолатҳо, мутталисимаи намунаи пайпас бо системаҳои иловагӣ, ба монанди нақбҳои барандон намудиҳо ва истинодҳо барои паҳн намудани минтақаҳои марги сиҳиқ дар ибтидои шитобҳо метавонад фаъолиятнок бошад. Инчунин, истиноди меъёрҳои интихоби намунаи пайпаси кишоварзӣ бар асоси навъи замин (ранг ё қумӣ) беҳбуд дода мешавад. Дар заминҳои қумӣ, нафаскашӣ тезтар аст ва ниёз ба намунаҳои бо фишори нисбатан зиёдатар доранд.</p>\n\n<h3>Ҷадвали муқоисаи истеҳсоли пиёз дар системаҳои гуногун</h3>\n<table>\n<thead>\n<tr>\n<th>Системаи обёрӣ</th>\n<th>Барабарии об (килограмм дар як метри мураббаъ)</th>\n<th>Ҳаҷми тахминии ҳосили пиёз (тонна дар гектар)</th>\n<th>Фароғати иқтисодӣ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Обгарм (полатарӣ)</td>\n<td>1/5</td>\n<td>10-15</td>\n<td>Камтарин</td>\n</tr>\n<tr>\n<td>Рibbonи қатъшударӣ (nobar)</td>\n<td>2/5</td>\n<td>20-25</td>\n<td>Баландтарин</td>\n</tr>\n</tbody>\n</table>\n<p>Чунки мебинед, системаи қатъшударии нарбар (nobar) бо зиёдшавии назарраси ҳаҷми маҳсул, хароҷоти обкориро кам мекунад. Ин намуна монанди таҳлилҳое аст, ки дар бораи <a href="https://navar-abyari.ir/oat-yield-per-hectare-guide/">Миқдори варзиш (бардошт) ҷав дар ҳектар</a> Барои набототи дунёӣ пешниҳод шудааст, аммо шағгол бо сабаби ниёзи зиёти об дар марҳалаи пухтани сабзавот, бунбасти баландтарро дар қатъшударии нарбар (nobar) дорад.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё барои зиёд шудани сабзӣ (bulb) тасмаи (line) беҳтар аст ё тақриқан (drip)?</h3>\n<p>Тасма (line) барои зиёд шудани сабзӣ одатан беҳтар аст, зеро фарогирии яхсайи равшантарро дар андозаи (width) рахоб (bed) меовард. Системаи тақриқан барои наботот мувофиқтар аст, ки ба тарозии (feeding) марказии яхсаи бисёр мутамарказ ниёз доранд. Пياز решаҳои сатҳӣ паҳншуда дорад ва тасма (line) ин ниёзро беҳтар иҷро мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-پیاز-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت پیاز در هکتار با نوار تیپ - تصویر 3"/><figcaption>crop yield per hectare drip irrigation پیاز</figcaption></figure>\n<h3>Чӣ тавр метавонам аз фуседан (rot) пيازро бо тасма (line) пешгирӣ кунам?</h3>\n<p>Бо кам кардани вақти обёрӣ дар охири давраи рушд (ҳафтаи охирин пеш аз интиқол) ва таъмини хушкӣ дар фазои байни рахобҳо. Инчунин истифодаи пӯлолаҳо (mulch) мувофиқ барои пешгирии тамоси мустақими пياز бо хок тарк.</p>\n<h3>Таъсири чуқории қабати шурӯд (plowing) бар тасма (line) пياز чист?</h3>\n<p>Шурӯди чуқур ниёз ба танзими фишори баромади тасма (line) дорад, то об ба чуқурии пайдоишудаи решаҳо расад. Дар пياز, одатан решаҳо то чуқурии 30 см паҳн мешаванд. Танзими система бар асоси ин чуқурӣ аз партофтани беҳуда об пешгирӣ мекунад. Таҳқиқот <a href="https://navar-abyari.ir/licorice-harvest-yield-per-hectare-factors/">Омилҳои таъсиркунанда ба ҳосили яки ҳектар ликоприс</a> Интиқоми системаи обёрӣ бо чуқурии ҷудуи решаи ғалладони ҳамоҳанг буданро низ таъкид мекунад.</p>\n\n<h2>Хулоса</h2>\n<p>Афзун кардан <strong>Афзун кардани ҳосили пиёз ба ҳисоби яки ҳектар тавассути наварчии қатқола</strong> Ин як равиши ихтиётии аст, ки лозими эҳтиёт дар фосилаи ғалладонӣ, интихоби мусоиди таҷҳизот ва идоракунии бизоатонаи вақти обёрӣ аст. Ин система бо афзун кардани самаранокӣи об ва ғизои реша, на танҳо ҳосилиро баланд мебаррад, балки сифат ва давомнокии пиёзро низ беҳтар мекунад. Бо назардошти қиммати иқтисодии баланди пиёз ва камбудии захираҳои обии, сармоягузорӣ ба наварчии қатқола яке аз муҳимтарин қадамҳое дар кишоварзии муосир аст. Ба кишоварзон тавсия мекунад, ки пеш аз паҳнкунии ин система, бо назардошти намуди хок ва шароитҳои иқлимии маҳаллӣ, аз маслиҳатҳои тахассусии обёрӣ истифода баранд.</p>\n<p><strong>Мақолаҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D8%B4%D8%B1%D9%8A%D8%B7-%D8%A7%D9%84%D8%B1%D9%8A-%D8%A8%D8%A7%D9%84%D8%AA%D9%86%D9%82%D9%8A%D8%B7-%D9%81%D9%8A-%D8%AA%DA%A9%D8%B1%DB%8C%D8%AA/">D8B4D8B1D98AD8B7 D8A7D984D8B1D98A D8A8D8A7D984D8AAD986D982D98AD8B7 D981D98A D8AADAA9D8B1DB8CD8AA</a></p>','Оптимизатсияи миқдори ҳосили пиёз дар гектар бо системаи штрихи Tip','Ошно шудан бо усули баланд барорӣ кардани ҳосили пиёз тавассути системаи қатораи тиби, идоракунии дақиқи об ва ғизои растаниҳо ва нуқтаҳои калидӣ барои расидан ба сатҳи максималии самаранокии дараматшавии пиёз.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
