SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='drip-tape-maintenance-cucumber-farming-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'drip-tape-maintenance-cucumber-farming-guide','drip-tape-maintenance-cucumber-farming-guide-crop-126-en');
