SET @resolved_slug=IF(@slug_conflict IS NULL,'idorokunii-mukammali-zararavaron-kinua-sistema-oborii-qatragi','idorokunii-mukammali-zararavaron-kinua-sistema-oborii-qatragi-crop-131-tj');
