SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='fosilayi-gallay-dar-parhezi-gub-standardha' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'fosilayi-gallay-dar-parhezi-gub-standardha','fosilayi-gallay-dar-parhezi-gub-standardha-crop-132-tj');
