SET @resolved_slug=IF(@slug_conflict IS NULL,'komsilli-ghurur-ghurur-ob-andozavi-ghurur','komsilli-ghurur-ghurur-ob-andozavi-ghurur-crop-133-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'komsilli-ghurur-ghurur-ob-andozavi-ghurur-crop-133-tj-7c0d47fe');
