SET @resolved_slug=IF(@slug_conflict IS NULL,'zararavaro-ham-bemorihoi-kabubo-obori-qiqtargi-natiabi','zararavaro-ham-bemorihoi-kabubo-obori-qiqtargi-natiabi-crop-134-tj');
