SET @resolved_slug=IF(@slug_conflict IS NULL,'purra-hokumi-zarar-korbi-bi-sistemi-obi-bi-qatra','purra-hokumi-zarar-korbi-bi-sistemi-obi-bi-qatra-crop-138-tj');
