SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='cullina-tipi-tape-drip-cost-per-hectare' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'cullina-tipi-tape-drip-cost-per-hectare','cullina-tipi-tape-drip-cost-per-hectare-crop-141-en');
