SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='rosemary-maintenance-tefrip-tape-optimal-irrigation' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'rosemary-maintenance-tefrip-tape-optimal-irrigation','rosemary-maintenance-tefrip-tape-optimal-irrigation-crop-144-en');
