START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-152' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-152:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='daromadi-kokcha-az-gektar-bo-nabarabshor' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'daromadi-kokcha-az-gektar-bo-nabarabshor','daromadi-kokcha-az-gektar-bo-nabarabshor-crop-152-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'daromadi-kokcha-az-gektar-bo-nabarabshor-crop-152-tj-cbfb2bcc');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Чаро оварии навозӣ барои клзза муҳим аст?</h2>\n<p>Корзори клзза дар минтақаҳои нимхушк ва хушки Эрон, ба сабаби вобастагии баланд ба боронборӣ, хатарҳои баланд дорад. Яке аз калидҳои асосӣ барои устуворӣ ва зиёдшавии <strong>Миқдори кабудӣи пирог дар як гектар</strong>ин дар бораи идоракунии дурусти об аст. Дар миёни инҳо, системаи обёрории нақшипӣ (напӣ) бо сабаби тақсимоти мувоҷибшудаи об дар шитонҳои кӯтоҳ, имконияти назорати дақиқи намнокӣ дар қаламрави решаҳои баргиро таъмин мекунад. Ин усул на танҳо аз камобӣ дар марҳилаҳои ҳассоси рушд пешгирӣ мекунад, балки бо пешгирӣ аз намнокии зиёд дар баргҳо, аз пайдо шудани бемориҳои занбокорӣ низ пешгирӣ менамояд. Барои фаҳмиши беҳтари механизмҳои рушди барги дигарҳои равғанӣ ва донадор, ки бо намунаҳои шабеҳ мутобиқат мекунанд, омӯзиши равишҳои куштории барги дигарҳои коспа низ фоидаовар аст. Барои муқоисаи намунаҳои обёрорӣ ва кабудӣ, метавонед роҳнамои мукаммалро дар мавзӯи миқдори обёрории нақшипӣ дар як гектар омӯзед, ки намунаҳои шабеҳи идоракунии зичӣ ва об дорад. Дар пайравӣ, мо ба баррасии муфассалтари ҳар яке аз ин мавҳот мепардозем, то ба усули куштории оптималӣ нолидед.</p>\n\n<h2>Таъсири бевоситаи нақшипӣ ба потенсиали кабудии пирог</h2>\n<p>Хароҷоти канова беназоя ба таъмини даими оби дар марҳилаҳои калидӣ, яъне ҳастии сабз, гулдармонӣ ва тӯлӣ додани дона, вобаста аст. Обинории шитобҳо бо эҷоди шитобҳои намноки пайваста, амиқии боракнии обро дар решаҳо зиёд мекунад. Таҳқиқот нишон додаанд, ки бо истифода аз ин усул, дарсади намии хок дар сатҳи муносиб дар тамоми давраи рушд нигоҳ дошта мешавад. Ин мустақиман ба зиёд шудани шумораи рӯяни дар ҳар воҳиди масоҳат ва дар охир ба афзоиши вазни дона оварда мерасонад. Беҳтар кардани шитобҳои кардан ва обинории принсипи муҳим аст. Дар системаи шитобҳо, масофа байни шитобҳо бояд дақиқан бо андозаҳои системаи обинории мувофиқат дошта бошад. Одатан тавсия дода мешавад, ки шитобҳои кардани канова беназоя 60 то 70 сентиметр масофа аз ҳам дошта бошанд. Ҷойгир кардани шитобҳои паштаи об ё чанчонаҳо дар ин хатҳо таъмин мекунад, ки об дақиқан дар радиуси 50 то 60 сентиметри решаи асосӣ ҷойгир шавад. Ин дақиқӣ боиси мешавад, ки оби истифодашуда на барои аз даст рафтан дар табуш байн меравад ва на дар шустани моддаҳои модарӣ ба амиқҳои ғайрирешавӣ фурӯ меравад. Барои беҳтар фаҳмидани аҳамияти тарроҳии фазо дар шитобҳо, ба тарзи тарроҳӣ дар маҳсулот дигар низ нигаристан мумкин аст. Масалан, роҳнамои миқдори бадани ҷав дар гектар нуктаҳои дақиқро дар бораи ҳисобҳои фишор ва ҷараёни система пешниҳод мекунад, ки барои канова беназоя низ истифода бардаст. Бо риояи ин нуктаҳо, шумо метавонед аз хароҷоти об пешгирӣ карда ва ба самаранокии баландтар барсид.</p>\n\n<h2>Нуктаҳои амалии кардан ва идоракунии шитобҳо дар канова беназоя</h2>\n<p>Пеш аз оғози давраи кардан, тайёр кардани замин ва ҷойгир кардани дурусти асбобҳо аҳамияти баланд дорад. Канова беназоя ба хоби зареҳкӣ зарурат дорад; бинобар ин, агар сохтори хок шумо вазнин бошад, эҷоди шитобҳои амиқ ба беҳтар шудани боракнишӣ кӯмак мекунад. Дар ҳоло, муҳимтарин нуктаҳои амалиӣ барои муваффақият дар ин система таҳлил мешавад:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-کلزا-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت کلزا در هکتار با نوار تیپ - تصویر 1"/><figcaption>crop yield per hectare drip irrigation канова беназоя</figcaption></figure>\n\n\n<ol>\n    <li><strong>Интихоби бадони сифатӣ:</strong> Аз бӯгоҳиҳои ҷамъбастшуда бо дараҷаи хӯрдшавии зиёдатари 95% истифода баред. Зичии боридан дар навбати намоиш одатан аз 250 то 350 килограмм бӯгоҳ бар ҳектар, вобаста ба иқлим, тағйир меёбад. Барои муқоисаи зичии боридан дар маҳсулоти дигари равғонӣ, дастурамали <a href="https://navar-abyari.ir/mikdori-tukhmi-havyz-dar-yek-ghektar-rohnamoi-purra/">Миқдори бӯгоҳи шӯбидан дар як ҳектар</a> меонамояндиши хубе аз тағйирёбандаҳои монанд пеш бароварда метавонад.</li>\n    <li><strong>Вақтбандии обӣ:</strong> Дар марҳилаҳои аввали таҷдид, обии пайдарпай ва бо ҳарорати паст тавсия дода мешавад. Ҳангои афзоиши обӣ, ҳароратро баланд бардоред, вале ин тӯро нигоҳ доред, то намӣ ба баргҳо нарасад. Ин кор ба пешгирии шӯршавии сатҳӣ ва нигоҳдошти солимӣ меъёри обӣ мусоидат мекунад.</li>\n    <li><strong>Мудохилаи ҳаят:</strong> Ҳаятҳои нитроген дорон бояд дар наздикии навбати обӣ гузошта шаванд, то бо об ба решаҳо расанд. Ин усул аз парсидан ва заюбӣ ҳаят пешгирӣ мекунад ва аз худкунӣ то 30% зиёд мекунад. Истифодаи ҳаятҳои тухмӣ дар вақти муносиб низ яке аз нуқтаҳои муҳим аст.</li>\n</ol>\n\n<h3>Мушкилоти оддӣ ва роҳҳои ҳалли онҳо</h3>\n<ul>\n    <li><strong>Кур шудани қурубандҳо:</strong> Канолға ҳеҷ гуна ҳассосияте ба бактерияҳои об надорад, аммо кӯбкории об метавонад сиҳро хурад. Истифодаи филтри мувофиқ ва шустушуви мунтазамӣ сиҳар маҷбур аст. Инчунин, назорати фишори сиҳар дар фосилаҳои кӯтоҳтар тавсия дода мешавад.</li>\n    <li><strong>Рушди алафҳо дар байни нӯрҳо:</strong> Азбаски танҳо қатори тип ниҳон аст, одафҳо дар қисмҳои хушк қуштад мебошанд. Агар зарурӣ бошад, аз одафкузҳои дар об ҳалшаванда истифода баред, ки назди қурубандҳо истифода мешаванд. Ин кор боиси камшавии моеъ дар сиҳар мебошад.</li>\n    <li><strong>Ҷойи беҳтарин барои ҳосилдорӣ:</strong> Вақти ҳосилкунии канаға муҳим аст. Гарчанде шумо метавонед нишонҳоеро дар бораи ҳосилкунии умумӣ дар дастурро <a href="https://navar-abyari.ir/basil-harvest-yield-per-hectare-guide/">Миқдори ҳосили хургуни дар ҳектар</a> машҳуд кунед (гарчанде фарқияти одафҳоро, принсипҳои монандии намии монанд аст), барои каногҳ, вақте ки дунҳо ранги худро тағйир медиҳанд ва заръ мешаванд ва пӯсти хушк мешавад, вақти беҳтарин барои ҳосилкунист. Дар ин марҳила, намии дунҳо камтар аз 10 фоис мешавад.</li>\n</ul>\n\n<h2>Саволҳои маъмул (FAQ) дар бораи ҳосили арчим (canola) бо намуни абкории қаторӣ</h2>\n\n<h3>1. Оё абкори қаторӣ барои хокҳои шағолӣ мувофиқ аст?</h3>\n<p>Бале, вале ба абкори бештар лозим дорад. Дар хокҳои шағолӣ қобилияти нигоҳ доштани об камтар аст, бинобар ин бояд даврӣ абкорӣ карданро кӯтоҳ кард ва суръати ҷараёни обро танзим намуд, то об пеш аз бухоршудан аз сатҳ ба чуқурӣ дохил шавад. Инчунин, истифодаи пардохти растаниҳо дар ин хокҳо метавонад дар нигоҳ доштани намӣ кӯмак расонад.</p>\n\n<h3>2. Чӣ қадар афзоиши ҳосилро эҳтимол кардан мумкин аст?</h3>\n<p>Вобаста ба минтақа ва муқоиса бо абкори тағозун (ғарқобӣ), афзоиши 15 то 25 фоизӣ дар <strong>миqdори ҳосили арчим (canola) дар гектар</strong> маълуб шудааст. Ин афзоиш бештар ба сабаби коҳиши стресси об дар марҳилаи пур шудани дон аст. Барои фаҳмидани тағйирёбандаҳое, ки ба ҳосил таъсир мерасонанд, шумо метавонед ба мақолаи <a href="https://navar-abyari.ir/pumpkin-seed-per-hectare-factors/">Мiqдори бодаби (тобба)</a> Тавассути инчунин оморишавии мутабири барои санҷиши омилҳои монанди об ва хок нигаред. Инчунин, сифати тоҷиб ва навъи асрӯҳ мустақимона ба ин рақамҳо таъсир мерасонанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-کلزا-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت کلزا در هکتار با نوار تیپ - تصویر 2"/><figcaption>Ҳосили ҳазортоқон дар гектар бо усули ороиши ҳазортоқонӣ (drip irrigation) кала (canola)</figcaption></figure>\n\n\n<h3>3. Сарфамиёнаи иловагии тасмаи иловагӣ (нип-тип) барои кала чанд аст?</h3>\n<p>Сарфамони нисбат ба нархҳои рӯзонаи бозор орофта мешавад ва ба омилҳо монанди масофаи хазортоқонҳо, навъи лӯла ва ғадирии тасмаи ғазлӣ вобаста аст. Ҳамин тавр тавсия дода мешавад, ки пеш аз харидан, сарфамони парвариш ва умри фаъоли асбобҳоро ҳисоб кунед. Дар даромадҳои дарозмуддат, парҳезкунӣ дар об ва зиёд будани ҳосил бозгашти сармояро таъмин мекунад. Сармоягузории ибтидоӣ, гарчанде, наздик ба муваззифа аст, вале бо назардошти баланд будани самаранокии об, эҳтиром ба иқтисод дорад.</p>\n\n<h2>Хулоса</h2>\n<p>Истифодаи системаи ороиши тасмаи иловагӣ (нип-тип) сармоягузории хушҳатҳо барои баланд бардоштани устувори... <strong>Ҳосили ҳазортоқони кала дар гектар</strong> аст. Бо назардошти камбудии об ва тағйиротҳои иқлими, ин усул ба кишовар имкон медиҳад, ки бо истеҳмолкунии бештарин ҳаҷми об, баландтарин самаранокии роғно аз тоҷиби худ ба даст овард. Калиди муваффақ дар тарҳрезии ибтидоӣ, танзими дақиқи масофаи тасмаҳо ва назорати доимии саломатии системаи ороиш мебошад. Риояи асосҳои ғазлӣ бо зичии мувофиқ ва идоракунии маводи тароқот дар атрофи ин система метавонад тағйироти бунёдиро дар сифат ва миқдори маҳсули ниҳоӣ ба вуҷуд орад. Тавсия дода мешавад, ки таҷрибаи муваффақи дигар кӯмакшудагони роғно ҳамчун намунаи техникии истифода баред, то аз хатогиҳо парҳез кунед ва ба баландтарин самараноки расед. Дар охир, баррасии нуқтаҳои асосӣ ва муроҷиат ба манбаъҳои алоқаманд дарки бештар барои дини миёни кишоварзии муосирро таъмин мекунад. Ин манбаъҳо мушаххасотҳо дар бораи кӯмакшудагони хурма, гавор ва тарбоки қаймоқӣ мебошанд, ки асосҳои муштараки ороишро шарҳ медиҳанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-کلزا-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت کلزا در هکتار با نوار تیپ - تصویر 3"/><figcaption>саривури ҳосил зарра аз як гектар бо оқимчии поёндарӣ (риширӣ) для канопсы</figcaption></figure>\n\n<p><strong>Маводи вобаста:</strong> Микдори тоҷри нусаз дар як гектар бо нақши ленти</p>\n<p><strong>Маводи вобаста:</strong> <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B2%DB%8C%D8%B1%D9%87-%D8%B3%D8%A8%D8%B2-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Микдори тоҷри зунбудин дар як гектар</a></p>','Даромади кӯкча дар як гектар бо системаи нақли абшор: Раҳнамои пурра барои баланд бардоштани ҳосил','Колза яке аз муҳимтарин растанҳои равғанӣ дар Эрон мебошад. Истифодаи обёрӣ тавассути намунаи дукна метавонад таъсири зиёдро ба самаранокии об ва дар натиҷа ба ҳосили ҳар гектар колза расонад. Дар ин мақола мо роҳҳои амалӣ ва илмӣ барои расидан ба баландтарин ҳосилро баррасӣ мекунем.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
