SET @resolved_slug=IF(@slug_conflict IS NULL,'toali-anchassi-parvarishi-paxta-nta-npk-hektor-tajik','toali-anchassi-parvarishi-paxta-nta-npk-hektor-tajik-crop-153-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'toali-anchassi-parvarishi-paxta-nta-npk-hektor-tajik-crop-153-tj-18d9425c');
