SET @resolved_slug=IF(@slug_conflict IS NULL,'miqdori-toji-margib-dar-1-hektar-roihnamai-kamil-baroi-kosh-tarobi-koshish','miqdori-toji-margib-dar-1-hektar-roihnamai-kamil-baroi-kosh-tarobi-koshish-crop-156-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'miqdori-toji-margib-dar-1-hektar-roihnamai-kamil-baroi-kosh-tarobi-koshish-crop-156-tj-f1699214');
