START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-162' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-162:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='fosalu-bayni-gharafhoni-naqqodh-dar-kishtubori-yaguz-sabzavot' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'fosalu-bayni-gharafhoni-naqqodh-dar-kishtubori-yaguz-sabzavot','fosalu-bayni-gharafhoni-naqqodh-dar-kishtubori-yaguz-sabzavot-crop-162-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fosalu-bayni-gharafhoni-naqqodh-dar-kishtubori-yaguz-sabzavot-crop-162-tj-1ba26c2b');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддама дар бораи аҳамияти тартиби пайпҳо дар парвариши сабзӣ</h2><p>Интихоб <strong>Фосилаи пайпҳо дар парвариши сабзӣ</strong> Ин на танҳо сохтори содда аст, балки як қарори муҳendisӣ-кишоварӣ мебошад, ки бевосита ба хароҷоти ниҳоӣ, тақсимоти баробарии namӣ ва дар натиҷа сифати маҳсулоти ниҳоӣ таъсир мерасонад. Сабзӣҳо аз сабаби рушди тезӣ решаҳо ва ҳассосии баланд ба камбудии маҳаллии об ба як тартиби дақиқи қатраӣ ниёз доранд. Ин тартиби дақиқ решаҳои фаъоли наботро пайваста дар минтаҷаи намнок нигоҳ медорад ва аз шиддати обӣ дар давраҳои муҳими рушд пешгирӣ мекунад. Дар деҳқонӣҳои тиҷоратӣ, ҳатто инҳирофи хурд аз меъёрҳои фосилаҳо метавонад боиси тақсимоти нобаробари моддаҳои ғизоӣ ва коҳиши вазн ва андозаи меваҳо баргонанд. Бинобар ин, фаҳмиши дуруст динамикеи гидравликӣ ва алоқаи он бо намуди хок ва намуди парвариш шартҳои асосӣ барои ҷорӣ намудани муваффақи системаи оборӣ мебошад.</p><p>Усули меъёрӣ истифодаи лӯлаҳои полиетилен (ПЭ) бо қалиноии гуногун 15, 20 ё 25 мм мебошад. Ин лӯлаҳо бояд дақиқ дар минтаҷаи решаҳои фаъол ҷойгир карда шаванд, то ки таъмин карда шавад, ки об аз сарфи нодароми ҳосил дар хок пешгирӣ мекунад. Дар ин қисм, мо принсипҳои асосии тартибро мӯрӣ мекунем ва дар идома тафсилоти техникӣ таҳлил хоҳем кард. Инчунин бояд диққат диҳед, ки ҷойгиркунии дурусти пайпҳо алоқаи мустақим бо намуди паҳншавии қатраҳо (паҳншавии якҷихона ё дуҷихона) дорад, ки дар қисмҳои оянда ба он мепардозем.</p><p></p><h2>Принсипҳои фосилаи пайпҳо вобаста ба намуди сабзӣ</h2><p>Ҳамаи сабзӣҳо яксон нестанд; бинобар ин, фосила байни ду пайпҳои обдиҳанда низ яксон нест. Муайян кардани фосилаи мувофиқ тоифаи генотипи набот ва чуқурии тоҷи решаҳо дарк аст. Дар ҳолати умумӣ, ду сценарии асосӣ вуҷуд доранд: парвариши сабзӣҳои рушдишаванда (масалан, шпинат ва каду) ва парвариши сабзӣҳои мевадор (масалан, калра ва каду). Ҳар кадоме аз ин гурӯҳҳо физиологияи гуногун доранд, ки бояд дар ҳисоб кардани фосилаи пайпҳо ба назар гиред.</p><h3>Таъсири геомотрияи ҷисми растани ба чуқурии кӯлаки реша</h3><p>Барои сабзоти монанди <strong>қаламфури қандӣ</strong> ё помидор, ки системаи решаи чуқуру паҳншударро доранд, масофаи байни сафҳо одатан ба 60 то 70 сантиметр наздик гирифта мешавад, то ки пӯшиши пурраи решаҳо амалӣ шавад. Аз тарафи дигар, барои сабзоти монанди салат ё шпинат, ки решаҳои ҷодӣ ва зичтар доранд, масофаи 40 то 50 сантиметр оптималӣ мебошад. Агар масофа хеле зиёд бошад, қисмҳои марказии байни ду саф хушк мемонанд ва растани маҷбур мешавад, ки энергияро барои ҷустуҷӯи об сарф кунад. Баръакс, агар хеле наздик бошанд, талафот ва фасод аз рутубати баланди муҳити реша зиёд мешавад ва хатари бемориҳои занбадашӣ баланд мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-سبزی-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت سبزی: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop сабзот</figcaption></figure>\n<p>Барои шиносӣ бо стандартҳои дақиқтар, шумо метавонед ба мақола <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%81%d9%84%d9%81%d9%84-%d8%af%d9%84%d9%85%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Дараҷаи даромади қаламфури қандӣ дар як гектар</a> ва <a href="https://navar-abyari.ir/tomato-seeds-per-hectare-guide/">Далели шумораи бехи томат дар як гектар</a> Ба ин мақолаҳо муроҷиат кунед, ки дар онҳо тарҳи ғирпандӣ ва дигаргуниҳои он бо метrażи навбати тип ба таври пурра баррасӣ шудаанд. Ин мақолаҳо маълумоти муфассал дар бораи решаҳои ҳар растаниро барои ҳисобкирии дақиқтар масофаи навбатуҳо пешниҳод мекунанд.</p><h3>Таъсири қадри хок ба нфузи дигаргунӣ</h3><p>Қадри хок (савол, силитӣ ё рӯбарғӣ) ба радиуси нфузи об аз лӯлаҳо таъсир мерасонад. Дар хокҳои ҷисмики риздигар, радиуси нфузи кӯтоҳтар аст ва лозимоти кам кардани масофаи навбатуҳо мавҷуд аст. Аз дигар самта, дар хокҳои гилӣ, об аҳтарнфуз мекунад ва мумкин аст масофаро каме зиёд кард, то аз шубъаи номатлуби реша пешгирӣ шавад. Баррасии дақиқ қадри хок пеш аз харидани лӯлаҳо, зарур аст, то аз нифузи паҳлуӣ пешгирӣ шавад. Моавзоти нақши хок дар кори системаҳои қатрагиӣ дар мақола <a href="https://navar-abyari.ir/ahamiyati-bozinsii-zamin-baroi-navori-tip-va-nayii-poli/">Муҳимии қадри хок барои навбати тип</a> Ба таври муфассал шарҳ дода шудааст.</p><p></p><h2>Ҳисобҳои амалӣ ва интихоби андозаи лӯла (ғабиши давар)</h2><p>Пас аз муайян кардани масофаҳои тӯлӣ, бояд ғабиши лӯларо (чукури давар) ҳисоб кард. Лӯлаҳои 15-миллиметрӣ одатан барои сабзавотҳои риз ва миёна тавсия дода мешаванд, зеро фишори дохилӣ паст доранд ва ҷараёни якхела эҷод мекунанд. Агар масофаи навбатуҳо дар тӯли канал зиёд бошад, барои пешгирӣ аз паст шудани фишор дар охири лӯла, лӯлаҳои 20 ё 25-миллиметрӣ истифода мешаванд. Аммо нуқтаи калидӣ, он аст, ки ғабиши зиёдатии лӯла боиси зиёд шудани хараҷ ва кам шудани чабкии система мегардад. Инчунин, интихоби ғабиши дурусти лӯла ба таври мустақим ба шустани дохили лӯла дар охири ҳар давроби обёрӣ таъсир мерасонад; лӯлаҳои нозктар дар сурати шустани муносиб набудан, имконияти оғоз шудани афкор доранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-سبزی-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت سبزی: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>Фазолиданиши бастани, тарҳи ҷойгиршавии сатрҳо, чистаб</figcaption></figure>\n<ul><li><strong>Лӯлаи 15 миллиметр:</strong> Мувофиқ барои фосилаҳои зер 15 метр ва сабзавоти хурду зич.</li><li><strong>Лӯлаи 20 миллиметр:</strong> Интихоби маъмултарин барои кишвари саноатии сабзавот бо фосилаи 30 то 45 метр.</li><li><strong>Лӯлаи 25 миллиметр:</strong> Барои кишварҳое, ки масоҳати дароз доранд ва шуби паст доранд, ки ба устувии баландтари фишор ниёз доранд.</li></ul><p>Дақиқият дар ҳисобкунии миқдори оби зарурӣ барои ҳар гектар калиди муваффақият аст. Барои шиносӣ аз <a href="https://navar-abyari.ir/miqdori-obdihiyi-novori-tipii-baroi-obeyri/">Ҳаҷми обдиҳии лентанави тип</a> Бо истинод ба сари баромади ҳар як қатра метавонед аз ҷадвалҳои стандартӣ истифода баред. Интихоби диаметри дохилии мувофиқ ба нахеи ниҳоии лӯлаҳо барои ҳар гектар таъсир мерасонад; роҳнамои <a href="https://navar-abyari.ir/navor-i-tip-baroi-yek-gektar-chi-qadar/">Нархи лентанави тип дар як гектар</a> метавонад кӯмак кунад, то бюджети дақиқтар дошта бошед ва аз хариди лӯлаҳои зиёд, ки боиси хароҷоти пинҳонӣ мегардад, хаш кунед.</p><h3>Таъсири шабистаки замин ба насби лента</h3><p>Дар минтақаҳое, ки шабистаки замин доранд, фосилаи лентанави тип бояд бо ҳарозии бештар ҳисоб карда шавад. Шабистак боиси ҷамъ шудани об дар нӯҳҳои поёнӣ ва ками таррӣ дар сархӯрҳо мегардад. Дар шартҳои чунин, истифодаи лӯлаҳои ғафстар ва коҳиши фосилаи лентанавҳо метавонад муин кунад. Инчунин, интихоби лӯлаи аз плииетилен сохташуда, ки ба пӯсидагӣ муқобилат дорад, муҳим аст. Мавзӯи пӯсишпазири лентанави тип ва меъёрҳои истеҳсоли он низ барои ба даст овардани фишори собита дар тамоми дарозии лӯлаҳо ҳаётӣ аст. Дар шабистакҳои тунд, ҳатто фарқияти як метр дар баландӣ метавонад боиси фарқияти чанд баробари сарро дар қатраҳои аввал ва охир гардад, ки ба танзиби дақиқи система ниёз дорад.</p><p></p><h2>Саволҳои муҳокамашуда (FAQ)</h2><h3>Фосилаи байни лентанавҳо дар ғунти салот чӣ қадар бояд бошад?</h3><p>Бо назардошти решаҳои кӯтоҳи каду, одатан масораи 40 то 50 сантиметр тавсия дода мешавад. Азбаски 15 миллиметрӣ истифода шудааст, тағйирдиҳии ин масора метавонад ба рушди нобаробари дони бошад. Баста ба нақшаи ҷойгиршавии қаторҳои партоби, ин масора метавонад ба вазъияти барориши бодоргонҳо таъсир кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-سبزی-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت سبزی: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>масораи қаторӣ барои системаи сипкандӣ (drip tape) барои сабзавотҳо</figcaption></figure>\n<h3>Оё имкон дорад, ки лентаи сипкандӣ (drip tape)-ро дар тарафи дутои қатор ҷойгир кунем?</h3><p>Бале, ин усул (дунахӯни) дар сабзавотҳо чун бодор, хурукӣ (drip) ва сипакҳо (drip tape) ҷо дорад. Масораи байни ду навар (drip tape) набояд камтар аз 60 сантиметр бошад, то партоби ғизоҳо ва бемориҳои қашқошӣ коҳиш ёбанд. Дар ин чизбурӣ (layout), даракни бин насорҳои наварӣ (drip tape) хеле муҳим аст, то аз ба вуҷуд овардани нуқтаҳои хушк дар марказ пешгирӣ шавад.</p><h3>Таъсири таҳти баланд бар масораи навар (drip tape) чӣ гуна аст?</h3><p>Дар таҳти зиёдтар аз 15%, зарур аст, ки масораи наварҳо (drip tape) коҳиш дода шуда, қабатии лӯлаи (drip tape) зиёд гардад, то аз афтиши фишор дар сатҳи поёнӣ пешгирӣ шавад. Бигзор, фишори таҳтиро (filtration) баланд бардоред, то ки зарардиҳии наварҳо (drip tape) дар минтақаи таҳти коҳиш ёбад. Истифодаи вазелин (waseline) ё часпони махсус барои пешгирии тағйиршавии наварҳо (drip tape) дар таҳти тавсия дода мешавад.</p><h3>Кайҳо навариро (drip tape) тағйир додан лозим аст?</h3><p>Наварҳо (drip tape) одатан ду фаслаҳа (4 то 5 моҳ) ҳастанд. Агар пурракии лӯлаи (drip tape) бошад ва сӯрохҳои сипкандӣ (drip tape) баста шуда ё ғайри муқаррарӣ шавад, онҳоро тағйир додан лозим аст. Таҳияи наварҳои (drip tape) қадимӣ, одатан самараноро ба таври назаррас коҳиш медиҳад.</p><h2>Хулоса</h2><p>Муайянкуна <strong>Масофаи лентаҳо дар парвариши сабзӣ</strong> Ин раванди фаъолона аст, ки мустақиман ба генотиҳи растаниҳо, намуди хок ва ғунҷоиши замин алоқаманд аст. Барои парваришҳои хурд, масофаҳои камтар ва ҷангонҳои нозуктар мувофиқтаранд, ҳангозе барои сабзӣҳои баландтар ва рӯйи амиқ, масофаҳои стандартии 50 то 70 сантиметрӣ бо ҷангонҳои 20 миллиметрӣ бештар истифода мешаванд. Ҳамیشа пеш аз кашидани лентаҳо, як қисми 10-метрӣро насб карда, мувоқифати обро дар хок санҷед. Ин корҳои хурд метавонанд аз беҳдошти захираҳо ва кам шудани ҳосилнокии умумии деҳа пешгирӣ кунанд. Дар охир, нигоҳубуни мувофиқи ҷангонҳо ва истифодаи филтрҳои мувофиқ, ду пойгоҳи дурӯзаи системаи понакиӣ дар парвариши сабзӣ мебошанд.</p>','Фосилу байни ғарафҳои наққоди дар киштубории яғузу сабзавот: стандардҳои тавсияшуда','Муайяни масофаи банди чанго дар кунуни сабзӣ як нишондиҳандаи муҳими барқарор кардани хароҷот ва афзундакунии самаранокӣ мебошад. Дар ин мақола ба таҳлил кардани усулҳои ҷойгир кардани қатрагӣ ва ҷадвали масофаҳо вобаста ба навъи сабзӣ дастрасӣ шуд.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
