SET @resolved_slug=IF(@slug_conflict IS NULL,'fawwaai-nawari-tip-dar-karibkorii-mosh-standardii-tavsiyashuda','fawwaai-nawari-tip-dar-karibkorii-mosh-standardii-tavsiyashuda-crop-163-tj');
