SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='drip-line-maintenance-chickpea-cultivation' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'drip-line-maintenance-chickpea-cultivation','drip-line-maintenance-chickpea-cultivation-crop-164-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'drip-line-maintenance-chickpea-cultivation-crop-164-en-2978d506');
