SET @resolved_slug=IF(@slug_conflict IS NULL,'nioghubinoo-tip-kushoti-nuhud-oboriy-qatraviy','nioghubinoo-tip-kushoti-nuhud-oboriy-qatraviy-crop-164-tj');
