SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='seeding-rate-colorful-flower-group-hectare' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'seeding-rate-colorful-flower-group-hectare','seeding-rate-colorful-flower-group-hectare-crop-178-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
