SET @resolved_slug=IF(@slug_conflict IS NULL,'trapezoidal-canal-spacing-melon-cultivation-standards','trapezoidal-canal-spacing-melon-cultivation-standards-crop-181-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
