START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-188' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-188:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='kompyot-sohbomai-pishukish-o-poyom-ba-maydoni' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'kompyot-sohbomai-pishukish-o-poyom-ba-maydoni','kompyot-sohbomai-pishukish-o-poyom-ba-maydoni-crop-188-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'kompyot-sohbomai-pishukish-o-poyom-ba-maydoni-crop-188-tj-408ec089');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада: Аҳиями обёрии идорашаванда дар истеҳсоми хурбош</h2><p>Хурбош яке аз ҳосилҳои ҳассос ба об аст, ки рӯйшт ва сифати он бевосита ба усули идоракунии манбаъҳои об вобаста аст. Дар анъанаҳои классикии кишоварӣ одатан аз обёрӣи ғарқобӣ истифода мекарданд, ки на танҳо ба хароҷоти бузургтарин манбаъ, яъне об оварда расонд, балки ба фурӯ шудани реша ва кам шудани самаранокии қанотҳо саббта кард. Имоқома бо донистани фоидаҳои обёрӣи нӯри типӣ, деҳқонон ҷустуҷӯи усулҳои дақиқтари монанди қатраобёрӣ мекунанд, ки имконияти идорашавидани миқдори об ва ғизои набототро фароҳам меорад. Ин усулҳо бо дақиқати баланд дар тақсимотинамудан, стрессро аз об ба ҳадди ақал мерасонанд ва боиси истеҳсоми мевае мебошад, ки аз ҷиҳати шакл ва талғам якхела аст. Илова бар ин, кам шудани бухоршавӣ ва ҷалби об дар хокҳои сабук, боз як афзалияти дигаре аст, ки обёрӣи қатрагӣ дар шароити иқлими хушк эҷод мекунад.</p><p>Ҳадафи ин дастур пешниҳоди як роҳи амалиётӣ барои карботани хурбош мебошад, ки дар он принсипҳои обёрӣи қатрагӣ дар тақсимоти намеҳои наботот, танзими фишори система ва барориши дарҷаи обёрӣ дохил шудааст. Бо иҷрои дурусти ин марҳилаҳо, интизор меравад, ки ғайр аз сарфишиёнии истифодаи об, якхелагии андоза ва талғами хурбош низ зиёд шавад. Илова бар ин, дар ин бахс ба баррасии вобастагии мустақим миёни дубори об ва миқдори ширинии мева менависем, ки барои деҳқонон муҳим аст.</p><br><h2>Интихоби усули мувофиқи карботан барои хурбош</h2><p>Барои истифодаи системаи обори қатрагӣ, усули кӯршудан бояд бо имкониятҳои техникии ғадакҳои типӣ мувофиқ бошад. Хуруби одатан дар дохили ғадак ё дар паси ғадак (манзили кӯршудан рӯи бӯдак) кӯр мешавад. Дар усули паси ғадак, растанӣ рӯи бӯдак ё бӯдаки хушк ҷойгир карда мешавад ва ғадаки обирӣ дақиқан дар наздикии решаҳои асосии растанӣ насб карда мешавад. Ин ҷойгиршавӣ боиси он мегардад, ки намнокиҳо ба минтақаи решаҳои хурди фаъол мустақиман мерасанд ва ҷабби моддаҳои ғизоӣ беҳтарин мешавад. Интихоби дурусти манзили кӯршудан қадами аввал дар коҳиши хароҷоти энергӣ ва зиёд кардани самаранокии система аст.</p><ul><li><strong>Усули кӯршудан дар дохили ғадак:</strong> Барои системаҳои лӯлавӣ бо диаметри калонтар мувофиқ аст, аммо дар хуруби, ғадакҳои типи сабуктар, ки мустақиман дар наздикии плети кӯршудан ҷойгир мешаванд, самаранокии бештар доранд ва насб кардани онҳо соддатар аст.</li><li><strong>Фасоли байни сатҳҳо ва дохили сатҳҳо:</strong> Фасоли стандартӣ барои хуруби одатан 100 то 120 сантиметр дар дохили сатҳ ва 160 то 180 сантиметр байни сатҳҳо аст. Ин фосилаҳо решаҳоро имкон медиҳад, ки паҳн шаванд ва ба ғадаки типӣ имкон медиҳад, ки минтаҳаи мувофиқи намнокроҳоро ба вуҷуд орад ва аз рақобати растанӣ барои манбаъҳо пешгирӣ мекунад.</li></ul><p>Дар вақти интихоби ғадакҳо, боварӣ ҳосил кунед, ки тақсимoti ғадакҳои замин пеш аз кӯршудан суръат дода шавад, то ки намнокории ибтидоии решаҳо иҷро шавад. Ишора ба <a href="https://navar-abyari.ir/%d9%85%d8%b4%d8%ae%d8%b5%d8%a7%d8%aa-%d9%81%d9%86%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c/" target="_blank" rel="noopener">Хусусиятҳои техникии ғадаки типи обирӣ</a> Дар муайян кардани диаметри ва фосилаи сӯронҳои ғадак муҳим аст, то об бо тарзи баробар дар тӯли сатҳ тақсим шавад ва аз ҷамъ шудани об дар ҷойҳои муайяни ғадак пешгирӣ карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-خربزه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت خربزه با آبیاری قطره‌ای - تصویر 1"/><figcaption>Usul-i karsazī, barodohi chashma, tarza-i obgiri, jadvali obgiri-kunī, zarbā</figcaption></figure>\n<br><h2>Jadvali obgiri-kunī (Jadvali obgiri) baroi zarbā</h2><p>Zarbā dar paydari vāsi-i pūshūm, ohtoriji obgi-jozi dori. Jadvali obgiri-kunī-jo kufi boroas shorot-o havai, noobi khakori va poyada-jo pūshūm tayyī shavad. Fahmi dūsi-i in poyadari-jo tarofon zaro-jozi, kalidi muvaffaqiat dar kashti zarbā boro sistemi chashma-o ast. Taghīri dabbī va muddati obgiri boi guzashtani zamoni, azī charkūgi mūstazil berūnam shuda boi amali pūyā konad.</p><ol><li><strong>Poyada-jo nūsha-o va barakatī rūshi (az riyati 1 to 4 haftavi):</strong> Dar in poyada, ohtoriji obgi kamo ast. Obgiri-kunijoi kūtuh-o va mardud (har 2 to 3 ruz) baroi monevati khushk shudanī khakori rūshidār mūstahsil shuda. Miqdori obgi kumo (taqrīban 2 to 3 litre dar soati baroi har nabo) kifoyi ast. Rūshi dar in daīri boisatī nāziku ast va khushki kumori sababi inqirozi pūshūmi nūshau shavad.</li><li><strong>Poyada-jo pūshūmi boya-o va sanga (az riyati 5 to 8 haftavi):</strong> Boi afzūshī ohtorijoi saboh, ohtoriji obgi afzūshī mūyād. Daivori obgiri-kunī be tartibi 3 to 5 ruz dar haftavi taghīrī mūyād va mudдати obgiri be tartibi 20 to 30 daqiqa afzūshī mūyād. Nabo dar in poyadai sur\'ati pūshūmi boi dārad va ba mūstahil shoidanī obgi oho nabo bado boi taghīrī kunod, toki pūshūmi munassibi dāshta boad.</li><li><strong>Poyada-jo gulzori-o va tashkuli miūho (avji pūshūm):</strong> Ин марҳила ҳассастарин аст. Ноқсоии об боиси шакли нодурусти мева ва коҳиши бадбӯӣ мешавад. Обкорӣ бояд мунтазам ва бо сарраши доимӣ анҷом шавад. Одатан ҳар 2 то 3 рӯз, дар муддати 30 то 45 дақиқа. Нӯсонишҳои шикорӣ дар ин марҳила метавонанд ба шикастани пӯсти турпӣ оварда расонанд, бинобар ин устувории обкорӣ аҳамияти аввалин дорад.</li><li><strong>Марҳилаи пухидан ва ҳосилкорӣ (2 ҳафтаи охир):</strong> Коҳиши тадриҷии обкорӣ барои зиёд кардани консентратсияи қанд ва бадбӯии турпӣ зарур аст. Обкорӣ 2 рӯз пеш аз ҳосилкорӣ қатъ мешавад, то хушбӯӣ ва бадбӯии мева ба ҳадди охир расад. Ин кор ҳамчун стресс физиологӣи сабук амал мекунад ва ширинии меvaro зиёд мекунад.</li></ol><p>Барои беҳтар кардани ин барнома, самаранокии системаи нӯрҳои капиллярӣ муҳим аст. Таҳқиқоти мақолаи чӣ гуна самаранокӣ ва бешқувватии наварҳои тибӣ-ро зиёд кардан метавонад ба пешгирии хашури наварҳо, нигоҳ доштани сарраши якгона дар тамоми давраҳои сатр ва ҳисоб кардани сарфи манбаҳо кӯмак расонад.</p><h2>Нуктаҳои амалии насб ва нигоҳдории система</h2><p>Насб кардани наварҳои тибӣ дар парашҳои турпӣ нуқти нозук дорад, ки дар сурати диққат нашудан, ба хатогиҳо дар обкорӣ ва коҳиши ҳосил меояд. Риояти ин масъалаҳо умри кории таҷҳизотро зиёд мекунад ва аз нуқсонҳои маъмули система пешгирӣ менамояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-خربزه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت خربزه با آبیاری قطره‌ای - تصویر 2"/><figcaption>planting methods drip crop irrigation schedule турпӣ</figcaption></figure>\n<ul><li><strong>Фишори кори мувофиқ:</strong> Системаҳои хурбоза одатан бо фишори 1 то 1.5 бар кор мекунанд. Фишори зиёд ба пардидани ришта ё хориши номуназми об оварда мерасонад. Ба дастурав} <a href="https://navar-abyari.ir/%d8%a7%d9%86%d8%af%d8%a7%d8%b2%d9%87%da%af%db%8c%d8%b1%db%8c-%d9%81%d8%b4%d8%a7%d8%b1-%d8%a2%d8%a8-%d8%a8%d8%b1%d8%a7%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be/" target="_blank" rel="noopener">Андозагирӣ фишори об барои риштаи drip</a> Барои танзими куллони фишорӣ система зарур аст, то баромади фишорӣ дар ҳудуди бехатар будани ришта боқӣ мондааст.</li><li><strong>Пӯшиши пудрҳои ҳифозакунанда:</strong> Ҳангоми ниҳол гузоштан, ҷойро ки ришта мегузарад аз дасти ҳашароти хокӣ (масалан, кӯлаҳои хокӣ) ҳифоз кунед. Истифодаи риштаҳои сифатнок ва ба нурҳои UV муқовиматнок, калиди ором будан дар фасл ва кам шудани вайронии мӯлозимот аст.</li><li><strong>Хамӯшшавии риштаҳо:</strong> Дар ҳолати истифодаи ду ришта дар ҳар як қатор, риштаҳо набояд болои якдигар афтоданд. Масофаи мувофиқ барои эҷоди пӯшиш намдори якҷо дар хок тавсия дода мешавад, то рӯягонҳо аз ҳарду тараф ғизо пайдо кунанд.</li></ul><br><h2>Ҷавоб ба саволҳои маъмулӣ (FAQ)</h2><h3>Оё барои парвардани хурмӯса аз системаи оборишавӣ (обрӣ) истифода кардан мумкин аст?</h3><p>Бале, системаи оборишавии қатрагӣ ё омехтаи нӯрагӣ ва шӯрӣ метавонад барои хурмӯса истифода шавад. Ин усул махсусан дар заминҳои бо насобкунии суст муфид аст. Бо илова кардани ду нӯраи дигар ба шӯри асосӣ, метавон дар ҳамзамон оборӣ ва тағзия (фудишт) -ро иҷро кард. Ин кор ба зиёд шудани ҷазби моддаҳои ғизоӣ тавассути решаҳои хурмӯса мусоидат мекунад ва ниёз ба заҳарпуркунии сатҳии заминро кам мекунад.</p><h3>Агар нӯра илгал гирад, бояд чӣ кор кард?</h3><p>Илгалии нӯраи тайп мушкили муҳаммал аст. Агар аз нӯраҳои шустаншаванда (Back-flushing) истифода мебаред, бо кушодани шири баромадӣ, шустани баръаксро иҷро кунед. Ба ғайр аз ин, бояд нӯраҳоро иваз кард. Пешгирӣ тавассути истифодаи филтрҳои муносиб (мисли филтри тобида ё дискӣ) бисёр самараноктар аст ва маљимони таъмириро ба таври ҷиддӣ кам мекунад.</p><h3>Оё хурмӯса ба оби хунук ё гарм ҳассос аст?</h3><p>Даромад дар худи неволхурмӯса бисёр таъсир надорад, вале ҳарорати замин хеле муҳим аст. Оборӣ бо оби хеле хунук метавонад дар замини заиф шӯки решаҳоро ба вуҷуд орад. Бинобар ин, тавсия дода мешавад, ки оборӣ дар соатҳои хунуктари рӯз иҷро карда шавад, то буғшавӣ кам шавад ва намии решаҳо нигоҳ дошта шавад ва аз сӯхтани баргҳо дар ҳавои гарм пешгирӣ гардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-خربزه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت خربزه با آبیاری قطره‌ای - تصویر 3"/><figcaption>planting methods drip crop irrigation schedule хурмӯса</figcaption></figure>\n<h2>Хулоса</h2><p>Кӯмак кардан бо ороиши наққорӣ на танҳо як пешрафти техникӣ, балки як зарурати иқтисодӣ барои деҳқонони имрӯза аст. Бо риояи принсипҳои кӯмак кардан дар кандаи мувофиқ, риояи барномаи дақиқи ороиш ва нигоҳубини мунтазами ришавҳои тип, метавон ба кандаҳои пурбос ва кӯмакҳои сифатнок бо лютзи кӯмак даст ёфт. Тавсия мешавад, ки барои маълумот бештар дар бораи маҳсулоти монанд, <a href="https://navar-abyari.ir/vegetable-yield-per-hectare-guide/" target="_blank" rel="noopener">рамзори истифодаи сабзоти боғдорӣ дар гектар</a> ро таҳқиқ кунед, то таъсири ороиш ва кандаи ниҳоӣ хуб муайян шавад ва фаҳмиши беҳтари иқтисодии кӯмак кардан дастёб шавад.</p>\n<p><strong>маҳсулоти алоқаманд:</strong> <a href="https://navar-abyari.ir/90mm-plastic-pipe-irrigation-guide/">90mm plastic pipe irrigation guide</a>ҳаҷми гулдани хушмез дар гектар: омилҳои таъсиргузор ва усулҳои зиёд кардан</p>','Kompylot soʻhobnomai pichikish va poʻyom ba maydoni','Оямогирии принсипҳои кунд кардани арбуз дар ҷониби системаи обёрӣи қатрагӣ метавонад ҳосилро ва сифати ҳосилро ба таври калон зиёд кунад. Дар ин дастур ба тафсилоти фаннӣ, аз ҷумла намуди гузар, саммити обёрӣ ва истифодаи намои тиб дида шудааст.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
