SET @resolved_slug=IF(@slug_conflict IS NULL,'shati-napa-maintenance','shati-napa-maintenance-crop-192-iraq');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'shati-napa-maintenance-crop-192-iraq-3cfa8d51');
