SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='nihohubin-naqshagi-bo-navari-t-bar' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'nihohubin-naqshagi-bo-navari-t-bar','nihohubin-naqshagi-bo-navari-t-bar-crop-192-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'nihohubin-naqshagi-bo-navari-t-bar-crop-192-tj-ff5992d4');
