SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='comprehensive-carrot-cultivation-drip-tape-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'comprehensive-carrot-cultivation-drip-tape-irrigation-guide','comprehensive-carrot-cultivation-drip-tape-irrigation-guide-crop-198-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'comprehensive-carrot-cultivation-drip-tape-irrigation-guide-crop-198-en-bb19873e');
