SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='omuzish-umumi-ziyod-kardani-hosilnoki-bamiya' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'omuzish-umumi-ziyod-kardani-hosilnoki-bamiya','omuzish-umumi-ziyod-kardani-hosilnoki-bamiya-crop-199-tj');
