SET @resolved_slug=IF(@slug_conflict IS NULL,'mishon-hosili-mash-dar-1-hektar-bo-nubi-tib','mishon-hosili-mash-dar-1-hektar-bo-nubi-tib-crop-201-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'mishon-hosili-mash-dar-1-hektar-bo-nubi-tib-crop-201-tj-86697f03');
