SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='miktora-bobihoki-miyatar-varekhtar' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'miktora-bobihoki-miyatar-varekhtar','miktora-bobihoki-miyatar-varekhtar-crop-204-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
