SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='managing-cotton-pests-diseases-drip-irrigation' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'managing-cotton-pests-diseases-drip-irrigation','managing-cotton-pests-diseases-drip-irrigation-crop-214-en');
