SET @resolved_slug=IF(@slug_conflict IS NULL,'tahlil-arzishi-parvarihi-sarim-bosi-sistemi-nagulii-tase','tahlil-arzishi-parvarihi-sarim-bosi-sistemi-nagulii-tase-crop-215-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'tahlil-arzishi-parvarihi-sarim-bosi-sistemi-nagulii-tase-crop-215-tj-c68723b1');
