SET @resolved_slug=IF(@slug_conflict IS NULL,'fosila-i-chora-i-konichi-i-murchob','fosila-i-chora-i-konichi-i-murchob-crop-217-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fosila-i-chora-i-konichi-i-murchob-crop-217-tj-9626ad10');
