SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fosilaishuuri-tip-nokushkonii-nahuri-moyarhoi-tavsiashuda-crop-218-tj-eecae266');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада: Чаро фосилаи ғараи бозорӣ дар кашт ва парвариши бишток муҳим аст?</h2>\n<p>Бишток, ҳамчун яке аз муҳимтарин гиёҳҳои паштур, барои ғизо ва нигоҳ доштани сохтори хок ба системаи оҳиста ва пайвастаи абшавӣ ниёз дорад. Дар абшавии қутрӣ ва ғараи бозорӣ, ҷойгир шудани дурусти лӯла дар зер хати кашт, бевосита ба пӯшишдиҳии реша ва тақсимоти баробари намнокӣ дар зонаи реша таъсир мерасонад. Бисёр деҳқонон дар интихоби <strong>фосилаи ғараи бозорӣ дар кашт ва парвариши бишток</strong> дар мушкилоти афсонакӣ қарор доранд; оё ғара бояд аслан дар зер реша бошад ё дар фосилаи бехатар? Ин ҷавоби савол ба омилҳое, аз қабили намуди хок, иқлими минтақа ва намуди мошини кашт вобаста аст.</p>\n<p>Стандартҳои тавсияшуда барои ҷойгиркунии сатҳҳо (Row Layout) дар кашт ва парвариши бишток, мақсадро ба кам кардани фишори абӣ дар давраҳои ҳассос гулистозӣ ва тоҳугзорӣ ва пешгирӣ аз абшидани беҳудаи қисматҳои норешаӣ марказӣ мекунанд. Дар ин ҷо, бо тафсилоти техникӣ ва амалӣ, ба таҳлили беҳтаркунии ин фосилаҳо мепардозем.</p>\n\n\n\n<h2>Асосҳои техникии ҷойгиркунии сатҳи бишток ва ҷойгиршавии ғараи бозорӣ</h2>\n<p>Барои муайян кардани <strong>фосилаи ғараи бозорӣ дар кашт ва парвариши бишток</strong>Баҳодиҳии вобастагии байни андозаи байнрадаҳо ва шумораи маҳалли шӯи об дар хок муҳим аст. Навиши бисёр вақт дар ду системаи асосии ниёбӣ (дурдаҳо), ё ягон даҳа (яксинг) партоб карда мешавад. Фазои муқаррарӣ байни раҳоҳо вобаста ба моҳ, аз 50 то 65 сентиметр тағйир меёбад, аммо қатри чароги раҳоҳо тақрибан аз 3 то 5 сентиметр аз сатҳи хок анҷом дода мешавад.</p>\n\n<h3>1. Ташаккули ягон раҳо (Системаи Single Row)</h3>\n<ul>\n<li><strong>Фазои байни раҳоҳо:</strong> Одатан байни 40 то 50 сентиметр.</li>\n<li><strong>Ҷойгиршавии хати шӯӣ:</strong> Дар ин система, хати шӯӣ бояд баландтаран таҳти хати чароги раҳо бошад, бо қатри 2 то 3 сентиметр таҳти сатҳи хок ҷойгир мешавад.</li>\n<li><strong>Фазои канора:</strong> Фазои хати шӯӣ то маркази раҳо бояд камтар аз 10 сентиметр бошад, то ба рутубат, тоҷикӣ тақсим мешавад.</li>\n</ul>\n\n<h3>2. Ҷойгиркунии дуқаторӣ ё ду қаторӣ (Системаи дуқаторӣ)</h3>\n<p>Дар усули дутарафона ё дуқаторӣ, ки дар минтаҷаҳои хушктар маъмултар аст, ду қатори либе бо масофаи наздик (тақрибан 20 то 25 сантиметр) ва масофаи байни блокҳои дуқаторӣ (60 то 70 сантиметр) шинонда мешаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-لپه-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت لپه: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop либе</figcaption></figure>\n<ul>\n<li><strong>Ҷойгирии нӯри дрип:</strong> Нӯри дрип дар маркази ҳар як блоки дуқаторӣ (яъне дар миёнаи масофаи 60-70 сантиметрӣ) ҷойгир мешавад.</li>\n<li><strong>Масофа аз решаҳо:</strong> Дар ин ҳолат, масофаи нӯри дрип то наздиктарин решаи бутта тақрибан 10 то 15 сантиметр аст. Ин масофаи бехатарӣ имкон медонад, ки паршистани мустақими об гарм ба болои бомбӯш ё таҷи решаҳоро пешгирӣ кунад ва тақсимоти баробартари рутубат дар ду қатори ҳамсоя сурат гирад.</li>\n<li><strong>Самти ҳаракати чархҳои мошинҳо:</strong> Ин ҷобаҳшӣ имкон медиҳад, ки мусҳидҳо бидуни задаи решаҳои асосии лӯбиё аз байни кӯлаҳои танӯзӣ гузаранд.</li>\n</ul>\n\n<p>Бояд дида ҳисоб кард, ки дар <strong>Фосилаи намуни лӯбӣ дар кариб (лӯбӣ)</strong> Барои системаи дуравӣ, ғайрисимметрияи ҷобаҳшӣ метавонад боис шавад, ки қисми дохилии дурав хушк монд ва дар қисми берунӣ об кам шуд. Аз ин рӯ, танзими дақиқи хатти намуни лӯбӣ ба маркази геометрии кӯла калиди муваффақият аст.</p>\n\n\n\n<h2>Таъсири хусусиятҳои хок бар интихоби фосила</h2>\n<p>Хоки кушод ва сабук (масалан, риғзӣ) суръати нафси обро баланд мебардорад ва даираи шӯстаи обро маҳдудтар мекунад. Бидуни ин, хокҳои шудурул (лӯйм) намдориро баробартар ва тавассути ҳаракати капиллӣ дар амиқии зиёд пароканда мекунад.</p>\n\n<table>\n  <thead>\n    <tr>\n      <th>Навъи хок</th>\n      <th>Фосилаи тавсияшудаи намуни лӯбӣ аз маркази рав (якрравӣ)</th>\n      <th>Дури ҷойгиршавии нӯри Tiph</th>\n      <th>Эзоҳи техникӣ</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>Резғун (Шадаб)</td>\n      <td>5 то 8 сантиметр</td>\n      <td>2 то 3 сантиметр</td>\n      <td>Об таҷзия шуда дар баробар парҳез мешавад; масофаи камтар лозим аст.</td>\n    </tr>\n    <tr>\n      <td>Роски (Сос-роски)</td>\n      <td>5 то 10 сантиметр</td>\n      <td>3 то 4 сантиметр</td>\n      <td>Шароити мувозинатнокнтарин; устувории баланди таранҷум.</td>\n    </tr>\n    <tr>\n      <td>Шакаст ва равиш</td>\n      <td>8 то 12 сантиметр</td>\n      <td>3 то 5 сантиметр</td>\n      <td>Капилляритси қавӣ; имконияти зиёдтарини фосилоҳро мебахшад.</td>\n    </tr>\n  </tbody>\n</table>\n\n<p>Дар сурати истифодаи лӯлаи навартип бо диаметр 16 ё 12 миллиметр ва фосилаи гиреҳҳо 12 ё 15 сантиметр, метавон давраҳои пӯсаки ҳамсояҳоро то ҳадди имкон омехта кард, то ки аз хушк шудани навартипулоси миёнаи хок байни сатҳҳо пешгирӣ шавад. Ин яки принсипи калидӣ дар беҳтарсозӣ мебошад <strong>Фосилаи навартип дар кишти лӯға</strong> ист.</p>\n\n<h2>Амалӣ нуқтаҳо барои иҷро кардани дурусти оварии об бо усули нафкадкунӣ барои псевдокоциум (левзея)</h2>\n\n<h3>1. Танзими чуқурии нафкади об нисбат ба қабати зичшуда</h3>\n<p>Баъди гузаштани машинаи беҳбурдонӣ, қабати хокки зичшуда (Compact Layer) дар чуқурии 3 то 5 сантиметр боқӣ мемонад. Нафкади об бояд асосан дар ҳамин қабати зичшуда ва дақиқан зери он joy гирад. Агар нафкади об дар чуқурии зиёдтар аз беҳбурдонии дона joy гирад, решаҳои асосӣ наметавонанд ба осонӣ ба об расанд ва наботот ба стресс хубор мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-لپه-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت لپه: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>масофаи нафкади об тарҳбандии сутун ғаламези левзея</figcaption></figure>\n\n<h3>2. Ташаккули рафоби об ва фишори система</h3>\n<p>Барои фарогирии оптималӣ 10 то 15 сантиметр дар атрофи нафкади об, фишори кории система бояд байни 1 то 2 бар бошад. Агар фишор зиёд бошад, об дар шакли чӯрҳои обнокишуда дар атрофи нафкади об ташаккул меёбад ва сабаби сӯзиши решаҳои назари левзея мешавад. Ба тазаммун, фишори кам фарогирии нокомплет ташаккул меорад. Мувозинат дар <strong>Масофаи нафкади об дар беҳбурдонии левзея</strong> ва фишори обварӣ ду тарафи як сақфа мебошанд.</p>\n\n<h3>3. Моҳтоби обварӣ бо ҳарорати хок</h3>\n<p>лапу дор ба намуди доимӣ (Constant Moisture) дар тӯли мавсими барои ҳассос аст. Дар баҳор ва тобистон, бо кам шудани ҳарорати хок дар охирҳои шаб, вақти беҳтарини чархзанинии нави таси чизи ҳастанд. Обварии рӯзона бо ҳаҷми кам (10 то 15 метри мукабб дар гектар, вобаста ба иқлим) ба ҷои обварии ҳафтаноки пурҳаҷм, хатари шӯру рӯйшати рӯявӣ ва бемориҳои занби ғазӯро аз тағйирот дар намнокӣ-хушкӣ ба таври муҳим кам мекунад.</p>\n\n\n\n<h2>Чалони маъмул ва роҳҳои амалӣ</h2>\n<ul>\n<li><strong>Табъи гиёҳ ва шустани нави таси чизи:</strong> Ҳангоми дарҷондани гизо тавассути нави таси чизи, масоҳати нави таси чизи то решаи рост аҳамияти ҳаётӣ дорад. Агар масоҳат дар ҷойгиркунии ду қатор камтар аз 5 сентиметр бошад, консентратсияи маҳлули гизо метавонад ба таври маҳаллӣ зиёд шавад ва сабаби сӯзони реша (Fertilizer Burn) гардад. Таваққуф додани гизо бо об обварӣ ва танзими консентратсияи беҳтар дар <strong>Масоҳати нави таси чизи дар партоби лапу дор</strong> тавсия мешавад.</li>\n<li><strong>Поӯшиш риштаҳо бо хок:</strong> Пас аз гузашти ҳафтуми дуюми партоб, риштаҳои паҳлӯии лӯбои ҷустуҷӯи таробро аз сатҳи хок ба чуқурӣ мекунанд. Агар риштаҳо ба тоқили хок пурра пошонида нашаванд, риштаҳо дар қабати сатҳӣ (болимат 5 см) риштакашӣ мекунанд, ки ин қабат бо наби бобу офтоб хушк мешавад. Бинобар ин, партоб хок бар риштаҳо пашти тоқил бошад, вазифаи беҳамдаст аст.</li>\n<li><strong>Мубориза бо кӯпҳои зараровар байни риштаҳо:</strong> Фосилаҳои холӣ байни риштаҳо дар тарҳбандии кушода муҳити мувофиқ барои афзоиши кӯпҳои зараровар мебошад. Истифодаи ӯзҳои химиявии максаднок, пеш аз бадани риштаҳо, зарур аст, то аз рақобат барои тароб ва моддаҳои ғизоӣ пешгирии кӯпҳои зараровар карда шавад.</li>\n</ul>\n\n<p>Таҷрибаҳои деҳқоноён нишон медиҳад, ки идоракунии беҳтарини <strong>Фосилаи риштаҳо дар кунҷи лӯбои</strong> Ба назар нагирифтории шароити риштакашӣ, метавонад самаранокии обро то 20 фоид зиёд кунад. Ин зиёдшавии самаранокӣ, бевосита ба ҳаҷми истеҳсоли нохи лӯбои дар як гектар таъсир мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-لپه-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت لپه: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>fosilay-i rishtha tarhibandii kunji lubbai</figcaption></figure>\n\n<h2>Саволҳои оддӣ (FAQ) дар бораи обёрди нисо бо нӯри пайкар</h2>\n\n<ol>\n<li><strong>Савол: Оё имкон дорад, ки нӯри пайкарро байни сафҳои нисои ки дар хок боронида шудаанд, ҷойгир кард?</strong><br>\nҶавоб: Бале, дар тартиботи ду саф, нӯри пайкар дақиқан дар миёнаи фазои байни ду блокҳои ду саф ҷойгир мешавад. Ин "байнисафӣ" будан, аз бурида шудани решаҳои асосӣ тавассути нӯри пайкар пешгирӣ мекунад ва каналҳои умумии шустаниро барои ҳар ду саф эҷод менамояд.</li>\n\n<li><strong>Савол: Дар куё ҳол нӯри пайкари 16 миллиметрро ба ҷои 12 миллиметр истифода мебарем?</strong><br>\nҶавоб: Дар минтақаҳо бо камбудии шадиди об ва талаботи рӯзиаш зиёда аз 10 метри мукауб, нӯри пайкари 16 миллиметр бо лампаҳои (кафшҳои) беҳтарин фосиладошӣ, таҳвилоти баландтари обро бо шустани якхела фароҳам меорад. Дар минтақаҳои мутобиқ бо нӯри пайкари 12 миллиметр ва кафшҳои 15-15 сантиметрӣ низ пӯшиши лозима амалӣ мегардад.</li>\n\n<li><strong>Савол: Чӣ тавр метавон аз таҳаввули рағбат (намӣ) зери нӯри пайкар дар хокҳои пастулулук (паст-лулук) пешгирӣ кард?</strong><br>\nҶавоб: Бурдани нисо дар ҳамаи камтар (3 сантиметр) ва истифодаи нӯри пайкар бо кафшҳои 10-15 сантиметрӣ дар <strong>Фосилаи нӯри пайкар дар боронунии нисо</strong> Оптимизация позволяет насыщать зону вымывания влаги на более глубоком уровне за счёт капиллярного движения. Также надлежащий дренаж перед посевом предотвращает образование затопленных ям вокруг полос.</li>\n\n<li><strong>Вопрос: Имеет ли значение расстояние от полосы тип до угла ряда в однорядной компоновке?</strong><br>\nОтвет: Да, в однорядной компоновке, если расстояние от полосы тип от центра ряда превышает 12 сантиметров, влага остаётся в виде локализованного и сконцентрированного вымывания, а боковые корни сои оказываются в сухой зоне вымывания вокруг него. Для желаемого покрытия вымывания требуется расстояние менее 10 сантиметров.</li>\n</ol>\n\n<h2>Резюме: Стратегия устойчивости в эффективности использования воды</h2>\n<p>Оптимальный выбор <strong>Расстояние между полосами тип в выращивании сои</strong> Это процесс, включающий в себя комбинацию почвоведения, ботаники и ирригационной техники. Двухрядная компоновка с расположением полосы тип посередине грядки является эффективным выбором для большинства сельскохозяйственных слоёв с использованием посевных машин, поскольку она предотвращает повреждение корней и обеспечивает равномерное покрытие влажностью для обоих рядов.</p>\n<p>Дар натиҷа, диққат ба хусусиятҳои бумӯшишароӣ, истифодаи фишори мувофиқ ва нигоҳдории мунтазами шӯистани нарди тиб лозимияти назорати доимии таргии хокро дар тӯли мавсими афрӯдӣ талаб мекунад. Барои таъмини баландтарин самаранокии истеҳсоли ҷавдол, деҳқонон метавонанд ба [рахнамои умумӣ барои кардани ҷавдол] (https://navar-abyari.ir/%d8%b1%d8%a7%d9%87%d9%86%d9%85%d8%a7%db%8a%20-%d8%ac%d8%a7%d9%85%d8%b9-%da%a9%d8%a7%d8%b4%d8%aa-%da%a9%d8%af%d9%88-%d8%aa%d8%ae%d9%85%db%8d/) ва [мӯҳлати тӯҳфари ҷавдол дар як гектар] (https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%b1-%d8%a8%d8%af%d8%b1-%d8%a8%d8%a7%d9%82%d9%84%d8%a7-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/) ҳамчун манбаъҳои иловагии ҷойгиркунии меваҳои дигар муроҷиат кунанд. Инчунин, барои фаҳми беҳтар ҳаҷми истеҳсоли ҷавдол дар як гектар, хондани [ҳаҷми истеҳсоли ҷавдол дар як гектар] (https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%ac%d9%88-%d8%af%d9%88%d8%b3%d8%b1-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/) тавсия дода мешавад. Дар натиҷа, агар шумо дар ҷустуҷӯи беҳтар кардани системаи оварӣ дар кунҷи боғбонӣ ва думбоғбонӣ бошед, [ҳаҷми истеҳсоли ҷавдол ва шаш дигар] (https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%AC%D9%88-%D8%B4%D8%B4-%D9%BE%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/) нуқтаҳои муҳимро пешниҳод мекунад.</p>\n<p><strong>Мактабҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%d8%b1%d8%a7%d9%87%d9%86%d9%85%d8%a7%db%8c-%d8%ac%d8%a7%d9%85%d8%b9-%da%a9%d8%a7%d8%b4%d8%aa-%da%a9%d8%af%d9%88-%d8%aa%d8%ae%d9%85%db%8c/">Раҳнамои умумӣ барои кардани ҷавдол</a>, <a href="https://navar-abyari.ir/sesame-seed-quantity-per-hectare-yield-tips/">sesame seed quantity per hectare yield tips</a>, <a href="https://navar-abyari.ir/%D9%82%DB%8C%D9%85%D8%AA-%D9%84%D9%88%D9%84%D9%87-%D9%84%DB%8C-%D9%81%D9%84%D8%AA/">D982DB8CD985D8AA D984D988D984D987 D984DB8C D981D984D8AA</a>, <a href="https://navar-abyari.ir/bell-pepper-yield-per-hectare-tajik-farmers/">bell pepper yield per hectare tajik farmers</a></p>','Фосилаи шитори нӯри тип дар қаришкунӣи наҳӯрӣ: Маъёрҳои тавсияшуда','Хатоҳои маъмул дар созандагии чидкунии навори типӣ барои растанҳои ҳабшӣ, масалан, лӯбӣ, одатан аз фаҳмиши нодурусти дарёи решагӣ ва зичии бӯдаҳо сарчasma мегиранд. Ин дасту nomҳо чидкунии беҳтарини сафҳоро барои истифодаи максималии захираҳои об тавзеҳ медиҳад.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
