SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='comil-rahnamoyi-ghuqur-gharoh' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'comil-rahnamoyi-ghuqur-gharoh','comil-rahnamoyi-ghuqur-gharoh-crop-219-tj');
