SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='fosilayi-nuri-tayp-dar-kishtahoi-tolerant-rahnamo' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'fosilayi-nuri-tayp-dar-kishtahoi-tolerant-rahnamo','fosilayi-nuri-tayp-dar-kishtahoi-tolerant-rahnamo-crop-220-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fosilayi-nuri-tayp-dar-kishtahoi-tolerant-rahnamo-crop-220-tj-9b21d7b9');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарот: Аҳамияти бартарин кардани фосилаи нӯқутипӣ дар парвариши камалина</h2>\n<p>Камалина яке аз растаҳои саноатии арзанда, ки дар муҳитҳои иқлимии гуногун ва шартҳои экологии гуногун парвариш карда мешавад, мебошад. Дар системаҳои оғобёркунии муосир, истифода аз <strong>нӯқутипӣ</strong> бо сабаби қобилиятҳои бисёр ва самаранокии баланд дар расондани об ба реша, усули асосӣ ва васеистеъмолӣ мебошад. Яке аз суолҳои асосии кишоварзон, ёфтани «фосилаи нӯқутипӣ дар парвариши камалина» бартарин аст. Ин параметр на танҳо ба хараҷҳои ибтидоӣ таъсир мерасонад, балки ба паҳншавии якхелаи оғобёр, афзоиши якхелаи раста ва баъд аз он, ба зиёд шудани ҳаҷм ва сифати маҳсули ниҳоӣ таъсири мустақим дорад.</p>\n<p>Ҳадафи ин мақола, таҳқиқи муфассали фосилаҳои тавсияшуда барои нӯқутипӣ дар саҳободаҳои камалина асосан дар бораи амиқии реша, шартҳои хок ва нонакҳои парвариш аст. Бо мо бошед, то ба таҳлили тафсили ҷойгиркунии садҳо, нуқтаҳои амалӣ ва суолҳои муқаррарӣ равона карда шавем.</p>\n\n\n<h2>Ҷойгиркунии садҳо ва нақши фосилаи нӯқутипӣ дар парвариши камалина</h2>\n<p>Фаҳмидани робитаи миёни <strong>фосилаи садҳо</strong> ва <strong>Шумораи нӯрони пайп ҳар як қатор</strong>, асоси тарҳбандии дурусти оборӣ мебошад. Дар тизимҳои оборию бозгаштӣ, нӯрони пайп одатан як бор дар ҳар як шӯрбобон ё дар байни онҳо партофта мешаванд. Масофа байни нӯрони пайп бояд чунин бошад, ки минтақаи таршавӣ (Wetted Zone) аз ду нӯри ҳамсоя ба якдигар расад, аммо ҳеҷ гоҳ ба андозе нарасад, ки боиси гарофтани решаҳо гардад. Ин мувозинат яке аз калидҳои таъсиррасонӣ ба бунбаши маҳсулот аст.</p>\n<h3>Таъсири чуқурии решакишии калам</h3>\n<p>Озмудҳо нишон медиҳанд, ки қабати фаъоли решаи калам ҳаргунанд ва вобаста ба намуд, синни наботот ва шароити хок тағйир меёбад. Дар ҳафтароҳҳои аввали рӯшӣ, решаҳо сатҳӣ‌таранд, аммо бо гузашти вақт ба қабатҳои чуқури‌тар ҳаракат мекунанд. Масофаи нӯрони пайп бояд чунин танзим карда шавад, ки об то андиши фаъоли реша дар охирин босор барасад. Мутолиқа кун, ки масофаи амудӣ байни нӯронҳо (яъне шумораи нӯронҳо дар як шӯрбобон) метавонад як, ду ё ҳатто се нӯро дарбар гирад, вале масофаи уфуқӣ байни шӯрбобонҳо (масофа аз шӯрбобон то шӯрбобон) таъсири бештари ба таъмини умумӣ дорад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کاملینا-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت کاملینا: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>масофаи пайпҳо, тарҳбандии қаторҳо, партоби калам</figcaption></figure>\n<h3>Стандартҳои тавсияшуда барои масофаи шӯрбобон то шӯрбобон</h3>\n<ul>\n<li><strong>Дар шароити сабук ва рангии хок бо даромади паст:</strong> Тавсия мешавад, ки масофа хурдтар бошад, яъне тақрибан 45 то 50 сантиметр, то ки тақсимоти об беҳтар шавад.</li>\n<li><strong>Дар шароити хуки миёна ва шағалакӣ, бо гузаштагии хуб:</strong> Масофа дар ҳаҷми 55 то 65 сантиметр бештар мувофиқ аст, зеро об метавонад беҳтар ба чуқурӣ расад ва масофаи бозарро фаро гирад.</li>\n<li><strong>Дар системҳои якришта (Single-row) бо интиқоли наҳф (тип):</strong> Масофайи ришта (шир) метавонад то 70 сантиметр низ расад, ки бевосита вобаста ба суръати ризиши наҳф аст.</li>\n</ul>\n\n\n<h2>Нуқтаҳои амалӣ барои муайян кардани масофайи наҳф (тип) дар боғҳои кукуруза</h2>\n<p>Ҳангоми омодагии замин ва кундани, риоя кардани нуқтаҳои иҷроӣ метавонад ба таври мустақим таъсири ҳосилнокии системаи обёрӣ ва беҳтар шудани масофаҳои интихобшударо овард.</p>\n<ol>\n<li><strong>Санҷиши аввалинашавии наҳф (тип) дар боғ:</strong> Пеш аз ниҳоїдани ҷойгиркунии ниҳоӣ, як нахи тамро муваққатан дар майдон гузоред ва пас аз 24 соати обёрӣ, чуқурӣ ва андозаи минтақаи тарро чен кунед. Ин кор ба шумо кӯмак мекунад, ки масофаи дақиқро бо назардошти суръати махсуси нӯфӯдониши нах муайян кунед.</li>\n<li><strong>Ҳамсатҳии нах бо гардиш:</strong> Ҳатман боварӣ ҳосил кунед, ки нахи там маҳз дар гардиш ва зери токӣ ҷойгир шудааст. Ягон ҷазоғӣ ё каҷӣ вуҷуд наяд. Каҷ шудани нах боиси пайдоиши нуқтаҳои нобаробари тару хушк мегардад.</li>\n<li><strong>Бартарноксозӣ бо ҷойгиркунии қатор:</strong> Агар аз ҷойгиркунии қатории ду нах дар ҳар як гардиш истифода мебаред, масофаи нахҳоро дар дохили гардиш бо таври якхела назар дошта бошед. Масалан, агар гардиш 30 сантиметри чуқурӣ дошта бошад, нахҳо дар чуқурии 10 ва 20 сантиметрӣ ҷойгиранд. Ин ҷойгиркунимон карда, ки масофаи уфуқӣ байни гардишҳои ҳамсоя ба мадди зиёд афзоиш меёбад ва хароҷот кам мешавад.</li>\n<li><strong>Нақши идоракунии хок:</strong> Дар хокҳое, ки таърихи сахтшавии сатҳиро доранд, масофаҳои дарозтар тавсия дода мешаванд. Барои олимӣ оид ба хусусиятҳои хок, шумо метавонед дастуравоҳии обёрии мақсаднок аз қаториро омӯзед, то фаҳмиши беҳтареро оид ба нӯфӯдониши об дар хок ҳосил кунед.</li>\n<li><strong>Ҳифзи масофаҳои сарҳадӣ:</strong> Дар мавзеҳои, ки ченаки баррасии бӯди барои гуногуни якфасилаҳо истифода мешавад, бояд тамаддун шавад, ки ченаки баррасии бӯди сари бӯдӣ-ро напушта ва наҷойгузорона накардааст.</li>\n</ol>\n<p>Инчунин, эҳтиром ба <strong>хароҷи сари бӯдӣ барои як гектар чӣ қадар аст?</strong> масъалаест, ки дар ҷойгиршавӣ, ба қарори корти калминаъ таъсир мерасонад. Барои тафшиси дақиқтар ин масъала шумо метавонед ба роҳнамоии хароҷи сари бӯдӣ барои як гектар муроҷиат кунед, то мувозунат байни хароҷот ва фосилаи интихобшударо дуруст баррасӣ намоед.</p>\n\n\n<h2>Саволҳои маъмулӣ (FAQ)</h2>\n<h3>1. Оё фосилаи сари бӯдӣ дар мавзеҳои калминаъ кишҳои зимистона бо кишҳои пайизӣ фарқ дорад?</h3>\n<p>Бале, то андозае, ки шароити хок ва ҳарорати муҳит фарқ мекунад, фосилаи тавсияшуда низ метавонад тағйир ёбад. Дар кишҳои пайизӣ, рӯиши аввали рӯяк одаҳо тезтар аст ва ниёз ба фосилаи камтар дорад, то ки рӯякҳои нав ба об дастрасӣ доранд. Баъд аз он, дар мавзеҳои зимистона, рӯиши рӯяк метавонад сохтори зиёдтар дошта бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کاملینا-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت کاملینا: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop калминаъ</figcaption></figure>\n<h3>2. Агар аз лентаҳои дарқатноқ бо суръати офтан низкор истифода мебарам, масофаро зиёд мекунам?</h3>\n<p>Не, суръати офтан камтар маънои онро дорад, ки минтақаи тар мешаван бориқтар ва чуқуртар аст. Дар ҳамин ҷо барои фарогирии беҳтарин, метавон масофаи байни лентаҳо ва нақобҳоро каме зиёд кард. Аммо ин зиёдшавӣ бояд дар асоси санҷишҳои майдонӣ бошад.</p>\n<h3>3. Оё ҷойгиршавии қаторӣ бо ду лента дар ҳар нақоб ба масофаи нақоб-ба-нақоб таъсир мерасонад?</h3>\n<p>Бале, бо ҷойгир кардани ду лента дар нақоб, чуқурии пӯшиши об зиёд мешавад ва шумо метавонед бо нигоҳ доштани фарогирии мувофиқ, масофаи нақоб-ба-нақобро то ҳадди муайян зиёд кунед ва аз шудаи камтари лентаҳои дарқатноқ раҳо шавед. Ин як усули оддӣ барои кам кардани хароҷот аст.</p>\n\n<h2>Хулоса: Интихоби масофаи лентаи дарқатноқ барои бастакунии ҳосили камил</h2>\n<p>Муайян кардан <strong>Масофаи лентаи дарқатноқ дар кунҷи камил</strong> Як раванди муҷаллас аст, ки омилҳои хок, реша, шароитҳои иқлимӣ ва суръати офтани лентаро дар бар мегирад. Ба ҷои тавakkal ба як рақами ягона, тавсия дода мешавад, ки деҳқонҳо бо анҷоми санҷишҳои кӯтоҳмуддат дар замини худон, масофаеро интихоб кунанд, ки мувозинатро байни фарогирии об ва арзиши лентаи дарқатноқ пурра исбот кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کاملینا-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت کاملینا: استانداردهای توصیه‌شده - تصویر 3"/><figcaption> фосилаи назм ва ҷобаи пичкабарии қитъа барои чандир</figcaption></figure>\n<p>Истифодаи ҷобаҳои рони беҳтар ва нигоҳ доштани дақиқии корҳо метавонад самаранокиро ба сурати назаррас зиёд кунад. Барои донистани беҳтар дар бораи дараҷаҳои мухталифи ҳосили маҳсулот, шумо метавонед ба мақолаҳое монанди миқдори ҷамъоварии себ дар як гектар ё миқдори ҷамъоварии шабдат дар як гектар ва роҳҳои зиёдкунӣ назар андозед, ки нишон медиҳанд, чӣ гуна системаи пичкабарии хуб ба сифат ва миқдори ҳосил таъсир мекунад.</p>\n<p>Дар натиҷа, пайгирӣ ва эҳтироми даими ҳамакӣ ба фавқалодаташаккунонӣ метавонад таъмини ба таври давомӣ муносиб будани фосилаи пичкаю нурӯҳ ва иҷрои хуби эҳтиёҷоти решаҳои қитъагаро таъмин кунад.</p>\n<p><strong>Маводеи алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%aa%d8%b1%db%8c%d8%aa%db%8c%da%a9%d8%a7%d9%84%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Маводи бубури тариха дар як гектар + ҷадвали зичии кишт</a>, <a href="https://navar-abyari.ir/spring-barley-harvest-yield-per-hectare-practical-solutions/">spring barley harvest yield per hectare practical solutions</a>, <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%ac%d8%b9%d9%81%d8%b1%db%8c-%d8%af%d8%b1-%d9%87%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори ҷамъоварии шабдат дар як гектар + роҳҳои зиёдкунӣ</a>، <a href="https://navar-abyari.ir/tikmi-kunjat-dar-hektar/">tikmi kunjat dar hektar</a></p>','Фосилаи Нӯри Тайп дар Киштҳои Толерант: Раҳнамои Фароғанд ва Тамоимҳои Тавсияшуда','Дониши дар бораи беҳтарин масофаи чидиши риштавӣ барои камалини, калиди дасторсидан ба самаранокии баланд ва кам кардани истифодаи об мебошад. Ин роҳнамо меъёрҳои тавсияшуда ва нуктаҳои амалии ҷойгиркунии ҳатҳоро шарҳ медиҳад.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
