SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='zarardarsuvarak-kukuruz-obari-noqatatalavi' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'zarardarsuvarak-kukuruz-obari-noqatatalavi','zarardarsuvarak-kukuruz-obari-noqatatalavi-crop-224-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'zarardarsuvarak-kukuruz-obari-noqatatalavi-crop-224-tj-d45cd877');
