START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-225' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-225:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='hajmi-hosili-piyajcha-dar-gektar-bo-namunai-tish' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'hajmi-hosili-piyajcha-dar-gektar-bo-namunai-tish','hajmi-hosili-piyajcha-dar-gektar-bo-namunai-tish-crop-225-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'hajmi-hosili-piyajcha-dar-gektar-bo-namunai-tish-crop-225-tj-8a12378b');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Чаро системаи оросиши махдудии риштагӣ барои парвариши пиёзча зарур аст?</h2>\n<p>Пиёзча (Allium cepa var. aggregatum) яке аз маҳсулоти қиматнок ва дарахолид аст, ки суръати афзоиши баланд дорад ва ба шароитҳои обзистӣ ҳассос аст. Дар шароитҳои анъанавӣ, оросиши хушкӣ метавонад боиси бемориҳои занбарунии ришта ва вайроншавии шохаҳои паҳлӯшавояд, ки мустақиман ба <strong>миқдори ҳосилшавии пиёзча дар ҳектар бо усули махдудии риштагӣ</strong> асари манфӣ мерасонад. Системаи махдудии риштагӣ тавассути тақсимоти дақиқи об ва моддаҳои ғизоӣ дар сатҳи хок шароити идеалиро барои ташаккули пиёзчаҳои хурд ва якхоро фароҳам меорад.</p>\n<p>Истифодаи ин усули оросиш на танҳо ба кам шудани истифодаи об то 40 фоиз оварда мерасонад, балки бо нигоҳ доштани намнокии якхоро дар минтақаи риштагиҳо зероиси одавро паст мекунад ва аз ҷиҳати иқтисодӣ ҷозибии сармоягузориро дар соҳаи кишоварзӣ баланд мебардорад. Дар ин ҷо мо принсипҳои фаннӣ ва амалии ин усулро баррасӣ мекунем.</p>\n\n\n<h2>Параметрҳои асосӣ дар муайян кардани самаранокии пиёзча</h2>\n<h3>Таъсири зичии нишобанӣ ба ҳаҷми истеҳсолот</h3>\n<p>Яке аз омилҳои асосие, ки деҳқон бояд ба назар гирад, зичии муносиби нишобанӣ аст. Барои пиёзча, одатан масофаи охирин байни нохистҳо бояд чунин бошад, ки растаниҳо имконияти кофиро барои афзоиши кураҳои риштагӣ дошта бошанд, бе он ки дар ҷабби рӯшноӣ ва моддаҳои ғизоӣ рақобат кунанд. Дар хокҳои сабук, зичии баландтар қабул мешавад, аммо дар хокҳои сабук ва вазнин, кам кардани масофаҳо барои зиёд кардани истеҳсоли воҳидӣ ба фоида аст.</p>\n<h3>Идоракунии ғизо ва обори (Fertigation)</h3>\n<p>Обори навори ғизоӣ ба шумо имкон медиҳад, ки маводҳои заҳрнок ва гиёҳоваро (кӯдашҳо) минералиро мустақиман бо оби оборӣ истифода баред. Ин усул ҷӯшидани моддаҳои ғизоиро пешгирӣ мекунад ва ба ҷазиби беҳтари унсурҳои рӯйхаткунанда, ба монанди манган, раъй ва оҳан, оварда мерасонад, ки барои рушди пиязоҳои нӯлӣ зарур аст. Дар маҷмӯъ, иҷрои дурусти [идоракунии бӯи пиязоҳои нӯлӣ дар ҳар гектар](https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%AD%D8%AF%D8%B3%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/) дар асоси ниёзи воқеии гиёҳ, калиди муваффақият мебошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-پیازچه-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت پیازچه در هکتار با نوار تیپ - تصویر 1"/><figcaption>маҳсули ҳосил дар як гектар обори навори ғизоӣ пиязоҳои нӯлӣ</figcaption></figure>\n\n\n<h2>Қисмҳои ихтисосӣ: алоқаи реша ва намии хок</h2>\n<p>Пиязоҳои нӯлӣ гиёҳе бо системаи риши мураккаб ва пистон (бӯи) аст. Обори навори ғизоӣ бояд тавре тарҳрезӣ шавад, ки намӣ дар амикии 15 то 20 сантиметрӣ дар хок ҳисоб боқӣ монад. Агар намӣ сатҳӣ бошад, решаҳо сатҳӣтар мерӯянд ва дар вақти гармии шиддатнок ба зудӣ хушк мешаванд. Дар ин самт, шиносоӣ бо [молдодаи об дар бағалҳо истилоҳати писта](https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A7%D8%A8-%D8%AF%D8%B1-%D8%A8%D8%A7%D8%BA%D8%AA-%D9%BE%D8%B3%D8%AA%DB%8C%D9%87/) ҳамчун намунаи обори ҳашаматнок метавонад ба беҳтарсозии тарҳҳои обори пиязоҳои нӯлӣ илҳомбахш бошад, гарчанде ки ниёзҳои ҳар як маҳсулот гуногун аст.</p>\n<h3>Афзалиши самаранокӣ бо танзими сарфи мувофиқ</h3>\n<p>Барои афзалиши ҳосилнокии ниҳоӣ, сарфи баромаданда аз наворҳо ва фишори лӯлаи асосӣ бояд тавре танзим шавад, ки ҳеҷ қатрае ба берун аз минтақаи реша дохил нашавад. <a href=\'https://navar-abyari.ir/%d9%86%d8%ad%d9%88%d9%87-%d8%a7%d9%81%d8%b2%d8%a7%db%8c%d8%b4-%da%a9%d8%a7%d8%b1%d8%a7%db%8c%db%8c-%d9%88-%d8%a8%d9%87%d8%b1%d9%87%d9%88%d8%b1%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c/\' target=\'_blank\'>Шакли афзалиши самаранокӣ ва истеъмолнокии навори ғизоӣ</a> Ин талаботҳои амиқи донистани физикаи хок ва ҳидролики система дорад. Камак шудани табъуъ аз сатҳи хок яке аз фоидаҳои пинҳони ин система аст, ки боис ба истеъмолкунии камтар мегардад.</p>\n\n<h2>Нуқтаҳои амали барои боғҳои пиёз</h2>\n<ul>\n<li><strong>Ҷиҳозҳои иловагӣ:</strong> Истифодаи филтри мувофиқ барои пешгирии баст шудани навиҳои тип таассуротан муҳим аст. Мурофияҳои дренажи хокро низ бояд пеш аз бунбасти ғалла бозарзӣ намуд.</li>\n<li><strong>Вакти нобаробаркунӣ:</strong> Дар марҳилаҳои ибтидоии рушд, нобаробаркунӣ бояд маъмул ва ҳаҷми паст дошта бошад. Дар марҳилаи охирини ташаккули пиёзҳо, ҳаҷми нобаробаркуниро кам кунед, то ки ҷунгибар тайёр ба ҷамъ бадад.</li>\n<li><strong>Мудирияти дренаж:</strong> Таъмини, ки навъҳо дар хатти ростдори бунбос бошанд. Ҳар гуна инҳироъ боис ба хушк шудани қисме аз радифҳо ва камак шудани маҳсули интизоми мегардад.</li>\n</ul>\n<p>Барои муайяни дақиқтари раванди техникӣ, метавонед ба [марҳилаҳои насби наври Tefil](https://navar-abyari.ir/%d9%85%d8%b1%d8%a7%d8%b1%d9%84-%d8%af%d8%b3%d8%aa%d8%a8%d9%88%d9%84-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%d9%8a%d9%84/) муроҷиат кунед, то аз ҷойгиршавии дурусти таҷҳизот таъмин шавед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-پیازچه-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت پیازچه در هکتار با نوار تیپ - تصویر 2"/><figcaption>маҳсули зиёди ғаламбар дар гектар оварии боқлаҳо</figcaption></figure>\n\n<h2>Саволҳои зуд-зуд такроршаванда (FAQ)</h2>\n<h3>Оё наври Tefil барои ҳамаи намуди хок мувофиқ аст?</h3>\n<p>Системаи наври Tefil ба таври умумӣ барои аксари хокҳои кишоварзӣ тарҳрезӣ шудааст, аммо дар хокҳое, ки шӯрӣ баланд ё кислоталӣ қавӣ доранд, ба танзими кимиёвӣ ниёз доранд. Дар баъзе минтақаҳо истифодаи [пайвастагиҳои наври Tefи кишоварзӣ](https://navar-abyari.ir/%d8%a7%d8%aa%d8%b5%d8%a7%d9%84%d8%a7%d8%aa-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%d9%8a%d9%84-%da%a9%d8%b4%d8%a7%d9%88%d8%b1%d8%b2%db%8c/) бо сифати баланд умри системаро зиёд мекунад.</p>\n<h3>Фарқи наври Tef ва қапидашавӣ дар бағалӣ чист?</h3>\n<p>Наври Tef тавассути эҷоди банди намнок имконияти оварӣ ва партошро дар як вақт фароҳам меорад, ки барои заминҳои зиёди бағалӣ, ки фазои фавосилу фазобанд доранд, самараноктар аст. Капидашавӣ барои ниҳолҳое мувофиқ аст, ки бо фосилаҳои зиёдтар партошуда мешаванд.</p>\n<h3>Вақти беҳтарин барои партоши барои ҳадди акс маҳсулот?</h3>\n<p>Вобстаи иқлим, парвариши тирамашоӣ барои ҳосили тобистонӣ ва парвариши тобистонӣ барои ҳосили тирамашоӣ вуҷуд дорад. Интихоби намуди барори мувофиқ, масалан [барори шавол дар ҳектар](https://navar-abyari.ir/piyozcha-hosili-gektar-rohnomo/), метавонад фарқиятҳои назаррасро дар ҳосили ниҳоӣ ба вуҷуд орад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-پیازچه-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت پیازچه در هکتار با نوار تیپ - تصویر 3"/><figcaption>ҳосили ғалам по ҳектар нории заринӣ пиез</figcaption></figure>\n\n<h2>Хулоса: Калиди иқтисодӣ шудани боғҳои пиез</h2>\n<p>Муҳимтарин омили парвариши мӯффақпӯраи пиез, идоракунандагии омили муҳитӣ ва рӯшанӣ аст. Системаи нории заринӣ имкон медиҳад, ки об ва хӯрокворҳоро дақиқан дар вақти ҷойе ки гиёҳ ба он ниёз дорад, таъмин кунад. Ин дақиқӣ бевосита ба сифат ва миқдори пиезҳои иҳтирошуда таъсир мерасонад ва дар охир боиси афзуншавӣ <strong>ҳаҷми ғалам пиез по ҳектар бо нории заринӣ</strong> меояд.</p>\n<p>Инчунин, омӯзиши мақолаҳо монанди [рахнамбарии мағзорабарорӣ ғалам заринӣ по ҳектар](https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B3%D8%B3%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/) метавонад назари беҳтари муқоисаи ҳосили маҳсулоти гулдор бо маҳсулоти пиезӣ ба шумо диҳад. Бо риояи принсипҳои техникӣ ва назорати доимии системаи оборӣ, шумо метавонед ба самаранокии иқтисодии устувор ноил шавед.</p>\n\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B7%D8%A7%D9%84%D8%A8%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 D8B7D8A7D984D8A8DB8C D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/canola-yield-per-hectare-guide-iraqi-farmers/">canola yield per hectare guide iraqi farmers</a>, <a href="https://navar-abyari.ir/%D9%87%D9%85%D9%87-%DA%86%DB%8C%D8%B2-%D8%AF%D8%B1%D8%A8%D8%A7%D8%B1%D9%87-%D9%85%D8%B2%D8%A7%DB%8C%D8%A7%DB%8C-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D9%BE%D9%84%D8%A7%DA%A9%D8%AF%D8%A7%D8%B1/">D987D985D987 DA86DB8CD8B2 D8AFD8B1D8A8D8A7D8B1D987 D985D8B2D8A7DB8CD8A7DB8C D986D988D8A7D8B1 D8AADB8CD9BE D9BED984D8A7DAA9D8AFD8A7D8B1</a></p>','Ҳаҷми ҳосили пиёзча дар гектар бо намунаи тиш: Рамони амали барои зиёд кардани самаранокӣ','Муайяни омили мушоири ба уҳуди бубук ва таъсири системаҳои оборишӣ дар замини намо ва нӯрҳои пурқувват ба зиёд намудани ҳаҷми гулгӯй ва кам кардани зерри обу хок.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
