SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='fasila-navoni-tipish-o-kish-nuql-standard' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'fasila-navoni-tipish-o-kish-nuql-standard','fasila-navoni-tipish-o-kish-nuql-standard-crop-227-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fasila-navoni-tipish-o-kish-nuql-standard-crop-227-tj-67f7d4ba');
