INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','دليل شامل لزيادة غلطة الحمص في الهكتار بوحدة ري نظام الشريط الموصّل' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
