SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='bug-yigimi-oshirish-umumiy-qo-llanma' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'bug-yigimi-oshirish-umumiy-qo-llanma','bug-yigimi-oshirish-umumiy-qo-llanma-crop-228-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'bug-yigimi-oshirish-umumiy-qo-llanma-crop-228-tj-4c9bc954');
