SET @resolved_slug=IF(@slug_conflict IS NULL,'colored-seed-quantity-per-hectare-guide','colored-seed-quantity-per-hectare-guide-crop-230-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'colored-seed-quantity-per-hectare-guide-crop-230-en-7fe579c8');
