SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='soybean-cultivation-cost-drip-lines-hectare' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'soybean-cultivation-cost-drip-lines-hectare','soybean-cultivation-cost-drip-lines-hectare-crop-236-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'soybean-cultivation-cost-drip-lines-hectare-crop-236-en-df5e48df');
