SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='sesame-seed-rate-per-hectare-cultivation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
