SET @resolved_slug=IF(@slug_conflict IS NULL,'darayid-i-troitikale-dar-yek-hektar-bo-istriyoda-az-nuri-tip','darayid-i-troitikale-dar-yek-hektar-bo-istriyoda-az-nuri-tip-crop-239-tj');
