INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على اهم الآفات والأمراض التي تصيب الفلفل الحلو في نظام الري بالتنقيط. دليل فني للمزارعين العراقيين يتضمن حلول المكافحة والوقاية لزيادة المحصول وجودة الثمار مع الحفاظ على مياه الري.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','مشكلات و امراض الفلفل الحلو في نظام الري بالناقل' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
