SET @resolved_slug=IF(@slug_conflict IS NULL,'comprehensive-guide-caraway-cultivation-drip-tape-line-irrigation','comprehensive-guide-caraway-cultivation-drip-tape-line-irrigation-crop-244-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'comprehensive-guide-caraway-cultivation-drip-tape-line-irrigation-crop-244-en-d0fe7bf5');
