START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-244' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-244:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='rahnamai-comprehensive-kosht-shahi-be-yaribi-qatraie-wa-navare-tape' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'rahnamai-comprehensive-kosht-shahi-be-yaribi-qatraie-wa-navare-tape','rahnamai-comprehensive-kosht-shahi-be-yaribi-qatraie-wa-navare-tape-crop-244-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'rahnamai-comprehensive-kosht-shahi-be-yaribi-qatraie-wa-navare-tape-crop-244-tj-71359a42');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада: Аҳамияти идоракунии дақиқи об дар парвариши шаҳӣ</h2><p>Шаҳӣ яке аз гиҳазҳои дору ва хӯроквории арзишнок аст, ки ғиболи он дар Эрон решаҳои қадимӣ дорад, вале дар ҷаҳони муосири кишоварзӣ, муваффақият дар парвариши он ба дақиқии идоракунии манбаъҳои об ва хок вобаста аст. <strong>Ғиболӣ шаҳӣ бо оварии туп-тупӣ</strong> ва системаҳои монанд ба он, монанди шитобҳои риз, ҳалли илмӣ барои пайгирии даъвоҳои камобӣ ва беҳтарсозии сифати маҳсул мебошад. Ин системаҳо бо роҳи дақиқии об ба минтақаи решаҳо, аз заифшудани иловагии рӯйи замини ғиболи пешгирӣ мекунанд ва муҳити якхела барои афзоиши сафҳо ва истеҳсоли бадҳо эҷод мекунанд. Дар давом, ҳамаи ҷанбаҳои техникии ин роҳро бо муфассал менависем, то ки кишоварон бо иқрона аз натиҷа аз технологияҳои нави оварӣ истифода баранд.</p><h2>Асосҳои техникии шитобҳои риз дар ғиболи шаҳӣ</h2><p>Шитобҳои риз яке аз самараноктарин роҳҳои оварии маҳаллӣ аст, ки барои гиҳазҳое монанд ба шаҳӣ, ки ба намӣ аз решаҳо ҳисишанд, бисар мувофиқ мебошад. Иҷрои мағзидҳои тарик ва амиқ дар рӯи хок, боиси мешавад, ки об ва моддаҳои тудуқшуда ба таври мустақим ва бе хароҷот ба чуқурии решаҳо номад шаванд. Истифодаи шитобҳои риз дар ғиболи шаҳӣ се бартарии асосӣ дорад: аввал, камёбии назариёи истеъмоли об дар муқоиса бо роҳҳои оварии тағор; дуюм, пешгирӣ аз гиҳазҳои вайронкунанда байни қатъҳои гиҳазҳои асосӣ; ва сеюм, имконияти ҳарорати дохилии решаҳо, ки ҷабби беҳтари моддаҳои ғизоиро кафолат мекунад. Барои иҷрои дурусти ин роҳ, ошноӣ бо асосҳои механизатсия муҳим аст. Тавсия мешавад, ки кишоварон ҳатман дастурави махсусиро <a href="https://navar-abyari.ir/%d8%a2%d9%85%d9%88%d8%b2%d8%b4-%d8%a7%d8%b3%d8%aa%d9%81%d8%a7%d8%af%d9%87-%d8%a7%d8%b2-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be/">омӯзиш истифодаи шитобҳои риз</a> ро муолифа кунанд, то беҳтарин чуқурӣ ва масофаи шитобҳоро барои шаҳӣ ба даст оранд.</p><><h2>Вақти ғарсидан ва тайёр кардани замина</h2><p>Муваффақият дар <strong>ғарсидани шаҳӣ бо обёрӣ-ришандоӣ</strong> Аз худи замина оғоз меёбад. Шаҳӣ иқлими муътадилро бартарӣ медиҳад ва одатан ғарсидани он дар оғози баҳор ё охири тирамун анҷом дода мешавад. Тайёр кардани замина бояд ба таври чунин бошад, ки хокҳои гилӣ ва вазнин аз сатҳ хориҷ карда шаванд, то ки пайвастагии решаҳо ба осонӣ анҷом ёбад. Пеш аз ғарсидан, мувозинати кимиёвии хок бояд назорат шавад; шаҳӣ хокҳои сабук то миёнаро бо pH аз 6 то 8 дӯст медорад. Ҳамон вақте ки номувофиқият дар сатҳи замина вуҷуд дошта бошад, истифодаи шеравур ё трактор барои якхела кардани замина қадамҳои зарурӣ мебошад. Фосилагузории дурусти бобҳо ба якдигар таъсири мустақим ба шиддати рақобат барои об дорад. Бинобар он, одатан фосила байни бобҳо дар қатор 25 то 30 сантиметр ва фосила байни қаторҳо вобаста ба намуди системаи обёрӣ аз 60 то 80 сантиметр танзим карда мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-شاهی-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت شاهی با آبیاری قطره‌ای - تصویر 1"/><figcaption>методи ғарсидан системаи обёрӣ-ришандоӣ ҷадвали обёрӣ меҳварии обёрӣ шаҳӣ</figcaption></figure>\n<h2>Насб ва танжими системаи обёрӣ-ришандоӣ</h2><p>Калби зиндаи як бағъоми бой системаи обёрии он аст. Дар усули риндӣ об бо фишори паст ва сари сар ба рӯяндагии решаи баргҳо мерасад. Интихоби сари риндӣ мувофиқи намуди хок ва ниёзҳои баргҳо дар он марҳила муҳим аст. Барои шаҳӣ, сари риндӣ бо дебит аз 4 то 8 либру дар соат имконоти хуб мебошанд. Фосила байни сари риндиҳо одатан аз 20 то 25 сантиметр танзим карда мешавад, то ки пӯшиши тираҳӣ дар ҳудуди решаҳо ба беҳтарин тавр амалӣ шавад. Аз ҷониби дигар, зеро ки шаҳӣ баргҳои системаи решаҳои паҳншуда дорад, марказӣ кардани об дар атрофи сӯхтаи баргҳо самаранокии ҷабирро зиёд мекунад. Фаҳмидани асосҳои геометрии ҷойгиркунии сари риндиҳо бо тафаккури техникӣ лозим аст. Омӯзиши мақолаи чӣ гуна муайян кардани нуқтаҳои обёрӣ дар нурди туп ба ҳамчун намунаи ҳисоб кардани нуқтаҳои беҳтар барои системаҳои маҳаллӣ монанди обёрӣ-ришандоӣ хизмат менамояд.</p><h3>Ҷадвали стратегии обёрӣ барои шаҳӣ</h3><table><thead><tr><th>Марҳилаи рушди наҷор</th><th>Усули обёрӣ</th><th>Давраи тавсияшуда</th></tr></thead><tbody><tr><td>Бурҷи дун</td><td>Рутубати хеле устувор</td><td>Автоматӣ/рӯзона</td></tr><tr><td>Шакли пучлакҳо ва рушд</td><td>Обёрии мунтазам</td><td>Ҳар 2 рӯз як маротиба</td></tr><tr><td>Афзоиши рушони ғалзоӣ ва иловагӣ</td><td>Кам кардани доз, зиёд кардани чуқурӣ</td><td>Ҳар 3 рӯз як маротиба</td></tr></tbody></table><p>Диққат диҳед, ки ин ҷадвалҳо танҳо як пайдарпаии умумӣ мебошанд ва кибортар бояд бар асоси намуди замин (ғаллошӣ ё ранҷиб) ва ҳарорати ҳаво онҳоро навсозад. истифодаи ҳисобкунандаҳои намии замин метавонад ин равандро дақиқтар ва бе талафоти об иҷро кунад.</p><h2>Идоракунии таъмиркунии ва ҳашаротҳои дохилии ғалзоӣ</h2><p>Яке аз бартарииҳои асосии обёрӣи наққораӣ қобилияти иҷрои амали «фертигатсия» ё нӯшидани моддаҳои ғизоӣ тавассути хатҳои обёрӣ мебошад. Ин усул харҷҳоро барои паҳн кардани моддаҳои ғизоӣ дар сохторҳои калон ба ҳадди ақал мерасонад ва дақииқатро дар истеҳсолотро ба ҳадди зиёд мерасонад. Шаҳӣ ба нитроген ҳадди зиёд ҳассос аст ва дар оғози марҳилаи афзоиш нӯшидани моддаҳои ғизоии моеъи мурда тавсия дода мешавад. Дар миёнаи фасл истифодаи омехтаҳои фосфорӣ ва калий барои мустаҳкам кардани саркӯб ва истеҳсоли дони зарур аст. Аммо як нуқтаи бехатарии хеле муҳим вуҷуд дорад: истифодаи моддаҳоеро, ки дар шартҳои мушаххас равон мешаванд ё пӯст меандозанд, бояд парҳиз кард, то хатҳои нории тира ва наққораҳо хунукшаванд. Ғайр аз таъмиркунӣ, идоракунии ҳашарот ин роҳ низ мумкин аст; фитотериюҳо ва ҳашаротубазҳоҳои махсус метавонанд тавассути наққораҳо ба ғалзо расанд. Барои дониши беҳтар дар бораи идоракунии парвариш омехта ва истифодаи манбаъҳо, мақола <a href="https://navar-abyari.ir/white-bean-seed-amount-per-hectare-iraq/">white bean seed amount per hectare iraq</a> метавонад бо тафсилоти дар бораи идоракунии донишҳо ва фосилагӣ барои шумо муфид бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-شاهی-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت شاهی با آبیاری قطره‌ای - تصویر 2"/><figcaption>Усули кӯронӣ, обёрӣи таматчӣ, расми обёрӣ барои парот шӯрӣ</figcaption></figure>\n<h2>Хатогиҳои маъмул ва роҳҳои ислоҳотӣ</h2><p>Ҳатто бо беҳтарин системаҳо, хатогиҳои иҷроӣ метавонанд самаранокиро паст бароранд. Хатогии маъмултарин дар кӯрони пароти шӯрӣ, интиқоли бодоранг дар амиқии зиёдатар аз иҷозат (зиёда аз 2-3 см) аст, ки ба таъхири сарсабзшавӣ ва баъзан нокомии амалиёт мусоидат мекунад. Дурӯма хато, гирифтан сӯрохиҳои бодоранги бо решаҳои хобишуда баъд аз обёрӣ мебошад; ин масъала боиси он мешавад, ки оксиген ба решаҳо нарасад ва саъҳҳудҳо афзоиш кунанд. Ҳалли ин масъала, хушкавирида ба сатҳот мебошад. Сангине интиқол, гирифти филтрҳо аст. Дар системаи таматчӣ, филтршавӣ ҷойгоҳи баланд дорад. Агар хок дорои қатъчаҳои калон бошад, ҳатман аз филтри тӯбӣ ё магнитӣ истифода баред. Ин мавзӯъ алоқамандӣ бо бастакҳои интиқоби қатъчаҳои хомӯш дар кӯрон дорад, ки дар манбаъҳое чун <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d9%85%d8%a7%d8%b4-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳисоби бодоранги маш дар 1 гектар + омили таъсиргузор барои муайян кардани ҳисоб</a> ба таври ғайрибевосита ба муҳимии андозаи қатъчаҳо дар бодоранги кӯрон ишора мекунад.</p><><h2>Саволҳои маъмул (FAQ)</h2><h3>Чаро баргҳои пароти шӯрӣ зери риштаи таматчӣ зардшудаанд?</h3><p>Зардшудани баргҳо метавонад аз камии нитроген, камии оҳан ё беоҳиссии ба саъҳҳудҳои хокӣ ба вуҷуд омада бошад. Дар системаи таматчӣ, эҳтимоли камии нитроген ба сабаби ғайримӯвозбудани маҳлуқи куд баланд аст. Санҷиши pH-и маҳлуқи ғизоӣ ва таҳқиқи хок барои мавҷуд будани омилҳои беморивар тавсия дода мешавад.</p><h3>Оё имкони парвариши шаҳӣ дар хокҳои хеле вазнин мавҷуд аст?</h3><p>Бале, аммо бо мушкилоти бештар. Дар хокҳои вазнин гузаштани реша суст аст. истифодаи таҳороти балотар (одатан дар шакли навар) ва ҳамоҳангӣ беҳтар метавонад ин мушкилро ҳал кунад. Дар ин шароит чуқури реша бояд камтар бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-شاهی-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت شاهی با آبیاری قطره‌ای - تصویر 3"/><figcaption>усули парвариш намоиши парвариши обориши бачача ва таърихи обориши шаҳӣ</figcaption></figure><h3>Бетарин вақти ғалғидани бо системаи обориши бачача кӣ аст?</h3><p>Ғалғидани шаҳӣ одатан дар вақте сурат мегирад, ки раста ба пуррагии расида ва данаҳои он хушк шудаанд. Ин давра тақрибан аз 75 то 85 рӯз пас аз парвариш аст. То ҳангоме ки ғалғидан карда намедаред, оборишро идома диҳед, аммо доҳаҳои охиринро кам кунед, то данаҳо сахт шаванд.</p>\n<h2>Хулоса ва назари оянда</h2><p>Истифодаи дониши анъанавии парвариш бо технологияҳои пешрафтаи обориши маҳаллӣ монанди бачача ва навар, калиди дастёби шаҳии сифати баланд ва иктисоми бештар об аст. Кишовароне, ки ҷустуҷӯи беҳтарин истеҳсои сабзавотро мекунанд, бояд ба принсипҳои асосӣ монанди фосила, ғизои мувозинатнок ва тозагии филтрҳо диққат диҳанд. Барои дарк беҳтар, чӣ тавр аз ҳар гектар замин бо камтарин талафоти манбаъҳо фоида бароранд, омӯзиши манбаъҳои гуногун монанди <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%85%d8%a7%d8%b1%da%86%d9%88%d8%a8%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Иқтисоби ғалғидани марчуба дар як гектар: рухнамоии умумӣ ва омили таъсиррасонанда</a> Ва мақолаҳои мумтебиҳ метавонад назари интеллектуалиро дар баробари маҳсулоти растаниӣ дар шумо эҷод кунад. Ин манбаъҳо ба шумо кӯмак мекунанд, то бо дониши омилҳое, ки ба самаранозукӣ таъсир мерасонанд, барои мавсимҳои оянда тадбيري иқтисодитар доред.</p>','Сохтори умумии кӯтоҳи ғундӯзӣ бо обёрӣи қатқатӣ ва навар','Дар ин мақола маълумоти техникӣ оид ба ғунӣ кардани шаҳӣ бо системаҳои қатрагӣ ва нӯри тӯпӣ баррасӣ шудааст. Нуқтаҳои асосӣ дар бораи амиқии ғунӣ, дебит қатрагӣкунандаҳо, идоракунии хок ва пешгирии вайронии хатҳо пешниҳод шудаанд.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
