SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='rasid-hisobi-koshish-komelina-obari-qatragi' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'rasid-hisobi-koshish-komelina-obari-qatragi','rasid-hisobi-koshish-komelina-obari-qatragi-crop-246-tj');
