SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='farmoish-salat-lenta-steel' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'farmoish-salat-lenta-steel','farmoish-salat-lenta-steel-crop-247-tj');
