SET @resolved_slug=IF(@slug_conflict IS NULL,'farmondani-nazoroti-top-ha-dar-parvarischi-gushti-standard-ho','farmondani-nazoroti-top-ha-dar-parvarischi-gushti-standard-ho-crop-260-tj');
