SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='andozai-bargi-oshpaz-dar-gectar' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'andozai-bargi-oshpaz-dar-gectar','andozai-bargi-oshpaz-dar-gectar-crop-262-tj');
