SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='pepper-yield-ha-drip-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'pepper-yield-ha-drip-irrigation-guide','pepper-yield-ha-drip-irrigation-guide-crop-266-en');
