SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='cotton-yield-analysis-half-drip-line-method' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'cotton-yield-analysis-half-drip-line-method','cotton-yield-analysis-half-drip-line-method-crop-271-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'cotton-yield-analysis-half-drip-line-method-crop-271-en-a200af4d');
