SET @resolved_slug=IF(@slug_conflict IS NULL,'sanchishi-fazoi-pashutarzi-bo-usuli-nobai-tipi','sanchishi-fazoi-pashutarzi-bo-usuli-nobai-tipi-crop-271-tj');
