SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='farqiyati-jont-hurushoni-ghalaydor' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'farqiyati-jont-hurushoni-ghalaydor','farqiyati-jont-hurushoni-ghalaydor-crop-273-tj');
