SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'farqiyati-jont-hurushoni-ghalaydor-crop-273-tj-dc093466');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Чаро масоҳат байни шохобҳо дар ёввон муҳим аст?</h2>\n<p>Ёввон яке аз муҳимтарин ғузолҳои доимӣ мебошад, ки дар бисёр минтақаҳои Ҷумҳурии Исломии Эрон парвораҳӣ мешавад. Бо назардошти истеъмоли баланди об дар ҳар як хароҷ ва зарурати решаҳои амиқ ба дастрасии доимӣ ба намӣ, интихоби <strong>масоҳати мувофиқи шохобҳо</strong> маҳсули мувозинати байни тафреъи сармоягузории ибтидоӣ ва самаранокии дарозмуддат мебошад. Агар масоҳат байни шохобҳо аз ҳамдигар зиёд бошад, минтақаҳои хушк байни хатҳои парвораҳӣ ба вуҷуд меояд ва пӯшиши решаҳо кам мешавад. Баръакс, масоҳати хеле кам ба заҳмат кардани шохобҳо, зиёд шудани сарфари харидори қисмҳои пластикӣ ва ба вуҷуд овардани шароити мувофиқ барои бемориҳои занбӯруғӣ дар қисми таҷи растани мусоидат мекунад.</p>\n<p>Дар усули обёрӣи қатқатӣ, ҷараёни оҳистаи об ва ҳаракати кам дар минтақаи решаҳо боиси ин мешавад, ки тақсимоти намӣ хеле вобаста ба геометрияи хатҳои обёрӣ бошад. Бинобар ин, фаҳмистандҳои тавсияшуда барои ҷойгиршавии хатҳо (Row Layout) муҳим аст. Дар пай баррасии муфассалҳои техникӣ, рақамҳо ва оморҳои тавсияшуда ва нуқтаҳои иҷроӣ хоҳад шуд.</p>\n\n\n\n<h2>Стандартҳои техникӣ масоҳати шохобҳо дар навъҳои ёввон</h2>\n<p>Муайян кардани масоҳати хатҳои обёрӣ ба се омили асосӣ вобаста аст: навъҳои ёввон, амики решагирии моҳир ва шароити кӯдакӣ. Дар умум, растании ёввон системаи решаҳои амиқ дорад, ки метавонад то 3 то 5 метр амвол кунад, вале бештарин зичии решаҳои фаъол дар 60 сантиметр болои сатҳи замин ҷойгир аст. Бинобар ин, мақсади ҷойгиркунии шохобҳо, ба вуҷуд овардани конуси намӣ (Wetting Cone) аст, ки дар амики 30 то 50 сантиметр, хатҳо бо ҳамдигар мувофиқ карда шаванд.</p>\n<h3>Таъсири шудири рельс ва саршир бар пӯшиши намӣ</h3>\n<ul>\n<li><strong>Нуби 1/2 дюймӣ (12.7 миллиметр):</strong> Барои навъҳои наҷофи нӯрғоҳ (одатан навъҳои маҳаллӣ) тавсия дода мешавад. Ин нубӣ Дарозии бештар дорад ва кӯни намии васеътарро ташкил медиҳад. Фосилаи мувофиқ: 70 то 80 сантиметр.</li>\n<li><strong>Нуби 3/4 дюймӣ:</strong> Истифодаи ин нубӣ дар наҷоф камтар маъмул аст, магар дар шартҳои исботшуда, ки эҳтиёҷ ба об ва ғизо (фрут) хеле баланд бошад. Фосилаи мувофиқ: 90 то 100 сантиметр.</li>\n<li><strong>Нуби 1/2 дюймӣ бо ҳалқаҳои иловагӣ:</strong> Дар навъҳои навтар бо рушди тезтар, гоҳе аз нубиҳо бо ҳалқаи иловагӣ истифода мебаранд, то дарозии ҷойгиршавиро зиёд кунанд. Фосилаи мувофиқ: 60 то 70 сантиметр.</li>\n</ul>\n<p>Дарозии дарозии хок ва сатҳи бухоршавӣ низ ба фосилаи фосила таъсир мерасонад. Дар минтақаҳои гарм ва хушк ба мисоли ҷануби Эрон, фосилаҳои камтар (60-70 сантиметр) барои бухоршавии баландтар аз сатҳи хок байни нубиҳо донишмандонар аст, то намӣ байни хатҳои нигоҳ дошта шавад.</p>\n\n<h2>Алоқаи фосилаи нуби тибе бо нафашкунӣ ва дарори наҷоф</h2>\n<p>Сохторкунӣи ҷадвалҳои кӯкар (Row Layout) бояд бо намунаҳои оғоз (drip tapes) мувофиқат кунад. Дар ғунд кардашавии люцерна одатан аз ғунд кардашавии хаттӣ (масоҳати калон) истифода мебаранд. Агар дар ғунд, байни ду хати ғунд як намунаи drip Tape ҷойгир шавад, масоҳати drip Tape айнан ба масоҳати хатҳои ғунд баробар мешавад. Ин усул (One-tape method) иқтисодӣтарин ҳолат аст, зеро танҳо як намуна дар ҳар ду хати ғунд ҷойгир мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-یونجه-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت یونجه: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop люцерна</figcaption></figure>\n<p>Баръакс, усули Two-tape method ҷойгир кардани ду намунаи drip Tape байни ду хати ғундро дар бар мегирад. Ин усул барои люцерنا, ки дар солҳои аввал зичии дон ғундшавӣ доранд, маъмул аст, зеро суръати пӯшиши ғаллоғӣро зиёд мекунад ва сояи муносибро мекуняд. Дар ин ҳолат, масоҳати намунаҳои drip Tape аз якдигар бояд ҳадди аққал 40 сантиметр бошад, то фишори механикии решаҳо бар намунаҳо пешгирӣ шавад. Инчунин, диққат диҳед, ки намунаҳои drip Tape-и зерзаминӣ дар люцерна истифодаи маҳдуд доранд, зеро решаҳои люцерна бо гузашти вақт бар намунаҳо меоянд ва бастории физикӣ ташкил медиҳанд. Бинобар ин, намунаҳои сатҳӣ барои люцерна афзалият доранд.</p>\n<p>Барои дарки беҳтарини намунаи паҳншавии нам, метавон ба мақолаи дастурашавии масоҳати drip Tape барои ҷуворӣ дар як гектар замин нигаронида шавад, зеро принсипҳои геометрии конуси нам дар ҳаргизҳо, ки худгуншии монанди люцерна доранд, низ эътибор медиҳанд (<a href="https://navar-abyari.ir/%D9%81%D8%A7%D8%B5%D9%84%D9%87-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%B0%D8%B1%D8%AA-%D8%B9%D9%84%D9%88%D9%81%D9%87-%D8%A7%DB%8C-%DA%A9%D8%A7%D8%B4%D8%AA-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Масоҳати drip Tape барои ҷуворӣ дар як гектар замин</a>). Ин намуна нишон медиҳад, ки чӣ гуна кунҷи ҷориги об ва намуди хок радиуси тозакунии навро муайян мекунад.</p>\n\n\n\n<h2>Нуқтаҳои амалӣ дар ҳисоб ва иҷрои drip Tape барои люцерна</h2>\n<ol>\n<li><strong>Муайян кардани масоҳат дар асоси намуди хок:</strong> Дар хокҳои гилӣ (ломи), радиуси ғусари об камтар аст ва масофаи байни сипҳои абкунӣ бояд наздиктар бошад (тақрибан 60 сантиметр). Дар хокҳои шаброки ғусар тезтар аст ва масофаро то 90 сантиметр зиёд кардан мумкин аст.</li>\n<li><strong>Роҳнамоӣ барои сипҳои абкунӣ:</strong> Сурати сипҳои абкунӣ бояд нишон дошт бо ҳаракати замин ҳосилшавӣ дорад, то аз ҷамъшавии об дар минтақаҳои поёнӣ пешгирӣ кунад. Ин раванд баробаргардии масофаи байни сипҳои абкунӣ дар тамоми зери ҷой мекунад.</li>\n<li><strong>Ғизокунии буттаҳо (Fertigation):</strong> Азбаски яфтув дар соли аввал ба калий ва нитроген ниёзи зиёд дорад, сипи абкунӣ бояд рост дар хати ғизокунии буттаҳо ҷойгир бошад. Агар масофаи сипҳои абкунӣ зиёд бошад, ҷабири калий аз тавассути рӯбҳои паҳлуӣ паст мешавад. Барои дониши бештар дар бораи арқамҳо, шумо метавонед ба дастури ҷамъи буттаи яфтув нишон баред.<a href="https://navar-abyari.ir/%d8%a7%d9%86%d9%88%d8%a7%d8%b9-%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d9%88-%d8%b9%d9%85%d9%84%da%a9%d8%b1%d8%af-%d9%87%d8%b1%da%a9%d8%af%d8%a7%d9%85/">Навъҳои абкунӣ ва кори ҳар яки онҳо</a>).</li>\n<li><strong>Пӯшидани сипҳои абкунӣ:</strong> Пас аз пайкунӣ, то баландии 10-15 сантиметр аз сатҳи хок бар сипҳоро пур кунед. Ин кор ба он оварда мерасонад, ки масофаи сипҳои абкунӣ аз нуқтаи назаркунӣ пайдо шаванд ва аз партофтани сипҳо бо шамол пешгирӣ кунад. Пӯшидан нигоҳдории ҳарорати рӯбҳо ва кам кардани бозхӯрӣро таъмин мекунад.</li>\n</ol>\n<p>Инчунин, агар шум мехоҳед аз усулҳои ивазкунанда мисли обории боронӣ истифода баред, бояд донед, ки ҷунгун ба сабаби доштан баргҳои васеъ, ба бемориҳои таҷ бои муносиб аст ва системаи чучаишӣ бо фосилаи назоратшудаи нӯраи чучаишӣ беҳтарин интихоб аст. Барои муқоиса, метавонед ба мақолаи «Ҷангунҳои хушкӣ, нӯраи чучаишӣ (шарҳ: нуқтаҳои муҳим дар нӯри чучаишӣ)» ва «Нуқтаҳои муҳим дар истифода аз нӯраи чучаишӣ» муроҷиат кунед, то хатогиҳои маъмулро дар иҷро кам созед.</p>\n\n\n\n<h2>Муқоисаи самаранокии: фосилаҳои гуногун вобаста ба ҳамдигар</h2>\n<p>Барои фаҳмиши бештари таъсири фосилаи нӯраи чучаишӣ ба истеҳсоли об ва зиёдшавии ҳосилот, дар jadвали зерин муқоисае байни ду сценарияи маъмул пешниҳод шудааст. Ин шумҳо асос бар дераҳои майданӣ дар минтақаҳои нимхушки Эрон ва бо фарзияи сарпешолии 2 литр дар соат барои ҳар метр нӯра (бо фосилаи 20 сантиметр) ҳисоб карда шудаанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-یونجه-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت یونجه: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>Fосилаи нӯраи чучаишӣ тарҳбандии рах халҳо ҷунгун</figcaption></figure>\n<table>\n<tr>\n<th>Меъёр</th>\n<th>Фосилаи 60 сантиметр (фурӯравӣ)</th>\n<th>Фосилаи 90 сантиметр (пурҳашаматӣ/камшавӣ)</th>\n</tr>\n<tr>\n<td>Шумораи нӯраҳо дар ҳектар</td>\n<td>Тақрибан 1660 метр</td>\n<td>Тақрибан 1110 метр</td>\n</tr>\n<tr>\n<td>Хароҷоти ибтидоии навар (%)</td>\n<td>100% (асос)</td>\n<td>Тақрибан 67%</td>\n</tr>\n<tr>\n<td>Пӯшиши намии решаҳо (% самаранокии баромад)</td>\n<td>Аз 95% то 100%</td>\n<td>70% (бо камшавии боронбарӣ дар минтақаҳои гармивӣ)</td>\n</tr>\n<tr>\n<td>Хатари бемории тоҷ/камар</td>\n<td>Пасттар (хуки хунуктар ва намии ягонаҷ)</td>\n<td>Баландтар (ҳавоҳои хушк байни шараҳҳо)</td>\n</tr>\n<tr>\n<td>Давраи абпандӣ дар ҳар маротиба</td>\n<td>Кӯтоҳтар (бо сабаби оқими доимӣ, аммо роҳи кӯтоҳтар)</td>\n<td>Баландтар (барои ҷуброн кардани масофа)</td>\n</tr>\n</table>\n<p>Маълумот нишон медиҳанд, ки кам кардани масофаи бозии таспаннӣ то 60 сантиметр, гарчанде ки хараҷи аввалиро зиёд мекунад, аммо аз ҷиҳати содиршавии оромӣ ба ҳар километр бозӣ, бо сабаби ягонаҷшавии намӣ ва кам шудани зарби гармии бутта, манфиати иқтисодии бештарро дар сафҳои якум ва дуюм дорад. Бинобар ин, дар шароити хушксол, ин масофаи кӯтоҳ нақши зиндагардонро дар нигоҳ доштани фаршпарии бутта иҷро мекунад.</p>\n<p>Ҳангоми гуфтугӯ оид ба содиршавии гектарии буттаҳои донии ҷо, баъзан муқоиса бо буттаҳои дигар, ба монанди ҷав амал мекунад. Барои фаҳмидани фарқияти содиршавии гектарӣ дар шароити монанд, шумо метавонед ба роҳнамои ҳосили ҷав дар як гектар (<a href="https://navar-abyari.ir/oat-yield-per-hectare-guide/">oat yield per hectare guide</a>Бояед дид кунед. Гарчанде ки вилли наботи доимӣ мебошад, вале намуди рушди решаҳо ва ниёзаш ба об дар муҳандисии системаи обёркунӣ, муодилаҳои монанд бо дигар набототи ноқил дорад.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Ба оё ҳангоми интизоми вилли аз шити банди зерзистӣ истифода бурдан мумкин аст?</h3>\n<p>Не, тавсия намешавад. Решаҳои вилли ба осонӣ бо шити зерзистӣ ғавғоӣ мекунанд ва дар марҳилаи дуюми рушд, обструксияи физикии шити-ро эҷод мекунанд. Шитҳои сатҳӣ бо қатти 10-сантиметрии хок беҳтарин имконият барои нигоҳ доштани фосилаи шит ва суръати ба дор овардани решаҳо ба намнокӣ мебошад.</p>\n<h3>Фосилаи шити бандӣ дар хокҳои гармболақ бо кадом меъёр муайян карда шавад?</h3>\n<p>Дар хокҳои гармболақ, ғавғоии амудии об бештар аст ва радиуси кунҷӣ кам мешавад. Бинобар ин, фосилаи шити бандӣ бояд кам карда шавад (тамаи 50-60 сантиметр), то инки конуси намнокӣ дар чуқурии зарурӣ фаро гирифта шавад. Инчунин, дар ин хокҳо, обёркунҳои бешумор бо ҳаҷми камро ба ҷои обёркунҳои вазнин ва камдавом истифода мекунанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-یونجه-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت یونجه: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop вилли</figcaption></figure>\n<h3>Ба оё фосилаи шити бандӣ барои шаклҳои сафед вилли (Sainfoin) бо вилли одамонан одии фарқ мекунад?</h3>\n<p>Бале, ғоҳишҳои сабзодод оддӣ решаҳои сахтр ва чуқуртар доранд. Дар ин ҳолат, фосилаи хатҳои обёрӣро то 10 сантиметр зиёд кардан мумкин аст, зеро решаҳои паҳлӯии онҳо қобилияти ҷустуҷӯии нам дар фосилаҳои бештарро доранд. Аммо барои лӯбиҳо, ки ба сӯи боло меафрӯяд, фосилаи камтар ва маҳдудшуда самараноктар аст.</p>\n\n<h2>Хулоса</h2>\n<p>Интихоби фосилаи хатҳои обёрӣ дар кишт кардани лӯбиҳо як қарордоди кӯпҳаҷаҷо аст, ки омилҳои хокӣ, иқлимӣ ва иқтисодиро дар бар мегирад. Стандардҳои умумӣ нишон медиҳанд, ки фосилаи 70 то 90 сантиметр барои аксари хокҳои ошёнанок ва силтӣ (сазиқӣ) дар минтаҳои марказии Эрон нуқтаи оптималӣ аст. Бо назардошти асосҳои тарҳрезии хатҳои ғалат ва пӯшиши реша, аз хатҳои обёрӣ бо дебит мувофиқ истифода баред. Рӯйхат гирифтани асосҳои муҳандисии сода, монанди пӯшиши мувофиқи хокӣ хатҳо ва самтдоии перпендикуляр ба шидат, умри фоидаи система ва сифати нам дар кӯҳи рурасаро таъмин мекунад.</p>\n<p>Дар охир, мониторинги мунтазами истеҳсоли хатҳои обёрӣ ва танзими фишори баромад, калиди устуворӣ аст. Бо оптимизатсияи фосилаи хатҳои обёрӣ, ҳам аз вайроншавии потенсиали истеҳсолии лӯбиҳо пешгирӣ карда мешавад ва ҳам истеъмоли об ба сатҳи стандартӣ мерасад. Барои маълумоти иловаӣ дар бораи тарҳрезии умумии система, омӯзиши дастиёр (омодасоз)-и ғоҳиши лӯбиҳо ва мақолаҳои алоқаманд бо геометрияи хатҳои обёрӣ дар дигар ғоҳишҳо тавсия дода мешавад.</p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%86%DA%A9%D8%A7%D8%AA-%D9%85%D9%87%D9%85-%D8%AF%D8%B1-%D9%87%D9%86%DA%AF%D8%A7%D9%85-%D8%A7%D8%B3%D8%AA%D9%81%D8%A7%D8%AF%D9%87-%D8%A7%D8%B2-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8/">D986DAA9D8A7D8AA D985D987D985 D8AFD8B1 D987D986DAAFD8A7D985 D8A7D8B3D8AAD981D8A7D8AFD987 D8A7D8B2 D986D988D8A7D8B1 D8AADB8CD9BE D8A2D8A8</a></p>','Фарқияти байни ҷунтҳои навриси хурӯҷонӣ дар ғалладорӣ: Мақоми тавсияшуда','Дар ин мақола шумо бо муҳимияти оптимизатсияи масоҳати нури тип боғзорҳои якунҷаъ, таъсири он ба решаандозӣ, самаранокии оборӣ ва кам кардани махраҷот шинос мешавед.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
