SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='migor-sabziji-yodgoriya-tolov' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'migor-sabziji-yodgoriya-tolov','migor-sabziji-yodgoriya-tolov-crop-276-tj');
