SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='fosila-i-shiziri-qulla-dar-kinva-munsiibati-tayinshuda' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'fosila-i-shiziri-qulla-dar-kinva-munsiibati-tayinshuda','fosila-i-shiziri-qulla-dar-kinva-munsiibati-tayinshuda-crop-280-tj');
