SET @resolved_slug=IF(@slug_conflict IS NULL,'iqtidori-hoshi-kuzi-kunudi-bog-ghishtpyab-tajik','iqtidori-hoshi-kuzi-kunudi-bog-ghishtpyab-tajik-crop-286-tj');
