SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='pest-ravshanbar-obiari-qutara' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'pest-ravshanbar-obiari-qutara','pest-ravshanbar-obiari-qutara-crop-288-tj');
