SET @resolved_slug=IF(@slug_conflict IS NULL,'onion-seed-rate-hectare-comprehensive-cultivation-drip-sdi-guide','onion-seed-rate-hectare-comprehensive-cultivation-drip-sdi-guide-crop-290-en');
