SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='mirkori-tohi-bodirka-dar-hektar' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'mirkori-tohi-bodirka-dar-hektar','mirkori-tohi-bodirka-dar-hektar-crop-290-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'mirkori-tohi-bodirka-dar-hektar-crop-290-tj-a1488dd2');
