SET @resolved_slug=IF(@slug_conflict IS NULL,'idorakuniji-zararrasonho-shpinat-sistemi-obori-anori','idorakuniji-zararrasonho-shpinat-sistemi-obori-anori-crop-296-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'idorakuniji-zararrasonho-shpinat-sistemi-obori-anori-crop-296-tj-2b70290e');
