SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='spinach-cultivation-cost-drip-tape-hectare' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'spinach-cultivation-cost-drip-tape-hectare','spinach-cultivation-cost-drip-tape-hectare-crop-298-en');
