SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='kharchati-karp-sabazi-bo-nurai-darak' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'kharchati-karp-sabazi-bo-nurai-darak','kharchati-karp-sabazi-bo-nurai-darak-crop-298-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'kharchati-karp-sabazi-bo-nurai-darak-crop-298-tj-11f89aa7');
