SET @resolved_slug=IF(@slug_conflict IS NULL,'sampeyoni-ghallai-quruqi-dar-hektar-bo-sistemanava-kn','sampeyoni-ghallai-quruqi-dar-hektar-bo-sistemanava-kn-crop-301-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'sampeyoni-ghallai-quruqi-dar-hektar-bo-sistemanava-kn-crop-301-tj-957dcef1');
