SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='fenug-yield-per-hectare-tipir-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'fenug-yield-per-hectare-tipir-irrigation-guide','fenug-yield-per-hectare-tipir-irrigation-guide-crop-304-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'fenug-yield-per-hectare-tipir-irrigation-guide-crop-304-en-38c6ac64');
