SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='comprehensive-garlic-yield-drip-line-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'comprehensive-garlic-yield-drip-line-guide','comprehensive-garlic-yield-drip-line-guide-crop-314-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'comprehensive-garlic-yield-drip-line-guide-crop-314-en-46ede7ef');
