SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='vegetable-yield-hectare-drip-tapes-productivity-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'vegetable-yield-hectare-drip-tapes-productivity-guide','vegetable-yield-hectare-drip-tapes-productivity-guide-crop-316-en');
