SET @resolved_slug=IF(@slug_conflict IS NULL,'rasmi-parvarishi-gandum-bo-systema-hobi-rosh-katrina-navar','rasmi-parvarishi-gandum-bo-systema-hobi-rosh-katrina-navar-crop-318-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'rasmi-parvarishi-gandum-bo-systema-hobi-rosh-katrina-navar-crop-318-tj-ba1c9a89');
