SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='binokunii-changa-ba-navori-tpe-noqthoi-osoni' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'binokunii-changa-ba-navori-tpe-noqthoi-osoni','binokunii-changa-ba-navori-tpe-noqthoi-osoni-crop-320-tj');
