SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='drip-tape-maintenance-okra-irrigation-efficiency' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'drip-tape-maintenance-okra-irrigation-efficiency','drip-tape-maintenance-okra-irrigation-efficiency-crop-324-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'drip-tape-maintenance-okra-irrigation-efficiency-crop-324-en-4179c349');
