SET @resolved_slug=IF(@slug_conflict IS NULL,'darmand-oshkorii-navroii-tip-baroiii-parhezii-okropoli','darmand-oshkorii-navroii-tip-baroiii-parhezii-okropoli-crop-324-tj');
