SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='nigohuborii-navor-tib-kishaki-kinoa' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'nigohuborii-navor-tib-kishaki-kinoa','nigohuborii-navor-tib-kishaki-kinoa-crop-325-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'nigohuborii-navor-tib-kishaki-kinoa-crop-325-tj-b03f4f41');
