SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='farasoni-karmoni-karbashivi-karbon' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'farasoni-karmoni-karbashivi-karbon','farasoni-karmoni-karbashivi-karbon-crop-328-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
