SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='onion-maintenance-drip-tape-irrigation-principles' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'onion-maintenance-drip-tape-irrigation-principles','onion-maintenance-drip-tape-irrigation-principles-crop-330-en');
