SET @resolved_slug=IF(@slug_conflict IS NULL,'rohnomo-yi-parhtobi-koch-oboriqa-tahuk-to-ijmoz','rohnomo-yi-parhtobi-koch-oboriqa-tahuk-to-ijmoz-crop-331-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'rohnomo-yi-parhtobi-koch-oboriqa-tahuk-to-ijmoz-crop-331-tj-606506c7');
