SET @resolved_slug=IF(@slug_conflict IS NULL,'harajati-kadu-kashi-sarminyob-bo-ruviro-vale-yek-gektar','harajati-kadu-kashi-sarminyob-bo-ruviro-vale-yek-gektar-crop-333-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'harajati-kadu-kashi-sarminyob-bo-ruviro-vale-yek-gektar-crop-333-tj-5083aa89');
