SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='coriander-seed-rate-hectare-drip-teflon-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'coriander-seed-rate-hectare-drip-teflon-irrigation-guide','coriander-seed-rate-hectare-drip-teflon-irrigation-guide-crop-335-en');
