SET @resolved_slug=IF(@slug_conflict IS NULL,'miqdor-i-bur-i-tritikale-ru-ektar','miqdor-i-bur-i-tritikale-ru-ektar-crop-338-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'miqdor-i-bur-i-tritikale-ru-ektar-crop-338-tj-d95aadf3');
