START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-340' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-340:tg-TJ' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='miqdori-bozori-chovon-dar-hektar-rahnomaii' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'miqdori-bozori-chovon-dar-hektar-rahnomaii','miqdori-bozori-chovon-dar-hektar-rahnomaii-crop-340-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'miqdori-bozori-chovon-dar-hektar-rahnomaii-crop-340-tj-6c6b28d2');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Коришти ҷавдор ҳамчун рӯяи бисёрсафаркӯш ва устод як аз интихоботи маърули барои деҳқонҳо мебошад. Муайян кардани <strong>миқдори бӯди ҷавдор дар ҳектар</strong> масъалаи ҳассос ва муҳим аст, ки бевосита ба хароҷот ва маҳсули ниҳоӣ таъсир мерасонад. Дар ин раҳнамасо мо раванди ҳисобкунии дурусти бӯдро баррасӣ мекунем ва онро бо системаҳои обкорӣ-нано ва қатрагӣ алоқаманд мекунем, то ки деҳқонии бартар пурсоҷӣ кунем. Фаҳмиши амиқ дар бораи алоқаи байни зичии партов ва ниёзҳои об, калиди муваффақият дар парвариши ин рӯя мебошад.</p>\n<p>Ҷавдор ба сабаби решаҳои чуқур ва устодии баланд нисбат ба шароитҳои гуногуни иқлимӣ имконияти партов дар бисёр минтаҳоро дорад. Аммо бе диққат ба шароитҳои хок ва обуҳаво, интихоби миқдори мувофиқи бӯд натиҷаи баръакс дошта метавонад. Дар поён, мо тамоми ҷанбаҳои ин мавзӯъро бо усули ихтисосӣ баррасӣ мекунем.</p>\n<h2>Амилҳое, ки ба муайян кардани миқдори бӯди ҷавдор таъсир мерасонанд</h2>\n<p>Муайян кардани дақиқи <strong>миқдори бӯди ҷавдор дар ҳектар</strong> вобаста ба бисёр амилҳост, ки бо якдигар дар таъмиланданд. Муҳимтарини ин амилҳо сифати бӯд, шароити хок, усули партов ва мақсади корез (парҳезгории чорво ё пӯлод) мебошад.</p>\n<ul>\n<li><strong>Сифати тохук:</strong> Дарсади нӯмӯдан ва тозагии тохук бевосита ба миқдори тоҳукҳои лозима таъсир мерасонад. Тоҳуки сифатбахштар ба шумораи камтар ниёз дорад.</li>\n<li><strong>Шароити хок:</strong> Дар хокҳои сабук, метавонад ба зичии камтари тоҳук ниёз бошад, то рақобат барои об кам шаванд.</li>\n<li><strong>Рӯҳи коркард:</strong> Коркарди дастӣ ё бо дастгоҳҳои пешрафта дақиқат паҳн кардани тоҳукро иваз мекунад.</li>\n<li><strong>Ҳадафи коркард:</strong> Салот одатан барои коркарди беш аз чорикҳо ниёз дорад, ки ба коркарди пӯшишбахш мутноқан аст.</li>\n</ul>\n\n<h2>Ҳисобкунии амалӣ: мо чӣ қадар бештар бобуҷанд (bodarra) лозим аст?</h2>\n<p>Барои ҳисобкунии дақиқ <strong>миқдори бешт бодал (bodarra) дар як гектар</strong>метавон аз формулаҳои асосӣ истифода бурд. Як гектар баробари 10000 метри квадратӣ аст. Бо назардошти масофаи ноб (байни сатрҳо) ва масофа дар сатр, шумораи лӯли ё сӯрохии лозимаро ҳисоб кардан мумкин аст.</p>\n<ol>\n<li>Масоҳати ҳар як сатро муайян кунед.</li>\n<li>Шумораи сатрҳои имконпазирро дар тамоми замин ҳисоб кунед.</li>\n<li>Шумораи сӯрохиро дар ҳар сатрро вобаста ба масофаи интихобшуда муайян кунед.</li>\n<li>Шумораи умумии сӯроҳро дар вазни ҳар як сӯрох зарб кунед, то миқдори лозими бешт (bodarra) ба даст овард.</li>\n</ol>\n<p>Одатан миқдори бови ҷудор барои як шикувкшиҳои стандартии минтақаҳои мулоим аз 150 то 250 километр дар гектар тағйир меёбад. Ин рақамҳо вобаста ба нусхашунагузорӣ ва шартҳои маҳаллӣ иваз мешаванд. Агар аз системаи оросиши қатрагӣ истифода шавад, назорати беҳтар ба захираҳои об метавонад ба кам шудани ниёз ба паҳнкунии зиёди бов дарҳамогӣ кӯмак расонад, зеро рақобати фаъолигиҳӣ барои намакӣ кам мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-چاودار-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر چاودار در هکتار: راهنمای جامع - تصویر 1"/><figcaption>Seed rate per hectare crop чаудар</figcaption></figure>\n<h2>Таъсири системаҳои оросиш бар зичии шикувкшигӣ</h2>\n<p>Оросиши қатрагӣ ва нӯраи тип инқилоб дар шакли кишоварӣ ба амал овардааст. Вақте муайян карда... <strong>Миқдори тоҳи ражак дар гектар</strong>, бояд нодидагузорӣ кард, ки кадом системаи обёрӣ истифода мешавад. Дар обёрӣи қатрагӣ имконияти назорати дақиқ миқдори об ба ҳар як лӯла ё saf мавҷуд аст. Ин имконро медиҳад, ки аз зичии баландтари тоҳ истифода барем, зеро стресс камтари об барои растониҳо пайдо мешавад.</p>\n<p>Баръакс, дар обёрӣи боронии анъанавӣ, рақобати шадид барои кашидани об метавонад ба заифӣи растониҳо оварда расонад. Бинобар ин, барои кашт кардани ражак бо системаи навоси нип, тавсия дода мешавад, ки зичии тоҳро ба миёна нигоҳ доред. Барои маълумоти беш дар бораи принсипҳои обёрӣ, метавонед ба мақолаҳои иловагӣ монанди <a href="https://navar-abyari.ir/important-tips-drip-tape-irrigation/">Нуқтаҳои муҳими обёрӣи навоси нип</a> Манроҳ кунед. Ин мавзӯъҳо якдигарро тапҳофӣ мекунанд.</p>\n\n<h2>Омилони амалӣ барои деҳқонон</h2>\n<p>Иҷрои дурусти парҳизкунии ҷавдар лозим аст. Ба ин омилҳо таваҷҷуҳ диҳед. Ин омилҳо барои парҳизкунии дурусти ҷавдар заруранд.</p>\n<ul>\n<li><strong>Омодакунии замин:</strong> Замин бояд пурраи шикм шуда бошад, то ки бугӣ ба таври яксон паҳн карда шавад.</li>\n<li><strong>Давомнокӣ:</strong> Ҷавдар барои парҳизкунии баҳорӣ-субҳӣ аст. Парҳизкунӣ дар вақти мувофиқ, барои парҳизкунии бештар мутобиқ аст.</li>\n<li><strong>Истифодаи буги мулоҳиза:</strong> Бигарро бояд аз марказҳои маъруф ва эътимоднок харид шуда, таъмин карда шавад, то аз набудани заҳрамӣ кафолат дошта шавад.</li>\n<li><strong>Фармоиш баъд аз ниҳолзанӣ:</strong> Обёрӣи аввалин бояд фавран анҷом дода шавад, то бигарро тар карда шавад ва раванди ҷавронӣ оғоз гардад.</li>\n</ul>\n<p>Инчунин, интихоби системаи мувофиқи обёрӣ вобаста ба намуди замин зарур аст. Дар заминҳои чинӣ, обёрӣи қатрагӣ барои пешгирии хиробшавӣ ва намӣи номувофиқ хеле тавсия дода мешавад. Дар шартҳои мазкур, камшавии <strong>Мигдор бигарҳои чодар дар гектар</strong> то ҳадди ақал, фазои бештарро барои рушди решаҳо эҷод мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-چاودار-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر چاودار در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Дараҷаи бигар дар гектар ғаламоти чодар</figcaption></figure>\n<h2>Корбаст ва ҳосили чодар</h2>\n<p>Мақсади охирин аз парвариши ҷавдор расидан ба самаранокии иқтисодии муносиб аст. Миқдори бози истифодашуда, ниҳоят ба вазни хуши ҳар метри мураббаъ таъсир мерасонад. Ёке таҳқиқот нишон дод, ки зиёд шудани зичии раҳонҳо аз ҳадди оптималӣ, метавонад боиси кам шудани вазни ҳар ниҳол аз сабаби камбудии рӯшноӣ ва манбаъҳо гардад. Бинобар ин, парҳези зиёд ҳамеша мусбат нест.</p>\n<p>Барои беҳтар дарёфтан самаранокии раҳонҳо, метавонед бо мавзӯи дигар чунин <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%B3%D8%A8%D8%B2%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">миқдори гирифтани сабзоти дар ҳектар</a> тақсимоти муқоисавӣ дошта бошед. Ҷавдор ҳамчун хӯроквор, самаранокии худро дар воҳиди сатҳ пешниҳод мекунад.</p>\n\n<h2>Саволҳои маъмулашуда (FAQ)</h2>\n<h3>1. Кам ё зиёд кардан миқдори тавсияшудаи бози кабуд чӣ натиҷа дорад?</h3>\n<p>Кам шудани миқдори бози боиси кам шудани пӯлоди бӯдҳо ва зиёд шудани ҳашорот мегардад. Зиёд шудани наздики миқдори бози ҷавдор дар ҳектар, боиси рақобати шадид ва кам шудани вазни ҳар ҳосил мегардад.</p>\n<h3>2. Оё миқдори бози дар обёрӣ поёнӣ бо баронавӣ фарқ дорад?</h3>\n<p>Бале. Дар ошориши қатқатӣ (сачинӣ) ба сабаби дақиқияти баландтар, метавон аз зичии каме зиёдтар истифода бурд. Дар ошориши барандӣ, ба сабаби нодақиқии тақсими намнокиҳо, тавсия мешавад, ки зичӣ камтар бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-چاودار-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر چاودار در هکتار: راهنمای جامع - تصویر 3"/><figcaption>Нормаи боби Ҷоваро вайрон кардан. Нормаи боби барои ҳар гектар човар</figcaption></figure>\n<h3>3. Беҳтарин фасли парвариши човар кай аст?</h3>\n<p>Човар одатан ба тирамоҳ (ду ҳафта пеш аз яхбандии шадид) ё бабӯҳи барзиёд кунҷшуда парвариш карда мешавад. Вақти парвариш бояд вобаста ба иқлими минтақа танзим шавад.</p>\n<h3>4. Чӣ қадар бобӣ дар ҳар чуқура парвариш карда мешавад?</h3>\n<p>Одатан 2 то 3 дона бобӣ дар ҳар чуқура парвариш карда мешаванд, то аз рақобати камшохӣ пешгирии шуд. Сипас, пас аз ағбаи асосӣ, гиёҳҳои заиф отрофта мешаванд.</p>\n<h2>Хулоса</h2>\n<p>Муайянкунии дақиқ <strong>Нерӯи ғаллаи рожин дар як гектар</strong> Ин як раванди фаъол аст, ки баррасии ҳамаи қисмҳои системаро лозим мекунад; аз сифати ғалла то намуди оварӣ. Бо истифода аз оварии қатрагӣ ва шитобзори банд, шумо метавонед назорати беҳтари захираҳои обро дар даст доред ва бинобар ин, стратегияи зичии ғалларо пуррақимма карда, мавридат кунед. Масҳавати моҳирони маҳаллиро пеш аз ғалларо интихоб кардан баъди пайдо шудани аврунаи мувофиқ барои заминаатон тавсия мешавад. Дар интиҳо, боз ёдгирӣ мешавад, ки барои идоракунии беҳтар раванди ҳаёти растаниҳо, мавзӯъҳои монанди аллергияҳои ғизоӣ (барои истифодаи инсонӣ) бояд дар назар гирифта шаванд, гарчанде ки ин мавзӯъ барои рожин камтар маъмул аст, зеро бештар барои хӯроки чорво ифода меёбад. Инчунин, муқоиса бо миқдори ғаллаи салат метавонад фарқро равшантар нишон диҳад, зеро салат як наъеҳи парранда мебошад ва зичии ғаллаи он дигар аст.</p>\n<p><strong>Маводи алоқаманд:</strong> <a href="https://navar-abyari.ir/kmyt-bthar-aladls-lal-haqtar/">kmyt bthar aladls lal haqtar</a>, <a href="https://navar-abyari.ir/%d8%aa%d9%86%d8%a7%da%98-%d9%be%db%8c%d8%a7%d8%b2-%d8%b3%d9%81%db%8c%d8%af-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Нерӯи луғби сафед дар як гектар</a></p>','Miqdori bozori chovon dar hektar: Rahnomaii poygo va olimi','Ошноӣ ба асосҳои муайян кардани миқдори боғи чӯдодар, омили таҳия ва афзоиш, ва тартиб баҳисоби ин раванд бо истифода аз технологияҳои ҳозираи ҳарорат.','publish','closed','closed',@resolved_slug,NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @resolved_conflict IS NULL;
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @resolved_conflict IS NULL,LAST_INSERT_ID(),NULL));
