SET @resolved_slug=IF(@slug_conflict IS NULL,'narkhi-kortishi-pustari-bo-lenta-dar-hektar-tahlil-vay-nuqotay-asosi','narkhi-kortishi-pustari-bo-lenta-dar-hektar-tahlil-vay-nuqotay-asosi-crop-341-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'narkhi-kortishi-pustari-bo-lenta-dar-hektar-tahlil-vay-nuqotay-asosi-crop-341-tj-a3ce3c0b');
