SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='pest-disease-control-pennywort-drip-tie-irrigation' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'pest-disease-control-pennywort-drip-tie-irrigation','pest-disease-control-pennywort-drip-tie-irrigation-crop-343-iraq');
