SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='kokshavii-purra-dar-borai-obdori-dar-navi-qatra' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'kokshavii-purra-dar-borai-obdori-dar-navi-qatra','kokshavii-purra-dar-borai-obdori-dar-navi-qatra-irr-01-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'kokshavii-purra-dar-borai-obdori-dar-navi-qatra-irr-01-tj-a5a080b6');
