SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='node-irrigation-guide-principles-benefits-implementation-tips' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'node-irrigation-guide-principles-benefits-implementation-tips','node-irrigation-guide-principles-benefits-implementation-tips-irr-05-en');
