SET @resolved_slug=IF(@slug_conflict IS NULL,'kumarav-mukammali-obborbiy-marksii','kumarav-mukammali-obborbiy-marksii-irr-09-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'kumarav-mukammali-obborbiy-marksii-irr-09-tj-96c1294d');
