INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола бо худ ошно мешавед бо асосҳои интихоб ва оптимизатсияи системаҳои обёрдоии қатрагӣ ва навори Титл барои оромӣ. Ҳамин тавр, шумо метавонед боҳалбонӣ иҳтиёт шавед.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
