SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='nuri-tipi-va-qatqatnashuvi-o-rnatish-qollanmasi' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
