INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Барои фаҳмиши арзиши лӯлаи бачадори 75 мм дар ҳавзаи деҳқонӣ, мо ҳисобкунии дақиқи сарфа, хурудоти нақлиёт ва молиявияни ҳарифро овардакунда, дастрасӣ ба молиявияни деҳотро тавсиф мекунад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','Сарфаи лӯлаи бачадори 75 миллиметр дар деҳот: ҳисобкунии дақиқ барои молиявии деҳқонӣ' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
