SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='naso-hama-goyana-nolai-pahlui-125mm-taqatir-tib' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'naso-hama-goyana-nolai-pahlui-125mm-taqatir-tib','naso-hama-goyana-nolai-pahlui-125mm-taqatir-tib-prod-018-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'naso-hama-goyana-nolai-pahlui-125mm-taqatir-tib-prod-018-tj-9f934926');
