SET @resolved_slug=IF(@slug_conflict IS NULL,'rahomon-nigohubin-ghami-shinaz-75-mm-sitema-hoi-obori-tamatka','rahomon-nigohubin-ghami-shinaz-75-mm-sitema-hoi-obori-tamatka-prod-025-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'rahomon-nigohubin-ghami-shinaz-75-mm-sitema-hoi-obori-tamatka-prod-025-tj-48aa1e2e');
