SET @resolved_slug=IF(@slug_conflict IS NULL,'komak-porra-andozaziri-va-intixobi-ruloni-tibi-20-sm-baroy-dehqoron','komak-porra-andozaziri-va-intixobi-ruloni-tibi-20-sm-baroy-dehqoron-prod-026-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'komak-porra-andozaziri-va-intixobi-ruloni-tibi-20-sm-baroy-dehqoron-prod-026-tj-82ee2cea');
