SET @resolved_slug=IF(@slug_conflict IS NULL,'muqayasa-samini-lula-nakh-dar-90-ml-sabit-sistema-nobar-tip-qatra','muqayasa-samini-lula-nakh-dar-90-ml-sabit-sistema-nobar-tip-qatra-prod-036-iraq');
