SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='taqqoso-i-lula-90mm-systema-ha' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'taqqoso-i-lula-90mm-systema-ha','taqqoso-i-lula-90mm-systema-ha-prod-036-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
