SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='mukammal-guide-tip-irrigation-sugar-cane-water-use-optimization' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'mukammal-guide-tip-irrigation-sugar-cane-water-use-optimization','mukammal-guide-tip-irrigation-sugar-cane-water-use-optimization-prod-044-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'mukammal-guide-tip-irrigation-sugar-cane-water-use-optimization-prod-044-tj-c3ad5029');
