SET @resolved_slug=IF(@slug_conflict IS NULL,'mutalif-chennakiridan-dast160','mutalif-chennakiridan-dast160-prod-061-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'mutalif-chennakiridan-dast160-prod-061-tj-cd668f37');
