SET @resolved_slug=IF(@slug_conflict IS NULL,'comparison-110mm-threaded-pipes-drip-irrigation-systems','comparison-110mm-threaded-pipes-drip-irrigation-systems-prod-068-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'comparison-110mm-threaded-pipes-drip-irrigation-systems-prod-068-en-e7eea28b');
