SET @resolved_slug=IF(@slug_conflict IS NULL,'mukoyisai-lulay-i-nakhkori-110mm-oibaqatav-vonav','mukoyisai-lulay-i-nakhkori-110mm-oibaqatav-vonav-prod-068-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'mukoyisai-lulay-i-nakhkori-110mm-oibaqatav-vonav-prod-068-tj-58b60670');
