SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='selecting-measuring-125mm-threaded-pipes-farms' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'selecting-measuring-125mm-threaded-pipes-farms','selecting-measuring-125mm-threaded-pipes-farms-prod-071-en');
