SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='installing-110mm-rigid-pvc-pipes-drip-irrigation' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'installing-110mm-rigid-pvc-pipes-drip-irrigation','installing-110mm-rigid-pvc-pipes-drip-irrigation-prod-075-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'installing-110mm-rigid-pvc-pipes-drip-irrigation-prod-075-en-caff8a5c');
