SET @resolved_slug=IF(@slug_conflict IS NULL,'komil-dasturi-andozakuniji-naskukuoni-lula-hai-girhdoni-110-milimetr-chukura-shitob','komil-dasturi-andozakuniji-naskukuoni-lula-hai-girhdoni-110-milimetr-chukura-shitob-prod-080-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'komil-dasturi-andozakuniji-naskukuoni-lula-hai-girhdoni-110-milimetr-chukura-shitob-prod-080-tj-943aa2ce');
