SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='khossu-siaathi-tekhniki-lola-125-mm-rakh-rahnamae-intikhib' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
