SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='tahlil-i-makhsumsi-juli-75-mm-baresmon' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'tahlil-i-makhsumsi-juli-75-mm-baresmon','tahlil-i-makhsumsi-juli-75-mm-baresmon-prod-091-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'tahlil-i-makhsumsi-juli-75-mm-baresmon-prod-091-tj-db4d0bdb');
