SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='110mm-ribbed-irrigation-pipe-buyers-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'110mm-ribbed-irrigation-pipe-buyers-guide','110mm-ribbed-irrigation-pipe-buyers-guide-prod-103-en');
