SET @resolved_slug=IF(@slug_conflict IS NULL,'arziishi-naahyi-daraz-90-millimetri-dar-moliron-takhmini-daqqi-broj-ubori','arziishi-naahyi-daraz-90-millimetri-dar-moliron-takhmini-daqqi-broj-ubori-prod-110-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'arziishi-naahyi-daraz-90-millimetri-dar-moliron-takhmini-daqqi-broj-ubori-prod-110-tj-a04ced6b');
