SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='75mm-threaded-pipe-drip-micro-irrigation-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'75mm-threaded-pipe-drip-micro-irrigation-guide','75mm-threaded-pipe-drip-micro-irrigation-guide-prod-112-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
