SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='muvoqiqati-joyi-past-75mm-qatraindoz' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'muvoqiqati-joyi-past-75mm-qatraindoz','muvoqiqati-joyi-past-75mm-qatraindoz-prod-112-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'muvoqiqati-joyi-past-75mm-qatraindoz-prod-112-tj-89657788');
