SET @resolved_slug=IF(@slug_conflict IS NULL,'osori-chulakii-vaidorakunii-hok-ravonishi-kumush-baroi-bahtarakar-dani-istifodabarai-ob','osori-chulakii-vaidorakunii-hok-ravonishi-kumush-baroi-bahtarakar-dani-istifodabarai-ob-strat-013-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'osori-chulakii-vaidorakunii-hok-ravonishi-kumush-baroi-bahtarakar-dani-istifodabarai-ob-strat-013-tj-03d027e5');
