SET @resolved_slug=IF(@slug_conflict IS NULL,'rahbariyaati-ommatoni-tasmi-konveyer-ozmoishi-timer-sensor-nami','rahbariyaati-ommatoni-tasmi-konveyer-ozmoishi-timer-sensor-nami-strat-016-tj');
