SET @resolved_slug=IF(@slug_conflict IS NULL,'reducing-water-stress-farms-teflon-strip-strategic-irrigation-guide','reducing-water-stress-farms-teflon-strip-strategic-irrigation-guide-strat-019-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'reducing-water-stress-farms-teflon-strip-strategic-irrigation-guide-strat-019-en-7b973680');
