SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='drip-line-cost-per-hectare-2025-estimate-key-considerations' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'drip-line-cost-per-hectare-2025-estimate-key-considerations','drip-line-cost-per-hectare-2025-estimate-key-considerations-strat-024-en');
