SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='arzoyi-hamrai-tib-1-hektar-2026' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'arzoyi-hamrai-tib-1-hektar-2026','arzoyi-hamrai-tib-1-hektar-2026-strat-024-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'arzoyi-hamrai-tib-1-hektar-2026-strat-024-tj-b174e41e');
