START TRANSACTION;
SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:strat-027' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:strat-027:en-US' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='iran-drip-irrigation-market-2026-trends' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'iran-drip-irrigation-market-2026-trends','iran-drip-irrigation-market-2026-trends-strat-027-en');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'iran-drip-irrigation-market-2026-trends-strat-027-en-801b87fa');
