SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='drip-irrigation-future-iran-agriculture-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@slug_conflict IS NULL,'drip-irrigation-future-iran-agriculture-guide','drip-irrigation-future-iran-agriculture-guide-strat-028-en');
