SET @resolved_slug=IF(@slug_conflict IS NULL,'obii-hasilonokii-ramondiqa-roadmap-farmers','obii-hasilonokii-ramondiqa-roadmap-farmers-strat-028-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'obii-hasilonokii-ramondiqa-roadmap-farmers-strat-028-tj-1e65321f');
