SET @resolved_slug=IF(@slug_conflict IS NULL,'khidmatrasoni-bad-forexi-lentay-chopi-rayhnamo-baroy-samaranokiyi-uustovor','khidmatrasoni-bad-forexi-lentay-chopi-rayhnamo-baroy-samaranokiyi-uustovor-strat-029-tj');
SET @resolved_conflict=(SELECT ID FROM `ha_posts` WHERE post_name=@resolved_slug AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @resolved_slug=IF(@resolved_conflict IS NULL,@resolved_slug,'khidmatrasoni-bad-forexi-lentay-chopi-rayhnamo-baroy-samaranokiyi-uustovor-strat-029-tj-cd9526f2');
